const webhookItem = $('Webhook WhatsApp').first().json;
const data = webhookItem.body.data;

if (data.key?.fromMe === true) {
  return [];
}

// Mensagem repetida: a Evolution reentrega a mesma mensagem (mesmo id) enquanto o fluxo não responde, por exemplo na
// foto do laudo, que leva mais de 1 minuto. "BD · Buscar usuários" grava o id e marca _nova = false na reentrega.
if ($input.all().some((i) => i.json._nova === false)) {
  return [];
}

const msgTimestamp = data.messageTimestamp;
const nowSeconds = Math.floor(Date.now() / 1000);
const MAX_AGE_SECONDS = 600;
if (msgTimestamp && (nowSeconds - msgTimestamp) > MAX_AGE_SECONDS) {
  return [];
}

const audio = data.message.audioMessage;
const imagem = data.message.imageMessage;
// Pre-tratamento da fala/ditado: conserta o que a transcricao (ou o teclado de voz) costuma errar,
// SEM IA, antes das regexes dos comandos. So mexe em texto com cara de fala; comando ja certo passa igual.
// Devolve o texto original quando nada precisa mudar.
// Fabricas travadas (so estas seis), navios "Orange X" e tanques de navio por extenso.
function resolverFabrica(entrada) {
  const SIGLAS = ['AQA', 'CON', 'COL', 'UCH', 'ITA', 'TMG'];
  const NOMES = { ARARAQUARA: 'AQA', CONCHAL: 'CON', COLINA: 'COL', UCHOA: 'UCH', ITAPOLIS: 'ITA', TERMINALGUARUJA: 'TMG', TERMINALDOGUARUJA: 'TMG', GUARUJA: 'TMG' };
  // leituras tortas conhecidas (letra de mao e transcricao): o Q de AQA vira "OQ", "0", "K"...
  const TORTAS = { AOQ: 'AQA', AOQA: 'AQA', AOA: 'AQA', AKA: 'AQA', A0A: 'AQA', AQ0: 'AQA', AQ4: 'AQA', AO4: 'AQA', A04: 'AQA' };
  const s = String(entrada || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (SIGLAS.includes(s)) return { sigla: s, corrigida: false };
  if (NOMES[s]) return { sigla: NOMES[s], corrigida: false };
  if (TORTAS[s]) return { sigla: TORTAS[s], corrigida: true, lido: String(entrada).trim() };
  if (s.length !== 3) return null;
  // mesma quantidade de letras e TODA letra diferente e uma confusao conhecida (O/0, I/L/1, N/H/M, U/V...)
  const GRUPOS = [['O', '0', 'Q', 'D'], ['I', 'L', '1'], ['N', 'M', 'H'], ['U', 'V'], ['C', 'G'], ['T', '7'], ['A', '4'], ['B', '8']];
  const confunde = (a, b) => GRUPOS.some((g) => g.includes(a) && g.includes(b));
  const candidatas = SIGLAS.filter((g) => {
    let dif = 0;
    for (let i = 0; i < 3; i++) {
      if (s[i] === g[i]) continue;
      if (!confunde(s[i], g[i])) return false;
      dif++;
    }
    return dif >= 1 && dif <= 2;
  });
  // so corrige com uma unica candidata (empate: nao adivinha)
  if (candidatas.length === 1) return { sigla: candidatas[0], corrigida: true, lido: String(entrada).trim() };
  return null;
}
const FABRICAS_VALIDAS = 'AQA (Araraquara), CON (Conchal), COL (Colina), UCH (Uchoa), ITA (Itapólis) ou TMG (Terminal Guarujá)';

function normalizarFala(original) {
  let t = String(original || '');
  if (!t) return t;
  const sem = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

  // so entra em acao se o texto tem cara de fala ou de ditado
  const temCara = /\b(zero|menor|maior|lod|ente|ate|abaixo|acima|virgula|orange|araraquara|conchal|uchoa|itapolis|guaruja)\b|\b\d{1,2}\s*(center|centro|central|port|bombordo|ps|starboard|boreste|sb)\b|\bfabrica\s+(?:d[aeo]\s+)?colina\b|\b(load|item|lotes?|fabrica|navio|linha|fase|amostras?)\s*,\s*\d|\b(load|item)\s+\d{1,3},\d{3}\b|\bdeu\s+[<>=]?\d+(?:[.,]\d+)?\s+lotes?\b|\blotes?\s+\d+\s+a\s+\d+|\b(load|item)\s+\d{1,3}\s\d{3}\b|\b(um|uma|dois|duas|tres|quatro|cinco|seis|sete|oito|nove|dez|onze|doze|treze|quatorze|catorze|quinze|dezesseis|dezessete|dezoito|dezenove|vinte|trinta|quarenta|cinquenta|sessenta|setenta|oitenta|noventa|cem|cento|duzentos|trezentos|quatrocentos|quinhentos|seiscentos|setecentos|oitocentos|novecentos)\b|^(leitura|resultado)s?\b|\blotes?\s+\d+(\s+(e\s+)?\d+){1,}\b/.test(sem(t));
  if (!temCara) return original;

  // 0) a transcricao as vezes poe virgula depois de cada palavra ('load, 46,699, fabrica AQA') e separador de milhar
  t = t.replace(/\b(load|item|lotes?|f[aá]brica|navio|linha|fase|amostras?)\s*,\s*(?=\d)/gi, '$1 ');
  t = t.replace(/\b(load|item)\s+(\d{1,3}),(\d{3})\b/gi, '$1 $2$3');

  // 1) palavras de numero -> algarismos (cento e vinte = 120); "um/uma" so depois de lote, amostra, tanque, deu...
  const U = { zero: 0, um: 1, uma: 1, dois: 2, duas: 2, tres: 3, quatro: 4, cinco: 5, seis: 6, sete: 7, oito: 8, nove: 9 };
  const D = { dez: 10, onze: 11, doze: 12, treze: 13, quatorze: 14, catorze: 14, quinze: 15, dezesseis: 16, dezessete: 17, dezoito: 18, dezenove: 19 };
  const T = { vinte: 20, trinta: 30, quarenta: 40, cinquenta: 50, sessenta: 60, setenta: 70, oitenta: 80, noventa: 90 };
  const H = { cem: 100, cento: 100, duzentos: 200, trezentos: 300, quatrocentos: 400, quinhentos: 500, seiscentos: 600, setecentos: 700, oitocentos: 800, novecentos: 900 };
  const tipo = (w) => (w in H ? 'H' : w in T ? 'T' : w in D ? 'D' : w in U ? 'U' : null);
  const valor = (w) => H[w] ?? T[w] ?? D[w] ?? U[w];
  const partes = t.split(/(\s+)/);                       // palavras e espacos
  const out = [];
  for (let i = 0; i < partes.length; i++) {
    const p = partes[i];
    const w = sem(p).replace(/[.,;:!?]+$/, '');
    const pontuacao = (p.match(/[.,;:!?]+$/) || [''])[0];
    if (!tipo(w)) { out.push(p); continue; }
    if ((w === 'um' || w === 'uma') && !/\b(lotes?|amostras?|tanques?|deu|foi|item|composta|load)\s*$/.test(sem(out.join('')))) { out.push(p); continue; }
    // acumula a sequencia valida: H? T? (U|D)? com "e" entre as partes
    let soma = valor(w), ordem = { H: 3, T: 2, D: 1, U: 1 }[tipo(w)], ultimo = i, usouFim = tipo(w) === 'D' || tipo(w) === 'U', temPont = pontuacao !== '';
    let j = i + 1;
    while (!temPont && j + 1 < partes.length + 1) {
      // espaco, "e", espaco, palavra  OU  espaco, palavra
      let k = j, ehE = false;
      if (partes[k] && /^\s+$/.test(partes[k]) && partes[k + 1] && sem(partes[k + 1]) === 'e' && partes[k + 2] && /^\s+$/.test(partes[k + 2])) { ehE = true; k += 3; } else if (partes[k] && /^\s+$/.test(partes[k])) { k += 1; } else break;
      const prox = partes[k]; if (!prox) break;
      const pw = sem(prox).replace(/[.,;:!?]+$/, ''); const pt = tipo(pw);
      if (!pt || pt === 'H' && ordem <= 3 && soma % 100 !== 0) break;
      const o = { H: 3, T: 2, D: 1, U: 1 }[pt];
      // "cento e vinte": so junta com "e" (ou direto, entre dezena e unidade); nao junta dois numeros soltos ("nove dez")
      if (o >= ordem || usouFim || (!ehE && !(pt === 'U' && tipo(sem(partes[ultimo]).replace(/[.,;:!?]+$/, '')) === 'T'))) break;
      if (pw === 'zero') break;
      soma += valor(pw); ordem = o; usouFim = pt === 'D' || pt === 'U'; ultimo = k; j = k + 1;
      if (/[.,;:!?]+$/.test(prox)) { temPont = true; }
    }
    const pontFinal = (partes[ultimo].match(/[.,;:!?]+$/) || [''])[0];
    out.push(String(soma) + pontFinal);
    i = ultimo;
  }
  t = out.join('');

  // 2) "menor que 10" -> "<10", "maior que 50" -> ">50"
  t = t.replace(/\b(?:menor(?:\s+(?:que|do\s+que))?|abaixo\s+de|menos\s+de)\s+(\d+(?:[.,]\d+)?)/gi, '<$1');
  t = t.replace(/\b(?:maior(?:\s+(?:que|do\s+que))?|acima\s+de|mais\s+de)\s+(\d+(?:[.,]\d+)?)/gi, '>$1');
  // 3) "8 virgula 5" -> "8,5"
  t = t.replace(/(\d)\s+v[ií]rgula\s+(\d)/gi, '$1,$2');
  // 4) faixas faladas: "lotes 11 a 16" -> "lotes 11-16"
  t = t.replace(/\b(lotes?|amostras?)\s+(\d+)\s+(?:a|at[eé])\s+(\d+)\b/gi, '$1 $2-$3');
  // 5) erros comuns da transcricao
  t = t.replace(/\blod\b/gi, 'load');
  t = t.replace(/\b(load|item)\s+(\d{1,3})\s(\d{3})\b/gi, '$1 $2$3');                       // "43 699"
  t = t.replace(/\b(f[aá]brica\s+\w+\s+)ente(\s+\d{3,4})\b/gi, '$1item$2');                   // "ente 2655"
  // 5b) fabricas travadas: o nome da cidade vira a sigla (a sigla torta e conferida/corrigida no comando, que avisa)
  t = t.replace(/\b(f[aá]brica\s+)(?:d[aeo]\s+)?(terminal\s+(?:d[aeo]\s+)?guaruj[aá]|guaruj[aá]|araraquara|conchal|colina|uchoa|it[aá]p[oó]lis)(?![A-Za-zÀ-ÿ0-9])/gi, (m, pre, nome) => pre + resolverFabrica(nome).sigla);
  // 5c) navio "Orange Sky" vira O.SKY; tanque de navio por extenso: 1 center = 1C, 1 port/1PS = 1P, 1 starboard = 1S
  t = t.replace(/\borange\s+([A-Za-z]+)/gi, (m, w) => 'O.' + w.toUpperCase());
  t = t.replace(/\b(\d{1,2})\s*(?:center|centro|central)\b/gi, '$1C')
       .replace(/\b(\d{1,2})\s*ps\b/gi, '$1P, $1S')
      .replace(/\b(\d{1,2})\s*(?:port(?:\s*side)?|bombordo)\b/gi, '$1P')
       .replace(/\b(\d{1,2})\s*(?:starboard|boreste|sb)\b/gi, '$1S');
  t = t.replace(/\b(\d{1,2}[CPSAF])\s+e\s+(?=\d{1,2}[CPSAF]\b)/gi, '$1, ');   // '1C e 2P' -> '1C, 2P'
  // 6) lista de lotes dita com espacos ou "e": "lotes 35 36 37 e 38" -> "lotes 35,36,37,38"
  t = t.replace(/\blotes\s+(\d{1,3}(?:\s*(?:,|\se\s|\s)\s*\d{1,3})+)(?=\s|[.,;]|$)(?!\s*-)/gi, (m, lista) => 'lotes ' + lista.split(/\s*,\s*|\s+e\s+|\s+/).filter(Boolean).join(','));

  // 7) ditado de contagens (C.T / B.L): "Leitura do CT do lote 43668. Lote 3 menor que 10, lote 4 20 ..."
  const cab = t.match(/^\s*(?:(?:leitura|resultados?)\s+(?:do|da|de|dos|das)?\s*)?(ct|c\.?\s?t\.?|bl\s?72|bl\s?120|bl|b\.?\s?l\.?(?:\s?(?:72|120))?)[\s,]+(?:(?:do|da|de)\s+)?(?:load|lote)\s+(\d{4,6})\b[\s.,:;]*(.*)$/is);
  if (cab) {
    const an = sem(cab[1]).replace(/[.\s]/g, '');
    let resto = cab[3]
      .replace(/\bdata\s+\d{1,2}\/\d{1,2}\/\d{2,4}\.?\s*$/i, '')            // a data da leitura nao entra no comando
      .trim();
    const clausulas = resto.split(/\s*[.;]\s*|\s*,\s+(?=lotes?\b)|(?<=\d)\s+(?=lotes?\b)/i).map((c) => c.trim().replace(/[.,;]+$/, '')).filter(Boolean);
    const norm = clausulas.map((c) => {
      const m = c.match(/^(lotes?)\s+([\d,\-\s]+?)\s+(?:(?:deu|foi|=)\s+)?([<>]?\s*\d+(?:[.,]\d+)?)$/i);
      if (m) return `${m[1].toLowerCase()} ${m[2].replace(/\s+/g, '')} deu ${m[3].replace(/\s+/g, '')}`;
      return c.replace(/^(lotes?\s+[\d,\-]+)\s+deu\s+([<>]?\s*\d+(?:[.,]\d+)?)$/i, (x, a, b) => `${a} deu ${b.replace(/\s+/g, '')}`);
    });
    t = `${an} load ${cab[2]} ${norm.join(', ')}`.trim();
  }
  // 8) recebimento/embarque ditados: tira a virgula que a fala poe antes de cada palavra-chave
  if (/^\s*(recebimento|embarque)\b/i.test(t)) {
    // na fala vem 'fabrica AQA item 2655'; o comando oficial e 'item 2655 fabrica AQA'
    t = t.replace(/\b(f[aá]brica\s+[a-z0-9]+)\s*[,.]?\s+(item\s+\d{3,4})\b/i, '$2 $1');
    t = t.replace(/^(\s*(?:recebimento|embarque))\s*[,.:]/i, '$1').replace(/\s*,\s*(?=(?:load|f[aá]brica|item|lotes?|navio|linha|fase|amostras?|data)\b)/gi, ' ').replace(/[.,;]+\s*$/, '');
  }
  return t.replace(/\s+/g, ' ').trim();
}

// As regexes dos comandos (e a IA) leem o texto ja tratado: "menor que 10" vira <10, "lotes 11 a 16" vira
// 11-16, "Lod 43 699" vira load 43699, números por extenso viram algarismos etc. Comando já certo passa igual.
const textoOriginal = data.message.conversation || '';
const texto = normalizarFala(textoOriginal);
const numeroRemetente = data.key.remoteJid;
const nomeContato = data.pushName || 'Desconhecido';

// --- Carrega usuários da planilha e identifica o nível de quem enviou ---
const usuarios = $input.all().map(i => i.json);
const numeroRemetenteLimpo = numeroRemetente.replace('@s.whatsapp.net', '');
const usuarioAtual = usuarios.find(u => String(u.Numero) === numeroRemetenteLimpo);
const nivelAtual = usuarioAtual ? usuarioAtual.Nivel : 'Desconhecido';
// --- BLOQUEIO: só usuários cadastrados podem usar o bot ---
if (nivelAtual === 'Desconhecido') {
  return [{
    json: {
      tipo: 'nao_cadastrado',
      numero: numeroRemetente,
      nomeContato,
      textoResposta: '❌ Você ainda não está cadastrado no LabFlow. Peça a um administrador para te cadastrar.'
    }
  }];
}
// Sinaliza se o nome do WhatsApp de quem mandou mudou (ou nunca foi
// preenchido) em relação ao que já está salvo na USUARIOS — só pra quem
// já é cadastrado (nunca cria cadastro novo por essa via).
const sincronizarNome = !!(usuarioAtual && usuarioAtual.Nome !== nomeContato);

// Toda resposta passa por aqui, pra sempre levar junto os dados de
// sincronização de nome sem precisar repetir em cada bloco abaixo.
// Cargo Coletor: só registra coleta e corrige/apaga a própria coleta (e vê a ajuda). Qualquer outro comando é barrado aqui.
const TIPOS_COLETOR = new Set(['coleta_terra', 'coleta_navio', 'coleta_corrigir', 'erro_coleta', 'erro_ia', 'interpretar_ia',
  'audio_transcrever', 'confirmar_pendencia', 'cancelar_pendencia', 'nao_cadastrado']);
const MSG_COLETOR = '❌ O seu cargo (Coletor) permite só registrar coletas e corrigir as suas próprias coletas. Escreva *comandos* para ver como.';
function output(json) {
  if (nivelAtual === 'Coletor' && json && json.tipo && !TIPOS_COLETOR.has(json.tipo)) {
    json = { tipo: 'erro_coleta', numero: json.numero || numeroRemetente, nomeContato, textoResposta: MSG_COLETOR };
  }
  return [{
    json: {
      ...json,
      _sincronizarNome: sincronizarNome,
      _numeroRemetenteLimpo: numeroRemetenteLimpo,
      _nomeContatoAtual: nomeContato,
      _nivelAtual: nivelAtual
    }
  }];
}
// --- FOTO de laudo: a IA de visão lê, o código valida e o bot pede um "sim" para a lista de comandos ---
if (imagem && !texto) {
  if (nivelAtual === 'Consultor') {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Consultores têm acesso somente de consulta. Peça a um administrador para registrar isso.' });
  }
  return output({ tipo: 'foto_ler', mensagemId: data.key.id, legenda: String(imagem.caption || '').slice(0, 300),
    hoje: new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente, nomeContato, nivelAtual });
}
// --- ÁUDIO: o Gemini transcreve e o texto volta reenviado (labflowAudio); até 1 minuto ---
if (audio && !texto) {
  if ((Number(audio.seconds) || 0) > 60) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '🎤 Áudio muito longo (máximo 1 minuto). Mande um comando por áudio.' });
  }
  return output({ tipo: 'audio_transcrever', mensagemId: data.key.id, segundos: Number(audio.seconds) || 0,
    numero: numeroRemetente, nomeContato });
}
// Texto transcrito de um áudio: vai direto para a IA, que sempre pede "sim" antes de gravar (a regex
// gravaria alguns comandos sem perguntar, e a transcrição pode errar). "sim" e "não" falados seguem normais.
if (webhookItem.body.labflowAudio === true && !/^(sim|n[aã]o)[.!]?$/i.test(texto.trim())) {
  // Fala já virou um comando completo (C.T/B.L, recebimento, compostas)? Não precisa de IA: segue como se a IA
  // tivesse devolvido esse comando (o Validar classifica e continua pedindo "sim" antes de gravar).
  const normCmd = texto.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
  const comandoPronto =
    /^(ct|cts|bls?|bl ?72|bl ?120) (load \d{4,6}|navio [^,]+ linha \d+ fase \d+) ((lotes?|amostras?) [\d,\-]+ deu [<>=]?\d+([.,]\d+)?(, )?)+$/.test(normCmd) ||
    /^recebimento load \d{4,6} item \d{3,4} fabrica [a-z0-9]+ lotes [\d,\-]+( data \d{2}\/\d{2}\/\d{4})?$/.test(normCmd) ||
    /^compostas do load \d{4,6}( item \d{3,4})? (\(\d[\d,\-]*\))+$/.test(normCmd);
  return output({ tipo: 'interpretar_ia', mensagem_original: texto, audio: true,
    ia_pronta: comandoPronto ? JSON.stringify({ intencao: 'comando', comando: texto.replace(/\s+/g, ' ').trim() }) : '',
    hoje: new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente, nomeContato, nivelAtual });
}
// Calcula as N linhas de análise (CT, BL, WORT) para um tanque, a partir
// da data em que o frasco (Normal ou Stress) foi analisado.
function calcularAnalises(dataAnaliseStr, idColeta, tanque, tipoFrasco, tipoTanque, navio) {
  const [dia, mes, ano] = dataAnaliseStr.split('/').map(Number);
  const dataBase = new Date(ano, mes - 1, dia);

  const formatarData = (d) =>
    `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;

  const somarHoras = (dataBase, horas) => {
    const d = new Date(dataBase);
    d.setHours(d.getHours() + horas);
    return d;
  };

  // Config: { pre: horas ou null, final: horas }
  const PRAZOS = {
    CT:   { pre: null, final: 48 },
    BL:   { pre: 72,   final: 120 },
    WORT: { pre: 120,  final: 240 }
  };

  // Cada linha: { subAnalise, metodo }
  const LINHAS = [
    { subAnalise: 'CT',   metodo: 'Profundidade' },
    { subAnalise: 'BL',   metodo: 'Profundidade' },
    { subAnalise: 'WORT', metodo: 'Profundidade' },
    { subAnalise: 'WORT', metodo: 'Superficie' }
  ];

  return LINHAS.map(({ subAnalise, metodo }, idx) => {
    const prazo = PRAZOS[subAnalise];
    const dataPreLeitura = prazo.pre !== null
      ? formatarData(somarHoras(dataBase, prazo.pre))
      : '';
    const dataLeituraFinal = formatarData(somarHoras(dataBase, prazo.final));
    const status = prazo.pre !== null
      ? 'Aguardando Pré-Leitura'
      : 'Aguardando Leitura Final';

    return {
      idAnalise: `AN-${idColeta}-${tipoFrasco}-${subAnalise}-${metodo}`.slice(0, 60),
      idColeta,
      tanque,
      tipoTanque,
      navio: navio || '',
      tipoFrasco,
      subAnalise,
      metodo,
      dataAnalise: dataAnaliseStr,
      dataPreLeitura,
      dataLeituraFinal,
      status,
      responsavel: nomeContato
    };
  });
}
// Calcula as 3 datas de drop (D5, D10, D15) a partir da data de coleta
function calcularDrops(dataColetaStr, idColeta, tanque, tipoTanque, navio) {
  const [dia, mes, ano] = dataColetaStr.split('/').map(Number);
  const dataBase = new Date(ano, mes - 1, dia);
  const dias = [5, 10, 15];
  return dias.map(offset => {
    const dataDrop = new Date(dataBase);
    dataDrop.setDate(dataDrop.getDate() + offset);
    const dd = String(dataDrop.getDate()).padStart(2, '0');
    const mm = String(dataDrop.getMonth() + 1).padStart(2, '0');
    const yyyy = dataDrop.getFullYear();
    return {
      idDrop: `DR-${idColeta}-${offset}`,
      idColeta: idColeta,
      tipoTanque: tipoTanque,
      tanque: tanque,
      navio: navio || '',
      diaDrop: `D${offset}`,
      dataPrevista: `${dd}/${mm}/${yyyy}`,
      status: 'Pendente',
      responsavel: nomeContato
    };
  });
}
function calcularArquivo(dataColetaStr, idColeta, tanque, navio) {
  const [dia, mes, ano] = dataColetaStr.split('/').map(Number);
  const dataColeta = new Date(ano, mes - 1, dia);
  const dataDescarte = new Date(dataColeta);
  dataDescarte.setDate(dataDescarte.getDate() + 365);

  const formatarData = (d) =>
    `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;

  return {
    id: `AR-${idColeta}`,
    idColeta,
    tanque,
    navio: navio || '',
    dataColeta: dataColetaStr,
    dataDescarte: formatarData(dataDescarte),
    status: 'Arquivado',
    responsavel: nomeContato
  };
}
