// corrigir coleta tanque terra 42 para 43 [data dd/mm/aaaa]  |  corrigir coleta navio O.SKY 123 tanque 1C para 2C [data ...]
// apagar coleta tanque terra 42 [data ...]  |  apagar coleta navio O.SKY 123 tanque 1C [data ...]
// Sem a data vale a coleta mais recente desse tanque (últimos 7 dias). Só quem registrou (ou Admin/Analista) altera.
{
  const D = '(?:\\s+data\\s+(\\d{2}\\/\\d{2}\\/\\d{4}))?$';
  const mCT = ajudaBusca.match(new RegExp('^(?:corrigir|alterar|trocar)\\s+coleta\\s+(?:do\\s+)?tanque\\s+(?:de\\s+)?terra\\s+(\\w+)\\s+(?:para|por)\\s+(?:o\\s+)?(\\w+)' + D));
  const mCN = ajudaBusca.match(new RegExp('^(?:corrigir|alterar|trocar)\\s+coleta\\s+(?:do\\s+)?navio\\s+(.+?)\\s+tanque\\s+(\\w+)\\s+(?:para|por)\\s+(?:o\\s+)?(\\w+)' + D));
  const mAT = ajudaBusca.match(new RegExp('^(?:apagar|cancelar|remover|excluir)\\s+coleta\\s+(?:do\\s+)?tanque\\s+(?:de\\s+)?terra\\s+(\\w+)' + D));
  const mAN = ajudaBusca.match(new RegExp('^(?:apagar|cancelar|remover|excluir)\\s+coleta\\s+(?:do\\s+)?navio\\s+(.+?)\\s+tanque\\s+(\\w+)' + D));
  if (mCT || mCN || mAT || mAN) {
    const bloqueio = bloqueadoConsultor();
    if (bloqueio) return bloqueio;
    const m = mCT || mCN || mAT || mAN;
    const origem = (mCT || mAT) ? 'terra' : 'navio';
    const corrigir = !!(mCT || mCN);
    const navioC = origem === 'navio' ? m[1].trim().toUpperCase() : '';
    const tanqueC = String(origem === 'terra' ? m[1] : m[2]).toUpperCase();
    const novoC = corrigir ? String(origem === 'terra' ? m[2] : m[3]).toUpperCase() : '';
    const dataC = m[m.length - 1] || '';
    const tanqueOk = origem === 'terra' ? /^\d+$/ : /^\d+[A-Z]?$/;
    const erroC = (t) => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
    if (!tanqueOk.test(tanqueC) || (corrigir && !tanqueOk.test(novoC))) {
      return erroC('❌ Número de tanque inválido. ' + (origem === 'terra' ? 'Tanque de terra é só número (ex.: 42).' : 'Tanque de navio é número e uma letra (ex.: 1C).') + ' Nada foi alterado.');
    }
    if (corrigir && tanqueC === novoC) return erroC('❌ O tanque novo é igual ao antigo. Nada foi alterado.');
    return output({ tipo: 'coleta_corrigir', modo: corrigir ? 'corrigir' : 'apagar', origem, navio: navioC, tanque: tanqueC, novoTanque: novoC,
      dataColeta: dataC, ehGestor: (nivelAtual === 'Admin' || nivelAtual === 'Analista' || nivelAtual === 'Operador') ? '1' : '0', numero: numeroRemetente, nomeContato });
  }
}
