  const mCampo = ajudaBusca.match(new RegExp('^(?:corrigir|alterar|trocar)\\s+(?:o\\s+|a\\s+)?(item|fabrica)\\s+do\\s+load\\s+(\\d+)' + IT + '\\s+(?:para|por)\\s+(?:o\\s+|a\\s+)?(.+)$'));
  const mLote = ajudaBusca.match(new RegExp('^(?:corrigir|alterar|trocar)\\s+(?:o\\s+)?lote\\s+(\\d+)\\s+do\\s+load\\s+(\\d+)' + IT + '\\s+(?:para|por)\\s+(?:o\\s+)?(?:lote\\s+)?(\\d+)$'));
  const mData = ajudaBusca.match(new RegExp('^(?:corrigir|alterar|trocar)\\s+(?:a\\s+)?data\\s+do\\s+lote\\s+(\\d+)\\s+do\\s+load\\s+(\\d+)' + IT + '\\s+(?:para|por)\\s+(\\d{1,2})[\\/.\\-](\\d{1,2})(?:[\\/.\\-](\\d{4}|\\d{2}))?$'));
  const mApagar = ajudaBusca.match(new RegExp('^(?:apagar|cancelar|remover|excluir)\\s+(?:o\\s+)?lote\\s+(\\d+)\\s+do\\s+load\\s+(\\d+)' + IT + '$'));
  if (mLoad || mCampo || mLote || mData || mApagar) {
