      if (mLoad[1] === mLoad[3]) return erroR(igual);
      acao = 'load'; dados = { load: mLoad[1], item: mLoad[2], campos: { numero: mLoad[3] } };
    } else if (mCampo) {
      const valor = mCampo[4].trim();
      if (mCampo[1] === 'item') {
        if (!/^\d{1,6}$/.test(valor)) return erroR('❌ Item inválido: use só os números (ex.: 2503). Nada foi alterado.');
        dados = { load: mCampo[2], item: mCampo[3], campos: { item: valor } };
      } else {
        const fab = resolverFabrica(valor);
        if (!fab || fab.corrigida) return erroR('❌ Fábrica inválida. Use ' + FABRICAS_VALIDAS + '. Nada foi alterado.');
        dados = { load: mCampo[2], item: mCampo[3], campos: { fabrica: fab.sigla } };
      }
