    } else if (mLote) {
      if (mLote[1] === mLote[4]) return erroR(igual);
      acao = 'lote'; dados = { load: mLote[2], item: mLote[3], lote: Number(mLote[1]), campos: { lote: Number(mLote[4]) } };
