      const iso = aa + '-' + mm + '-' + dd;
      const dt = new Date(iso + 'T12:00:00Z');
      if (isNaN(dt) || dt.toISOString().slice(0, 10) !== iso) return erroR('❌ Data inválida (dia/mês/ano). Nada foi alterado.');
      acao = 'lote'; dados = { load: mData[2], item: mData[3], lote: Number(mData[1]), campos: { data_recebimento: iso } };
