// "coletado por Joyce": quem coletou quando NAO foi quem mandou a mensagem ("coletado por mim" ou sem nome = quem mandou)
function extrairColetadoPor(txt) {
  const m = txt.match(/\s*,?\s*\bcoletad[oa]s?\s+(?:por|pel[oa])\s+(.+?)(?=\s+data\s+\d{2}\/\d{2}\/\d{4}|\s*$)/i);
  if (!m) return { texto: txt, nome: '' };
  const limpo = txt.replace(m[0], ' ').replace(/\s+/g, ' ').trim();
  const bruto = m[1].replace(/[.,;:!?]+$/, '').trim();
  if (/^(mim|eu|me)$/i.test(bruto)) return { texto: limpo, nome: '' };
  if (bruto.length > 40 || !/^\p{L}+(?:['. -]?\p{L}+)*\.?$/u.test(bruto)) {
    return { texto: limpo, erro: '❌ Não entendi o nome de quem coletou. Escreva só o nome, ex.: "coletado por Joyce". Nada foi gravado.' };
  }
  const particulas = new Set(['de', 'da', 'do', 'dos', 'das', 'e']);
  const nome = bruto.split(/\s+/).map((p, i) => (i > 0 && particulas.has(p.toLowerCase()) ? p.toLowerCase() : p.toLowerCase().replace(/(^|['-])(\p{L})/gu, (_, x, y) => x + y.toUpperCase()))).join(' ');
  return { texto: limpo, nome };
}
