// --- NFC PLACA A PLACA (C.T, B.L e WORT dos tanques) e REPETIÇÃO (reanálise) ---
// Análise do comando: ct (C.T 48h), bl72, bl120 (bl sozinho = bl120), wort profundidade|superficie 120h|240h
function analiseNfc(txt) {
  let m = txt.match(/\bwort\s+(profundidade|superficie)\s+(120|240)\s*h?\b/);
  if (m) return { sub: 'WORT', metodo: m[1] === 'superficie' ? 'Superficie' : 'Profundidade', etapa: m[2] === '120' ? 'pre' : 'final',
    rotulo: `WORT ${m[1] === 'superficie' ? 'Superfície' : 'Profundidade'} ${m[2]}h` };
  if (/\bbl\s*72\s*h?\b/.test(txt)) return { sub: 'BL', metodo: 'Profundidade', etapa: 'pre', rotulo: 'B.L 72h' };
  if (/\bbl(\s*120\s*h?)?\b/.test(txt)) return { sub: 'BL', metodo: 'Profundidade', etapa: 'final', rotulo: 'B.L 120h' };
  if (/\bc\.?t(\s*48\s*h?)?\b/.test(txt)) return { sub: 'CT', metodo: 'Profundidade', etapa: 'final', rotulo: 'C.T 48h' };
  return null;
}
const FRASCO = { normal: 'Normal', stress: 'Stress' };

// Repetição (ou reanálise): só para tanque com desvio aberto. Nunca vira análise nova (vem antes do
// registro de análise). Ex.: "repetição do tanque 47 stress bl120" / "reanálise do tanque 47"
if (/^(?:repeticao|reanalise|re-analise)\b/.test(ajudaBusca)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const mT = ajudaBusca.match(/\btanques?\s+([a-z0-9]+)/);
  if (!mT) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Diga o tanque da repetição. Ex.: repetição do tanque 47 stress bl120' });
  }
  const an = analiseNfc(ajudaBusca.replace(/\btanques?\s+[a-z0-9]+/, ' '));
  const mN = ajudaBusca.match(/\bnavio\s+(.+?)(?=\s+(?:normal|stress|ct|c\.t|bl\d*|wort|data|coleta)\b|\s*,|$)/);
  const mF = ajudaBusca.match(/\b(normal|stress)\b/);
  return output({ tipo: 'repeticao_nfc', tanque: mT[1].toUpperCase(), navio: mN ? mN[1].trim().toUpperCase() : '',
    frasco: mF ? FRASCO[mF[1]] : '', sub: an ? an.sub : '', metodo: an ? an.metodo : '', etapa: an ? an.etapa : '',
    rotulo: an ? an.rotulo : '', numero: numeroRemetente, nomeContato });
}

// 3 placas na ordem da bancada: 0 e <1 = "<1"; ">300" = incontável. Devolve a lista ou o texto do erro.
function lerTresPlacas(txt) {
  const valores = String(txt).split(/\s*(?:,|\be\b)\s*/).filter(Boolean);
  if (valores.length !== 3) return 'Mande as 3 placas (triplicata), na ordem da bancada (0 ou <1 = sem colônia).';
  const placas = [];
  for (const [i, v] of valores.entries()) {
    const m = v.replace(/\s+/g, '').match(/^([<>]?)(\d+)$/);
    if (!m) return 'Não entendi a placa "' + v + '". Use números, 0 ou <1 (sem colônia) e >300 (incontável).';
    const valor = Number(m[2]);
    if (m[1] === '<' && valor !== 1) return 'Placa sem colônia é *0* ou *<1*. Outros valores com "<" não valem.';
    placas.push(m[1] === '>' ? { placa: i + 1, sinal: '>', valor }
      : (valor === 0 || m[1] === '<') ? { placa: i + 1, sinal: '<', valor: 1 } : { placa: i + 1, sinal: '=', valor });
  }
  return placas;
}

// "Todos os tanques": a mesma leitura de todos os tanques que saem hoje (ou na data), sem crescimento (<1 nas 3 placas).
//   "bl todos os tanques navio O.SKY 123 deu <1"  ·  "ct todos os tanques terra de 17/10 deu <1"
//   "bl72 todos os tanques terra deu <1 exceto tanque 47 normal <1,1,0, tanque 48"
// Exceção com placas = o que deu naquele tanque e frasco; só o tanque (ou tanque + frasco) = fica de fora.
// Só entra a leitura que ainda não tem placas. Não abre desvio: o não ok volta com o comando pronto.
const matchTodosTanques = ajudaBusca.match(/^(c\.?t(?:\s*48)?|bl\s*72|bl\s*120|bl|wort\s+(?:profundidade|superficie)\s+(?:120|240))\s*h?\s+(?:d[eoa]s?\s+)?tod[oa]s\s+(?:os\s+)?tanques\b\s*(.*)$/);
if (matchTodosTanques) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const an = analiseNfc(matchTodosTanques[1]);
  const erroTodos = t => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
    textoResposta: '❌ ' + t + ' Nada foi gravado.\n\nEx.: bl todos os tanques navio O.SKY 123 deu <1 exceto tanque 1C normal <1,1,0' });
  let r = matchTodosTanques[2].trim();
  let navio = '';
  const mNavio = r.match(/^(?:d[oa]s?\s+)?navio\s+(.+?)(?=\s*,?\s+(?:que\s+(?:sa|vence)|d[eo]\s+(?:dia\s+)?(?:hoje|\d)|do\s+dia|hoje\b|deu\b|deram\b|ficou\b|ficaram\b|foi\b|=|<|0\b|sem\b|menor\b|menos\b|exceto\b|fora\b|com\s+excecao)|\s*$)/);
  if (mNavio) { navio = mNavio[1].replace(/\s+/g, ' ').trim().toUpperCase(); r = r.slice(mNavio[0].length).trim(); }
  else r = r.replace(/^(?:d[eoa]s?\s+)?terra\b\s*/, '');
  r = r.replace(/^,?\s*que\s+(?:sa(?:i|em)|vence(?:m)?)\s*/, '');
  let dataTodos = dataDaConsulta('hoje');
  let dataTxtTodos = '';
  const mData = r.match(/^,?\s*(?:d[eo]\s+(?:dia\s+)?|do\s+dia\s+|para\s+|pra\s+)?(hoje|\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)(?![\d\/])\s*/);
  if (mData) {
    dataTxtTodos = mData[1];
    dataTodos = dataDaConsulta(mData[1]);
    if (!dataTodos) return erroTodos('Data inválida: "' + mData[1] + '". Use dd/mm/aaaa.');
    r = r.slice(mData[0].length).trim();
  }
  const mValor = r.match(/^,?\s*(?:o\s+(?:c\.?t|bl|wort)\w*\s+)?(?:deu|deram|foi|foram|ficou|ficaram|=)?\s*(<\s*1|0|menor\s+que\s+(?:1|um)|menos\s+de\s+(?:1|um)|sem\s+crescimento|negativos?)(?![\d,.])\s*/);
  if (!mValor) {
    if (/^,?\s*(?:deu|deram|foi|foram|ficou|ficaram|=)?\s*[<>]?\s*\d/.test(r)) {
      return erroTodos('O "todos os tanques" só vale para sem crescimento (<1 nas 3 placas). Para um tanque com colônias, mande no "exceto" com as 3 placas, ou pelo comando de placas.');
    }
    return erroTodos('Diga o resultado: deu <1 (sem crescimento).');
  }
  r = r.slice(mValor[0].length).trim();
  const excecoes = [];
  if (r) {
    const mExc = r.match(/^,?\s*(?:exceto|menos|fora|com\s+excecao\s+d[oa]s?)\s+(.+)$/);
    if (!mExc) return erroTodos('Não entendi "' + r + '".');
    const partes = mExc[1].split(/\s*(?:,|;|\be\b)?\s*(?=\btanques?\s+[a-z0-9])/).map(s => s.trim()).filter(Boolean);
    for (const parte of partes) {
      const mLista = parte.match(/^tanques?\s+([a-z0-9]+(?:\s*(?:,|\be\b)\s*[a-z0-9]+)+)$/);
      if (mLista) {
        for (const t of mLista[1].split(/\s*(?:,|\be\b)\s*/).filter(Boolean)) excecoes.push({ tanque: t.toUpperCase(), frasco: '', placas: null });
        continue;
      }
      const mE = parte.match(/^tanques?\s+([a-z0-9]+)(?:\s+(normal|stress))?(?:\s*:?\s*(?:deu\s+)?([<>]?\s*\d+(?:\s*(?:,|\be\b)\s*[<>]?\s*\d+)*))?\s*$/);
      if (!mE) return erroTodos('Não entendi a exceção "' + parte + '". Use: exceto tanque 47 normal <1,1,0 (ou só exceto tanque 47 para deixar de fora).');
      if (mE[3] && !mE[2]) return erroTodos('No tanque ' + mE[1].toUpperCase() + ', diga o frasco (normal ou stress) antes das placas.');
      let placasE = null;
      if (mE[3]) {
        placasE = lerTresPlacas(mE[3]);
        if (typeof placasE === 'string') return erroTodos('Tanque ' + mE[1].toUpperCase() + ' ' + mE[2] + ': ' + placasE);
      }
      const chave = mE[1].toUpperCase() + '|' + (mE[2] ? FRASCO[mE[2]] : '');
      if (excecoes.some(x => x.tanque + '|' + x.frasco === chave)) return erroTodos('O tanque ' + mE[1].toUpperCase() + ' aparece duas vezes no "exceto".');
      excecoes.push({ tanque: mE[1].toUpperCase(), frasco: mE[2] ? FRASCO[mE[2]] : '', placas: placasE });
    }
  }
  return output({ tipo: 'placas_todos', ...an, navio, origem: navio ? 'navio' : 'terra', data: dataTodos, dataTxt: dataTxtTodos,
    excecoes, numero: numeroRemetente, nomeContato });
}

// Placas (triplicata): "ct do tanque 47 normal 12,8,15" / "bl72 do tanque 5 navio d.sky 123 stress 0,1,0 coleta 01/10/2026"
// 0 e <1 = "<1"; ">300" = incontável. Sempre as 3 placas, na ordem da bancada.
const matchPlacas = ajudaBusca.match(/^(c\.?t(?:\s*48)?|bl\s*72|bl\s*120|bl|wort\s+(?:profundidade|superficie)\s+(?:120|240))\s*h?\s+(?:d[oa]s?\s+)?tanques?\s+([a-z0-9]+)(?:\s+(?:do\s+)?navio\s+(.+?))?\s*,?\s+(normal|stress)\s*:?\s*([<>]?\s*\d+(?:\s*(?:,|\be\b)\s*[<>]?\s*\d+)*)(?:\s*,?\s*(?:data|coleta)(?:\s+da\s+coleta)?\s+(\d{2}\/\d{2}\/\d{4}))?$/);
