// --- CONCENTRADO: lista de lotes "1-5,7,9-10" -> [1,2,3,4,5,7,9,10] ---
function expandirLotes(texto) {
  const lotes = [];
  for (const parte of String(texto).split(',').map(p => p.trim()).filter(Boolean)) {
    const faixa = parte.match(/^(\d+)\s*-\s*(\d+)$/);
    if (faixa) {
      const ini = Number(faixa[1]), fim = Number(faixa[2]);
      if (ini < 1 || fim < ini || fim - ini > 200) return null;
      for (let n = ini; n <= fim; n++) lotes.push(n);
    } else if (/^\d+$/.test(parte) && Number(parte) > 0) {
      lotes.push(Number(parte));
    } else {
      return null;
    }
  }
  return lotes.length ? lotes : null;
}

// --- RECEBIMENTO NFC (item 129): load, fábrica, lote e, na observação, fresh/past e a diluição ---
// "recebimento nfc load 44300 fab aqa item 129 lote 10 past 10 elevado a 1, lote 10 fresh 10 elevado a 3 data 14/10/2026"
// O início "recebimento nfc" é opcional: "load 44300 fab aqa item 129 lote 10 past 10 elevado a 1" também vale.
const NFC_LISTA = '\\d+(?:\\s*-\\s*\\d+)?(?:\\s*(?:,|e)\\s*\\d+(?:\\s*-\\s*\\d+)?)*';
// a diluicao pode ser falada de varios jeitos: "10 elevado a 3", "10 elevado à terceira", "10 diluido a terceira", "10 à primeira", "10 a 3", "10^3", "diluicao 10 ao cubo"
const NFC_DIL = '(?:10\\s*(?:(?:elevad[oa]|diluid[oa])\\s*(?:(?:a|ao|na|no|em)\\s*)?|(?:a|ao|na|no|em)\\s+|potencia\\s*(?:de\\s*)?|expoente\\s*(?:de\\s*)?|exp\\.?\\s*|\\^\\s*|\\*\\*\\s*|(?=\\d(?!\\d)))(?:(?:expoente|potencia)\\s*(?:de\\s*)?)?(?:menos\\s*)?(-?\\d)|1\\s*[:/]\\s*(10{1,4})(?!\\d)|(?:dilui\\w*|dil\\.?)\\s*(?:de\\s+|em\\s+)?(\\d)(?!\\d))';
const NFC_GRUPO = new RegExp('lotes?\\s+(' + NFC_LISTA + ')\\s*,?\\s*(?:(?:do\\s+)?tipo\\s+|amostra\\s+)?(past|pasteurizad[oa]s?|fresh|fresc[oa]s?|in\\s+natura)\\s*[,;:]?\\s*(?:dilui\\w*\\s+(?:de\\s+)?)?' + NFC_DIL, 'g');
const nfcBusca = ajudaBusca
  .replace(/\bao\s+cubo\b|\bcubo\b/g, 'a 3').replace(/\bao\s+quadrado\b|\bquadrado\b/g, 'a 2')
  .replace(/\b(primeir[ao])\b/g, '1').replace(/\b(segund[ao])\b/g, '2').replace(/\b(terceir[ao])\b/g, '3').replace(/\b(quart[ao])\b/g, '4')
  .replace(/(\b10\s*(?:elevad[oa]|diluid[oa])?\s*(?:a|ao|na|no)\s+)(uma?|dois|duas|tres|quatro)\b/g,
    (_, pre, n) => pre + ({ um: 1, uma: 1, dois: 2, duas: 2, tres: 3, quatro: 4 })[n]);
const REGEX_NFC = /^(recebimento\s+nfc\s+)?(?:do\s+)?load\s+(\w+)\s*,?\s*fab(?:rica)?\s+([\w.\-]+)\s*,?\s*(?:item\s+(\w+)\s*,?\s*)?(lotes?\s+.+?)(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?\s*$/;
const TIPO_NFC = /\b(past|pasteuriz\w*|fresh|fresc[oa]s?|in\s+natura)\b/;
// varias linhas no mesmo comando (a foto manda assim): "recebimento nfc load 1 fab aqa lote 2 past 10 elevado a 1 ; load 3 fab col lote 4 fresh 10 elevado a 3"
// cada linha pode trazer no fim os resultados lidos no laudo (como saíram na placa; o banco multiplica pela diluição):
//   "... lote 10 past 10 elevado a 1 data 14/10/2026 resultados ct 14 bl72 22 bl120 <10" (é assim que a foto manda)
const RES_NFC = /\s*,?\s*resultados?\s*:?\s+((?:(?:ct|bl\s*72|bl\s*120|bl)\s*(?:deu\s*|=\s*)?[<>]?\s*\d+(?:[.,]\d+)?\s*(?:,|\be\b)?\s*)+)$/;
const resultadosDaLinha = (p) => {
  const m = p.match(RES_NFC);
  if (!m) return { linha: p, resultados: [] };
  const res = [...m[1].matchAll(/(ct|bl\s*72|bl\s*120|bl)\s*(?:deu\s*|=\s*)?([<>]?)\s*(\d+(?:[.,]\d+)?)/g)]
    .map((r) => ({ analise: nomeAnaliseCt(r[1]), sinal: r[2] || '=', valor: Number(r[3].replace(',', '.')) }));
  return { linha: p.slice(0, m.index), resultados: res };
};
const linhasNfc = nfcBusca.split(/\s*;\s*/).filter(Boolean).map(resultadosDaLinha);
const casosNfc = linhasNfc.map((x) => x.linha.match(REGEX_NFC));
if (casosNfc.length && casosNfc.every(Boolean) && (casosNfc[0][1] || TIPO_NFC.test(casosNfc[0][5]))) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const erroNfc = (t) => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  const exemploNfc = 'Ex.: recebimento nfc load 44300 fab aqa item 129 lote 10 past 10 elevado a 1';
  const hojeNfc = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  const porLoad = new Map();
  const fabricasLidas = [];
  for (const [iLinha, m] of casosNfc.entries()) {
    if (m[4] && m[4] !== '129') {
      return erroNfc('❌ O recebimento NFC é sempre o item 129 (você escreveu ' + m[4] + '). Nada foi gravado.');
    }
    const fabNfc = resolverFabrica(m[3]);
    if (!fabNfc) {
      return erroNfc('❌ Fábrica "' + m[3] + '" não reconhecida. Use ' + FABRICAS_VALIDAS + '. Nada foi gravado.');
    }
    if (fabNfc.corrigida) fabricasLidas.push({ lido: fabNfc.lido, sigla: fabNfc.sigla });
    const resto = m[5];
    const grupos = [...resto.matchAll(NFC_GRUPO)];
    const sobra = resto.replace(NFC_GRUPO, ' ').replace(/[\s,;]+|\be\b/g, '');
    if (!grupos.length || sobra) {
      return erroNfc('❌ Não entendi os lotes. Para cada lote diga o tipo (past ou fresh) e a diluição. ' + exemploNfc);
    }
    const vistosNfc = new Map();
    for (const g of grupos) {
      const lotesNfc = expandirLotes(g[1].replace(/\s+e\s+/g, ',').replace(/\s+/g, ''));
      if (!lotesNfc) return erroNfc('❌ Não entendi os lotes "' + g[1] + '". Use faixas e vírgulas, ex.: lotes 10-12 ou lotes 10,12.');
      const amostraNfc = /^past/.test(g[2]) ? 'past' : 'fresh';
      const diluicaoNfc = g[3] !== undefined ? Math.abs(Number(g[3])) : g[4] ? g[4].length - 1 : Number(g[5]);
      if (amostraNfc === 'past' && fabNfc.sigla !== 'AQA') {
        return erroNfc('❌ Só a AQA (Araraquara) tem amostra pasteurizada (past); as outras fábricas são fresh. Nada foi gravado.');
      }
      if (amostraNfc === 'past' ? diluicaoNfc !== 1 : (diluicaoNfc < 2 || diluicaoNfc > 4)) {
        return erroNfc('❌ Diluição fora do padrão: past é sempre 10 elevado a 1; fresh vai de 10 elevado a 2 até 10 elevado a 4 (você escreveu 10 elevado a ' + diluicaoNfc + ' em ' + amostraNfc + '). Nada foi gravado.');
      }
      for (const l of lotesNfc) {
        const k = l + '|' + amostraNfc;
        if (vistosNfc.has(k) && vistosNfc.get(k).diluicao !== diluicaoNfc) {
          return erroNfc('❌ O lote ' + l + ' (' + amostraNfc + ') apareceu com duas diluições diferentes. Nada foi gravado.');
        }
        vistosNfc.set(k, { lote: l, amostra: amostraNfc, diluicao: diluicaoNfc, data: m[6] || hojeNfc });
      }
    }
    if (vistosNfc.size > 1) return erroNfc('❌ O recebimento NFC é um lote por vez: mande um comando para cada lote (e para cada tipo). Ex.: recebimento nfc load 44300 fab aqa item 129 lote 10 past 10 elevado a 1. Nada foi gravado.');
    const resLinha = linhasNfc[iLinha].resultados;
    if (new Set(resLinha.map((x) => x.analise)).size !== resLinha.length) {
      return erroNfc('❌ O lote ' + [...vistosNfc.values()][0].lote + ' tem a mesma análise duas vezes nos resultados. Nada foi gravado.');
    }
    if (resLinha.length) for (const it of vistosNfc.values()) it.resultados = resLinha;
    const bl = porLoad.get(m[2]) || { load: m[2], fabrica: fabNfc.sigla, item: '129', itens: [] };
    if (bl.fabrica !== fabNfc.sigla) return erroNfc('❌ O load ' + m[2] + ' apareceu com duas fábricas (' + bl.fabrica + ' e ' + fabNfc.sigla + '). Nada foi gravado.');
    for (const it of vistosNfc.values()) {
      const igual = bl.itens.find((x) => x.lote === it.lote && x.amostra === it.amostra);
      if (igual && igual.diluicao !== it.diluicao) return erroNfc('❌ O lote ' + it.lote + ' (' + it.amostra + ') apareceu com duas diluições diferentes. Nada foi gravado.');
      if (igual) { igual.data = it.data; if (it.resultados) igual.resultados = it.resultados; } else bl.itens.push(it);
    }
    porLoad.set(m[2], bl);
  }
  const blocosNfc = [...porLoad.values()].map((bl) => ({ ...bl, itens: bl.itens.sort((x, y) => x.lote - y.lote || x.amostra.localeCompare(y.amostra)) }));
  const totalNfc = blocosNfc.reduce((s, bl) => s + bl.itens.length, 0);
  if (totalNfc > 60) return erroNfc('❌ Máximo de 60 lotes por mensagem.');
  return output({
    tipo: 'recebimento_nfc',
    load: blocosNfc[0].load,
    item: '129',
    fabrica: blocosNfc[0].fabrica,
    fabricaLida: fabricasLidas.length ? fabricasLidas[0].lido : '',
    fabricasLidas,
    itens: blocosNfc.flatMap((bl) => bl.itens.map((it) => ({ lote: it.lote, amostra: it.amostra, diluicao: it.diluicao }))),
    dataRecebimento: blocosNfc[0].itens[0].data,
    blocos: blocosNfc,
    numero: numeroRemetente,
    nomeContato
  });
}

// --- RECEBIMENTO DE LOTES (concentrado) ---
const matchRecebimento = texto.trim().match(/^recebimento\s+(?:do\s+)?load\s+(\w+)\s*,?\s*item\s+(\w+)\s*,?\s*f[aá]brica\s+([\w.\-]+)\s*,?\s*lotes?\s+([\d,\s\-]+?)(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?(?:\s*,?\s*(resultados?\s*<\s*10))?\s*$/i);

if (matchRecebimento) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  // item 129 é o recebimento de NFC: precisa do tipo (past/fresh) e da diluição de cada lote
  if (matchRecebimento[2] === '129') {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ O item 129 é o recebimento de NFC e cada lote precisa do tipo (past ou fresh) e da diluição. Ex.: recebimento nfc load ' + matchRecebimento[1] + ' fab ' + String(matchRecebimento[3]).toLowerCase() + ' item 129 lote 10 past 10 elevado a 1. Nada foi gravado.' });
  }
  // "resultados <10": C.T, B.L 72h e B.L 120h dos lotes novos entram como <10 (sem crescimento). Só o Admin (vem do TAB que abre a composta).
  if (matchRecebimento[6] && nivelAtual !== 'Admin') {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Só um Admin registra o recebimento já com os resultados <10. Nada foi gravado.' });
  }
  const lotes = expandirLotes(matchRecebimento[4]);
  if (!lotes) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Não entendi os lotes. Use faixas e vírgulas, ex.: lotes 1-14 ou lotes 1-5,7,9-10'
    });
  }
  // fábricas travadas: só estas seis; nome por extenso e letra torta (AOQ) viram a sigla; outra é recusada
  const fab = resolverFabrica(matchRecebimento[3]);
  if (!fab) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: `❌ Fábrica "${matchRecebimento[3]}" não reconhecida. Use ${FABRICAS_VALIDAS}. Nada foi gravado.`
    });
  }
  return output({
    tipo: 'recebimento',
    load: matchRecebimento[1],
    item: matchRecebimento[2],
    fabrica: fab.sigla,
    fabricaLida: fab.corrigida ? fab.lido : '',
    lotes: [...new Set(lotes)].sort((a, b) => a - b),
    dataRecebimento: matchRecebimento[5] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    resultadosMenor10: matchRecebimento[6] ? '1' : '',
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CRIAR COMPOSTAS: "compostas do load 77001 (1-5)(6-10)(11,12,15)" ---
const matchCompostas = texto.trim().match(/^compostas?\s+(?:do\s+)?load\s+(\w+)(?:\s*,?\s*item\s+(\w+))?\s*,?\s*((?:\(\s*[^()]*\)\s*)+)$/i);

if (matchCompostas) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const grupos = [...matchCompostas[3].matchAll(/\(([^()]*)\)/g)].map(m => m[1]);
  const compostas = [];
  for (let i = 0; i < grupos.length; i++) {
    const lotes = expandirLotes(grupos[i]);
    if (!lotes) {
      return output({
        tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
        textoResposta: `❌ Não entendi a composta ${i + 1}: "(${grupos[i]})". Nada foi gravado.\n\nFormato: compostas do load 77001 (1-5)(6-10)(11,12,15)`
      });
    }
    compostas.push([...new Set(lotes)].sort((a, b) => a - b));
  }
  const todos = compostas.flat();
  const repetidos = [...new Set(todos.filter((l, i) => todos.indexOf(l) !== i))];
  if (repetidos.length) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: `❌ Lote(s) ${repetidos.join(', ')} em mais de uma composta. Nada foi gravado.`
    });
  }
  return output({
    tipo: 'criar_compostas',
    load: matchCompostas[1],
    item: matchCompostas[2] || '',
    compostas,
    numero: numeroRemetente,
    nomeContato
  });
}
// --- EMBARQUE: "A1-A5" -> "1-5" (as amostras também podem ser escritas só com números) ---
function limparAmostras(s) { return String(s).replace(/\bA(?=\d)/gi, ''); }

// --- EMBARQUE (concentrado): "embarque navio O.SKY 133 linha 2 fase 2 load 77010 item 444 amostras 1-10 [data dd/mm/aaaa]" ---
const matchEmbarque = limparAmostras(texto.trim()).match(/^embarque\s+(?:do\s+)?navio\s+(.+?)\s*,?\s*linha\s+(\d+)\s*,?\s*fase\s+(\d+)\s*,?\s*load\s+(\w+)\s*,?\s*item\s+(\w+)\s*,?\s*amostras?\s+([\d,\s\-]+?)(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?\s*$/i);

if (matchEmbarque) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const navio = matchEmbarque[1].replace(/\s+/g, ' ').trim().toUpperCase();
  if (!/\s\d+$/.test(navio)) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Informe o navio com a viagem. Ex.: embarque navio O.SKY 133 linha 2 fase 2 load 77010 item 444 amostras 1-10'
    });
  }
  const amostras = expandirLotes(matchEmbarque[6]);
  if (!amostras) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Não entendi as amostras. Use faixas e vírgulas, ex.: amostras 1-10 ou amostras A1-A5,A7'
    });
  }
  return output({
    tipo: 'embarque',
    navio,
    linha: matchEmbarque[2],
    fase: matchEmbarque[3],
    load: matchEmbarque[4],
    item: matchEmbarque[5],
    amostras: [...new Set(amostras)].sort((a, b) => a - b),
    dataEmbarque: matchEmbarque[7] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CRIAR COMPOSTAS DE EMBARQUE: "compostas do navio O.SKY 133 linha 2 fase 2 (A1-A5)(A6-A10)" ---
const matchCompostasEmb = limparAmostras(texto.trim()).match(/^compostas?\s+(?:do\s+)?navio\s+(.+?)\s*,?\s*linha\s+(\d+)\s*,?\s*fase\s+(\d+)\s*,?\s*((?:\(\s*[^()]*\)\s*)+)$/i);

if (matchCompostasEmb) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const navio = matchCompostasEmb[1].replace(/\s+/g, ' ').trim().toUpperCase();
  const grupos = [...matchCompostasEmb[4].matchAll(/\(([^()]*)\)/g)].map(m => m[1]);
  const compostas = [];
  for (let i = 0; i < grupos.length; i++) {
    const amostras = expandirLotes(grupos[i]);
    if (!amostras) {
      return output({
        tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
        textoResposta: `❌ Não entendi a composta ${i + 1}: "(${grupos[i]})". Nada foi gravado.\n\nFormato: compostas do navio O.SKY 133 linha 2 fase 2 (A1-A5)(A6-A10)`
      });
    }
    compostas.push([...new Set(amostras)].sort((a, b) => a - b));
  }
  const todas = compostas.flat();
  const repetidas = [...new Set(todas.filter((a, i) => todas.indexOf(a) !== i))];
  if (repetidas.length) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: `❌ Amostra(s) ${repetidas.map(a => 'A' + a).join(', ')} em mais de uma composta. Nada foi gravado.`
    });
  }
  return output({
    tipo: 'criar_compostas_embarque',
    navio,
    linha: matchCompostasEmb[2],
    fase: matchCompostasEmb[3],
    compostas,
    numero: numeroRemetente,
    nomeContato
  });
}

// --- HOWARD (embarque): consultas ---
//   "temos analise de howard para hoje?"  -> compostas de embarque sem Howard
//   "quais howards foram lidos hoje?"     -> Howards gravados hoje
const howardEtapa =
  ajudaBusca.match(/^(?:temos|tem|quais|qual)?\s*(?:analises?\s+(?:de\s+)?)?howards?\s+(?:para|pra|de)\s+hoje$/) ? 'pendentes' :
  (ajudaBusca.match(/^(?:quais|qual)\s+howards?\s+(?:foram|ja\s+foram)\s+lidos?\s+hoje$/) ? 'lidos' : null);
if (howardEtapa) {
  return output({ tipo: 'consulta_howard', etapa: howardEtapa, numero: numeroRemetente, nomeContato });
}

// --- HOWARD (embarque): registrar a porcentagem ---
//   "howard #20 2%"
//   "Analise da composta de Howard do navio O.SKY 133 linha 2 fase 2 amostras 1-5, foi 2%"
if (/\bhowards?\b/.test(ajudaBusca) && /\d\s*%\s*$/.test(ajudaBusca)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const erroHoward = t => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  const pct = ajudaBusca.match(/(\d+(?:[.,]\d+)?)\s*%\s*$/);
  const perc = Number(pct[1].replace(',', '.'));
  // Howard é lido em 50 campos e cada campo positivo vale 2%: a porcentagem é sempre par
  if (!(perc >= 0 && perc <= 100) || perc % 2 !== 0) {
    return erroHoward(`❌ O Howard é lido em 50 campos, então a porcentagem é sempre par (0%, 2%, 4%...). Recebi ${pct[1]}%. Nada foi gravado.`);
  }
  const mIdHoward = ajudaBusca.match(/#\s*(\d+)/);
  if (mIdHoward) {
    return output({ tipo: 'howard_registrar', compostaId: Number(mIdHoward[1]), percentual: perc,
      refNavio: '', refLinha: '', refFase: '', refGrupos: [], numero: numeroRemetente, nomeContato });
  }
  const textoSemPct = texto.trim().replace(/[,\s]*(?:foi|deu|=)?\s*\d+(?:[.,]\d+)?\s*%\s*$/i, '');
  const refH = extrairRef(textoSemPct);
  if (refH.navio && refH.grupos.length === 1 && refH.grupos[0]) {
    return output({ tipo: 'howard_registrar', compostaId: '', percentual: perc,
      refNavio: refH.navio, refLinha: refH.linha, refFase: refH.fase, refGrupos: refH.grupos,
      numero: numeroRemetente, nomeContato });
  }
  return erroHoward('❌ Não entendi o Howard. Exemplos:\nhoward #20 2%\nAnalise da composta de Howard do navio O.SKY 133 linha 2 fase 2 amostras 1-5, foi 2%');
}

// --- TAB DE NFC (tank farm, por tanque; o comando sempre cita a data da coleta) ---
//   "Tab feito dos tanques terra 42,43 coleta 28/09/2026 [data dd/mm/aaaa]"
const matchTabNfc = texto.trim().match(/^tabs?\s+feitos?\s+(?:d[aeo]s?\s+)?tanques?\s+(?:terra\s+)?([\d,\s]+?)\s*,?\s*coleta\s+(\d{2}\/\d{2}\/\d{4})(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?(?:\s*,?\s*(completo))?\s*$/i);
// Atalhos (a data é a da coleta; sem ano vale o ano de hoje): "tq 44 16/10", "tab tanque terra 47 06/10/26", "tab feito tanque terra 42, data 16/10"
const matchTabNfcCurto = matchTabNfc ? null : texto.trim().match(/^(?:tabs?\s+(?:feitos?\s+)?(?:d[aeo]s?\s+)?(?:tq|tanques?(?:\s+terra)?)|tq)\s*,?\s*(\d+(?:\s*(?:,|\be\b)\s*\d+)*)\s*,?\s*(?:(?:coleta|data)\s+)?(\d{1,2})[\/.\-](\d{1,2})(?:[\/.\-](\d{4}|\d{2}))?(?:\s*,?\s*(completo))?\s*$/i);
// Vários grupos de coleta num comando só (a foto de TAB manda assim e o "sim" responde uma mensagem só):
//   "Tab feito dos tanques terra 39,46 coleta 17/10/2026 ; 43 coleta 18/10/2026 [data dd/mm/aaaa] [completo]"
const matchTabNfcVarios = (matchTabNfc || matchTabNfcCurto || !texto.includes(';')) ? null : texto.trim().match(/^tabs?\s+feitos?\s+(?:d[aeo]s?\s+)?tanques?\s+(?:terra\s+)?((?:[\d,\s]+?\s*,?\s*coleta\s+\d{2}\/\d{2}\/\d{4}\s*;\s*)+[\d,\s]+?\s*,?\s*coleta\s+\d{2}\/\d{2}\/\d{4})(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?(?:\s*,?\s*(completo))?\s*$/i);
if (matchTabNfc || matchTabNfcCurto || matchTabNfcVarios) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  let tanquesTxt, dataColetaNfc, dataFeitoNfc, completoNfc, gruposNfc = null;
  if (matchTabNfcVarios) {
    gruposNfc = matchTabNfcVarios[1].split(';').map((s) => s.trim().match(/^([\d,\s]+?)\s*,?\s*coleta\s+(\d{2}\/\d{2}\/\d{4})$/))
      .map((g) => ({ tanques: [...new Set(g[1].split(/[,\s]+/).filter(Boolean))], coleta: g[2] }));
    tanquesTxt = gruposNfc.map((g) => g.tanques.join(',')).join(','); dataColetaNfc = gruposNfc[0].coleta;
    dataFeitoNfc = matchTabNfcVarios[2] || ''; completoNfc = !!matchTabNfcVarios[3];
  } else if (matchTabNfc) {
    tanquesTxt = matchTabNfc[1]; dataColetaNfc = matchTabNfc[2]; dataFeitoNfc = matchTabNfc[3] || ''; completoNfc = !!matchTabNfc[4];
  } else {
    const cu = matchTabNfcCurto;
    const dd = cu[2].padStart(2, '0'), mm = cu[3].padStart(2, '0');
    if (Number(dd) < 1 || Number(dd) > 31 || Number(mm) < 1 || Number(mm) > 12) {
      return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
        textoResposta: '❌ Não entendi a data da coleta (dia/mês). Ex.: tq 44 16/10  ou  Tab feito dos tanques terra 44 coleta 16/10/2026' });
    }
    const aa = cu[4] ? (cu[4].length === 2 ? '20' + cu[4] : cu[4]) : new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }).slice(6);
    tanquesTxt = cu[1].replace(/\be\b/gi, ','); dataColetaNfc = dd + '/' + mm + '/' + aa; dataFeitoNfc = ''; completoNfc = !!cu[5];
  }
  const tanquesNfc = [...new Set(tanquesTxt.split(/[,\s]+/).filter(Boolean))];
  if (!tanquesNfc.length || tanquesNfc.some(t => !/^\d+$/.test(t))) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Não entendi os tanques. Ex.: Tab feito dos tanques terra 42,43 coleta 28/09/2026' });
  }
  const maxTanques = gruposNfc ? 24 : 8;
  if (tanquesNfc.length > maxTanques) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: `❌ Máximo de ${maxTanques} tanques por mensagem. Nada foi gravado.` });
  }
  // "completo": registra a coleta e as análises que faltam e marca <1,<1,<1 nas leituras já vencidas. Só o Admin.
  if (completoNfc && nivelAtual !== 'Admin') {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Só um Admin registra o TAB de tanque junto com a coleta, as análises e as placas <1. Nada foi gravado.' });
  }
  return output({ tipo: 'tab_feito_nfc', tanques: tanquesNfc, dataColeta: dataColetaNfc,
    dataFeito: dataFeitoNfc || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    completo: completoNfc ? '1' : '',
    grupos: gruposNfc ? gruposNfc.flatMap((g) => g.tanques.map((t) => ({ tanque: t, coleta: g.coleta }))) : null,
    gruposTxt: gruposNfc ? gruposNfc.map((g) => g.tanques.join(',') + ' coleta ' + g.coleta).join(' ; ') : '',
    numero: numeroRemetente, nomeContato });
}

// TAB de NFC em confirmação: "tab tanque terra 42 coleta 28/09/2026 em confirmação"
const matchTabNfcConf = ajudaBusca.match(/^tabs?\s+(?:d[aeo]s?\s+)?tanques?\s+(?:terra\s+)?(\d+)\s*,?\s*coleta\s+(\d{2}\/\d{2}\/\d{4})\s*,?\s*em\s+confirmacao$/);
if (matchTabNfcConf) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'tab_em_confirmacao', teste: 'TAB', compostaId: '',
    refTanque: matchTabNfcConf[1], refDataColeta: matchTabNfcConf[2], numero: numeroRemetente, nomeContato });
}

// resultado do TAB de NFC: "confirmação do tab tanque terra 42 coleta 28/09/2026 positivo"
const matchTabNfcRes = ajudaBusca.match(/^confirmacao\s+(?:d[aeo]\s+)?tabs?\s+(?:d[aeo]s?\s+)?tanques?\s+(?:terra\s+)?(\d+)\s*,?\s*coleta\s+(\d{2}\/\d{2}\/\d{4})\s*,?\s*(?:deu\s+)?(positivo|negativo)$/);
if (matchTabNfcRes) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'tab_resultado', teste: 'TAB', compostaId: '',
    refTanque: matchTabNfcRes[1], refDataColeta: matchTabNfcRes[2],
    resultado: matchTabNfcRes[3] === 'positivo' ? 'Positivo' : 'Negativo', numero: numeroRemetente, nomeContato });
}

// --- C.T e B.L (72h e 120h) por lote (recebimento) e por amostra (embarque) ---
function nomeAnaliseCt(s) {
  const t = String(s).toLowerCase().replace(/\s+/g, '');
  return t === 'ct' ? 'CT' : (t === 'bl72' ? 'BL72' : 'BL120');
}

// consultas: "quais ct tenho para ler hoje?" / "quais bl72 foram lidos hoje?"
const matchCtConsulta =
  ajudaBusca.match(/^(?:quais|qual|temos|tem)?\s*(ct|bl\s*72|bl\s*120|bl)s?\s+(?:(?:tenho|temos|tem)\s+)?(?:para|pra)\s+ler(?:\s+hoje)?$/) ||
  ajudaBusca.match(/^(?:quais|qual)\s+(ct|bl\s*72|bl\s*120|bl)s?\s+(?:foram|ja\s+foram)\s+lidos?\s+hoje$/);
if (matchCtConsulta) {
  return output({ tipo: 'consulta_contagens', analise: nomeAnaliseCt(matchCtConsulta[1]),
    etapa: /\bforam\b/.test(ajudaBusca) ? 'lidos' : 'ler', numero: numeroRemetente, nomeContato });
}

// --- "TODOS": C.T / B.L em todos os lotes (ou amostras) que saem hoje (ou na data) e ainda sem resultado ---
//   "bl72 load 44502 todos deu <10 exceto lote 3 deu 20"  ·  "bl72 recebimento load 44502 todos de 14/10 deu <10"
//   "ct nfc load 44300 todos deu <10 exceto lote 10 past deu 14"  ·  "bl120 navio O.SKY 189 linha 6 fase 1 todas deu <10"
// Exceção com valor = o valor daquele lote (pode até corrigir); exceção sem valor = fica de fora.
const matchCtTodos = ajudaBusca.match(/^(ct|bl\s*72|bl\s*120|bl)\s+(?:(?:d[oe]\s+)?recebimento\s+)?(?:(nfc)\s+)?(?:(?:d[oe]\s+)?load\s+(\w+)(?:\s*,?\s*item\s+(\w+))?|(?:d[oe]\s+)?(?:embarque\s+)?(?:d[oe]\s+)?navio\s+(.+?)\s*,?\s*linha\s+(\d+)\s*,?\s*fase\s+(\d+))\s*,?\s*(?:tod[oa]s|tudo)\b\s*(.*)$/);
if (matchCtTodos) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const ehNfcT = matchCtTodos[2] === 'nfc' || matchCtTodos[4] === '129';
  const ehLoadT = !!matchCtTodos[3];
  const exemploT = ehNfcT ? 'ct nfc load 44300 todos deu <10 exceto lote 10 past deu 14'
    : ehLoadT ? 'bl72 load 44502 todos deu <10 exceto lote 3 deu 20' : 'bl120 navio O.SKY 189 linha 6 fase 1 todas deu <10 exceto amostra 3 deu 20';
  const erroT = t => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: '❌ ' + t + ' Nada foi gravado.\n\nEx.: ' + exemploT });
  if (ehNfcT && !ehLoadT) return erroT('O NFC recebido é por load (não tem embarque).');
  if (matchCtTodos[2] === 'nfc' && matchCtTodos[4] && matchCtTodos[4] !== '129') return erroT('O recebimento NFC é sempre o item 129 (você escreveu ' + matchCtTodos[4] + ').');
  let r = matchCtTodos[8].trim().replace(/\ba(?=\d)/g, '');
  r = r.replace(/^(?:os\s+lotes|as\s+amostras|lotes|amostras)\b\s*/, '').replace(/^,?\s*que\s+(?:sa(?:i|em)|vence(?:m)?)\s*/, '');
  let dataT = dataDaConsulta('hoje');
  let dataTxtT = '';
  const mDataT = r.match(/^,?\s*(?:d[eo]\s+(?:dia\s+)?|do\s+dia\s+|para\s+|pra\s+)?(hoje|\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)(?![\d\/])\s*/);
  if (mDataT) {
    dataTxtT = mDataT[1];
    dataT = dataDaConsulta(mDataT[1]);
    if (!dataT) return erroT('Data inválida: "' + mDataT[1] + '". Use dd/mm/aaaa.');
    r = r.slice(mDataT[0].length).trim();
  }
  const VALOR_T = '(?:(menor\\s+que|menos\\s+de|abaixo\\s+de)\\s*|([<>=]?)\\s*)(\\d+(?:[.,]\\d+)?)';
  const mValorT = r.match(new RegExp('^,?\\s*(?:deu|deram|foi|foram|ficou|ficaram|=)?\\s*' + VALOR_T + '(?![\\d])\\s*'));
  if (!mValorT) return erroT('Diga o resultado do "todos", ex.: todos deu <10.');
  const todos = { sinal: mValorT[1] ? '<' : (mValorT[2] || '='), valor: Number(mValorT[3].replace(',', '.')) };
  r = r.slice(mValorT[0].length).trim();
  const grupos = [];
  const excluidos = [];
  const vistosT = new Set();
  if (r) {
    const mExc = r.match(/^,?\s*(?:exceto|menos|fora|com\s+excecao\s+d[oa]s?)\s+(.+)$/);
    if (!mExc) return erroT('Não entendi "' + r + '".');
    const partes = mExc[1].split(/\s*(?:,|;|\be\b)?\s*(?=\b(?:lotes?|amostras?)\s+\d)/).map(s => s.trim()).filter(Boolean);
    for (const parte of partes) {
      const g = parte.match(new RegExp('^(?:lotes?|amostras?)\\s+(' + NFC_LISTA + ')(?:\\s+(past|pasteurizad[oa]|fresh|fresco|in\\s+natura))?(?:\\s*,?\\s*(?:deu|foi|=)\\s*' + VALOR_T + ')?\\s*$'));
      if (!g) return erroT('Não entendi a exceção "' + parte + '". Use: exceto lote 3 deu 20 (ou só exceto lote 3 para deixar de fora).');
      const nums = expandirLotes(g[1].replace(/\s+e\s+/g, ',').replace(/\s+/g, ''));
      if (!nums) return erroT('Não entendi os números "' + g[1] + '".');
      const amostraT = !g[2] ? '' : (/^past/.test(g[2]) ? 'past' : 'fresh');
      if (amostraT && !ehNfcT) return erroT('past/fresh só existe no recebimento NFC.');
      const temValor = g[5] !== undefined;
      if (ehNfcT && temValor && !amostraT) return erroT('No NFC, diga o tipo do lote ' + g[1] + ' (past ou fresh) antes do resultado.');
      for (const n of nums) {
        const k = n + '|' + amostraT;
        if (vistosT.has(k)) return erroT('O ' + (ehLoadT ? 'lote ' : 'número ') + n + ' aparece mais de uma vez no "exceto".');
        vistosT.add(k);
      }
      const unicos = [...new Set(nums)].sort((a, b) => a - b);
      if (!temValor) { unicos.forEach(n => excluidos.push(ehNfcT ? { lote: n, amostra: amostraT } : n)); continue; }
      const sinalE = g[3] ? '<' : (g[4] || '=');
      const valorE = Number(g[5].replace(',', '.'));
      grupos.push(ehNfcT ? { lotes: unicos, amostra: amostraT, sinal: sinalE, valor: valorE } : { numeros: unicos, sinal: sinalE, valor: valorE });
    }
  }
  const todosT = { ...todos, data: dataT, dataTxt: dataTxtT };
  if (ehNfcT) {
    const pedidosT = grupos.flatMap(g => g.lotes.map(l => ({ lote: l, amostra: g.amostra })));
    return output({ tipo: 'contagem_nfc_registrar', analise: nomeAnaliseCt(matchCtTodos[1]), load: matchCtTodos[3],
      grupos, pedidos: pedidosT, todos: todosT, excluidos, numero: numeroRemetente, nomeContato });
  }
  const numerosT = [...new Set(grupos.flatMap(g => g.numeros))].sort((a, b) => a - b);
  return output({ tipo: 'contagem_registrar', analise: nomeAnaliseCt(matchCtTodos[1]), origem: ehLoadT ? 'recebimento' : 'embarque',
    load: matchCtTodos[3] || '', item: matchCtTodos[4] || '',
    navio: ehLoadT ? '' : matchCtTodos[5].replace(/\s+/g, ' ').trim().toUpperCase(),
    linha: matchCtTodos[6] || '', fase: matchCtTodos[7] || '',
    grupos, numeros: numerosT, todos: todosT, excluidos, numero: numeroRemetente, nomeContato });
}

// --- C.T e B.L do RECEBIMENTO NFC: "ct nfc load 44300 lote 10 past deu 14, lote 11 fresh deu <10" ---
// O número vem como saiu na placa; o bot multiplica pela diluição do lote (10 elevado a 1 acrescenta um zero).
const matchCtNfc = ajudaBusca.match(/^(ct|bl\s*72|bl\s*120|bl)\s+(?:(?:d[oe]\s+)?recebimento\s+)?(?:nfc\s+)?load\s+(\w+)\s*,?\s*(?:item\s+(\w+)\s*,?\s*)?(lotes?\s+.+)$/);
if (matchCtNfc && (matchCtNfc[3] === '129' || /\bnfc\b/.test(ajudaBusca) || /\b(past|pasteuriz\w*|fresh|fresco|in\s+natura)\b/.test(matchCtNfc[4]))) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const erroCtNfc = (t) => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  const exemploCtNfc = '\n\nExemplo: ct nfc load 44300 lote 10 past deu 14, lote 11 fresh deu <10';
  if (matchCtNfc[3] && matchCtNfc[3] !== '129') {
    return erroCtNfc('❌ O recebimento NFC é sempre o item 129 (você escreveu ' + matchCtNfc[3] + '). Nada foi gravado.');
  }
  const GRUPO_CT_NFC = new RegExp('lotes?\\s+(' + NFC_LISTA + ')\\s+(past|pasteurizad[oa]|fresh|fresco|in\\s+natura)\\s+(?:deu|foi|=)\\s*([<>=]?)\\s*(\\d+(?:[.,]\\d+)?)', 'g');
  const restoCtNfc = matchCtNfc[4];
  const gruposCtNfc = [...restoCtNfc.matchAll(GRUPO_CT_NFC)];
  const sobraCtNfc = restoCtNfc.replace(GRUPO_CT_NFC, ' ').replace(/[\s,;]+|\be\b/g, '');
  if (!gruposCtNfc.length || sobraCtNfc) {
    return erroCtNfc('❌ Não entendi os lotes. Para cada lote diga o tipo (past ou fresh) e o resultado.' + exemploCtNfc);
  }
  const vistosCtNfc = new Set();
  const grupos = [];
  for (const g of gruposCtNfc) {
    const lotesCt = expandirLotes(g[1].replace(/\s+e\s+/g, ',').replace(/\s+/g, ''));
    if (!lotesCt) return erroCtNfc('❌ Não entendi os lotes "' + g[1] + '". Use faixas e vírgulas, ex.: lotes 10-12. Nada foi gravado.');
    const amostraCt = /^past/.test(g[2]) ? 'past' : 'fresh';
    for (const l of lotesCt) {
      if (vistosCtNfc.has(l + '|' + amostraCt)) return erroCtNfc('❌ O lote ' + l + ' (' + amostraCt + ') aparece em mais de um grupo. Nada foi gravado.');
      vistosCtNfc.add(l + '|' + amostraCt);
    }
    grupos.push({ lotes: [...new Set(lotesCt)].sort((a, b) => a - b), amostra: amostraCt, sinal: g[3] || '=', valor: Number(g[4].replace(',', '.')) });
  }
  const pedidosCtNfc = [...vistosCtNfc].map((k) => { const [l, a] = k.split('|'); return { lote: Number(l), amostra: a }; });
  if (pedidosCtNfc.length > 60) return erroCtNfc('❌ Máximo de 60 lotes por mensagem. Nada foi gravado.');
  return output({
    tipo: 'contagem_nfc_registrar',
    analise: nomeAnaliseCt(matchCtNfc[1]),
    load: matchCtNfc[2],
    grupos,
    pedidos: pedidosCtNfc,
    numero: numeroRemetente,
    nomeContato
  });
}

// registro, com vários grupos na mesma mensagem:
//   "ct load 77001 lote 4 deu 10, lotes 5-10 deu <10"
//   "bl72 load 77001 item 444 lotes 1-14 deu <10"
//   "ct navio O.SKY 133 linha 2 fase 2 amostras 1-5 deu <10, amostra 6 deu 30"
const matchCtReg = limparAmostras(texto.trim()).match(/^(ct|bl\s*72|bl\s*120|bl)\s+(?:(?:d[oe]\s+)?recebimento\s+)?(?:load\s+(\w+)(?:\s*,?\s*item\s+(\w+))?|navio\s+(.+?)\s*,?\s*linha\s+(\d+)\s*,?\s*fase\s+(\d+))\s*,?\s*((?:lotes?|amostras?)\s+.+)$/i);
if (matchCtReg) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const erroCt = t => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  const exemplo = '\n\nExemplos:\nct load 77001 lote 4 deu 10, lotes 5-10 deu <10\nct navio O.SKY 133 linha 2 fase 2 amostras 1-5 deu <10, amostra 6 deu 30';
  const grupos = [];
  const vistos = new Set();
  for (const parte of matchCtReg[7].split(/(?:\s*,\s*|\s+)(?=(?:lotes?|amostras?)\s+\d)/i)) {
    const g = parte.trim().match(/^(?:lotes?|amostras?)\s+([\d,\s\-]+?)\s*(?:deu|foi|=)\s*([<>=]?)\s*(\d+(?:[.,]\d+)?)\s*$/i);
    if (!g) return erroCt(`❌ Não entendi "${parte.trim()}". Nada foi gravado.${exemplo}`);
    const numeros = expandirLotes(g[1].replace(/[\s,]+$/, ''));
    if (!numeros) return erroCt(`❌ Não entendi os números "${g[1].trim()}". Use faixas e vírgulas, ex.: lotes 5-10. Nada foi gravado.`);
    const unicos = [...new Set(numeros)].sort((a, b) => a - b);
    const repetidos = unicos.filter(n => vistos.has(n));
    if (repetidos.length) return erroCt(`❌ O número ${repetidos[0]} aparece em mais de um grupo. Nada foi gravado.`);
    unicos.forEach(n => vistos.add(n));
    grupos.push({ numeros: unicos, sinal: g[2] || '=', valor: Number(g[3].replace(',', '.')) });
  }
  const todosNumeros = [...vistos].sort((a, b) => a - b);
  if (todosNumeros.length > 200) return erroCt('❌ Máximo de 200 lotes/amostras por mensagem. Nada foi gravado.');
  const ehLoad = !!matchCtReg[2];
  return output({
    tipo: 'contagem_registrar',
    analise: nomeAnaliseCt(matchCtReg[1]),
    origem: ehLoad ? 'recebimento' : 'embarque',
    load: matchCtReg[2] || '',
    item: matchCtReg[3] || '',
    navio: ehLoad ? '' : matchCtReg[4].replace(/\s+/g, ' ').trim().toUpperCase(),
    linha: matchCtReg[5] || '',
    fase: matchCtReg[6] || '',
    grupos,
    numeros: todosNumeros,
    numero: numeroRemetente,
    nomeContato
  });
}

// --- TAB FEITO: "tab feito das compostas #4 a #6" ou "tab feito do load 77001" ---
const matchTabFeito = texto.trim().match(/^tabs?\s+feitos?\s+(?:d[aeo]s?\s+)?(?:compostas?\s+([#\d\s,ae\-]+?)|load\s+(\w+)(?:\s*,?\s*item\s+(\w+))?)(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?\s*$/i);

if (matchTabFeito) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const ids = [];
  if (matchTabFeito[1]) {
    // "#4 a #6", "#4-#6", "#4, #5 e #7"
    for (const m of matchTabFeito[1].matchAll(/#?(\d+)(?:\s*(?:a|-)\s*#?(\d+))?/g)) {
      const ini = Number(m[1]), fim = m[2] ? Number(m[2]) : ini;
      if (fim < ini || fim - ini > 100) { ids.length = 0; break; }
      for (let n = ini; n <= fim; n++) ids.push(n);
    }
    if (!ids.length) {
      return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
        textoResposta: '❌ Não entendi as compostas. Ex.: tab feito das compostas #4 a #6' });
    }
  }
  return output({
    tipo: 'tab_feito',
    compostaIds: [...new Set(ids)],
    load: matchTabFeito[2] || '',
    item: matchTabFeito[3] || '',
    dataFeito: matchTabFeito[4] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CONSULTAS DO TAB: espalhar hoje, ler hoje, lidos hoje ---
const matchTabConsulta =
  ajudaBusca.match(/^(?:quais|qual|temos|tem)?\s*tabs?\s+(?:(?:tenho|temos|tem)\s+)?(?:para|pra)\s+(espalhar|ler)(?:\s+hoje)?$/) ||
  ajudaBusca.match(/^(?:quais|qual)\s+tabs?\s+(?:foram|ja\s+foram)\s+(lidos?)\s+hoje$/);

if (matchTabConsulta) {
  const etapa = matchTabConsulta[1].startsWith('lido') ? 'lidos' : matchTabConsulta[1];
  return output({ tipo: 'consulta_tab', etapa, numero: numeroRemetente, nomeContato });
}
// --- TAB: etapa do dia feita ("tabs de hoje espalhados" / "tabs de hoje lidos") ---
const matchTabEtapa = ajudaBusca.match(/^tabs?\s+de\s+hoje\s+(espalhados?|lidos?)$/);
if (matchTabEtapa) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'tab_etapa', etapa: matchTabEtapa[1].startsWith('espalh') ? 'espalhar' : 'lidos',
    numero: numeroRemetente, nomeContato });
}

// --- TAB em confirmação: "tab #5 em confirmação" ---
const matchTabConf = ajudaBusca.match(/^tabs?\s+(?:da\s+composta\s+)?#\s*(\d+)\s+em\s+confirmacao$/);
if (matchTabConf) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'tab_em_confirmacao', compostaId: Number(matchTabConf[1]), numero: numeroRemetente, nomeContato });
}

// --- Resultado da confirmação: "confirmação do tab #5 positivo" ---
const matchTabRes = ajudaBusca.match(/^confirmacao\s+(?:do\s+)?tabs?\s+(?:da\s+composta\s+)?#\s*(\d+)\s*,?\s*(?:deu\s+)?(positivo|negativo)$/);
if (matchTabRes) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'tab_resultado', compostaId: Number(matchTabRes[1]),
    resultado: matchTabRes[2] === 'positivo' ? 'Positivo' : 'Negativo', numero: numeroRemetente, nomeContato });
}
// --- COLIFORMES DA FOTO (interno): só pelo "sim" da foto da folha de Coliformes (reenvio do próprio bot) ---
// "TAB da foto: #12 data 13/10/2026 positivo ; load 43699 item 2655 (1-3) data 13/10/2026 negativo" (só pelo sim da foto)
// positivo = "+" já confirmado; negativo = "—"; o TAB fica concluído (sem TAB ainda: entra feito na data da linha)
if (/^tabs?\s+da\s+foto\s*:/.test(ajudaBusca)) {
  const erroTf = (t) => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  if (webhookItem.body.labflowReenvio !== true) {
    return erroTf('❌ Esse comando é usado pela foto da folha de TAB. Mande a foto, ou use *tab #5 em confirmação* e *tabs de hoje lidos*.');
  }
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const linhasTf = [];
  for (const p of texto.trim().replace(/^tabs?\s+da\s+foto\s*:\s*/i, '').split(/\s*;\s*/).filter(Boolean)) {
    const m = p.match(/^(?:#\s*(\d+)|load\s+(\w+)\s+item\s+(\w+)\s*\(([\d,\s\-]+)\))(?:\s+data\s+(\d{2}\/\d{2}\/\d{4}))?\s+(negativo|positivo)$/i);
    if (!m) return erroTf('❌ Não entendi a linha "' + p + '" da foto de TAB. Nada foi gravado.');
    const lotes = m[4] ? expandirLotes(m[4].replace(/\s+/g, '')) : [];
    if (m[4] && !lotes) return erroTf('❌ Não entendi os lotes "' + m[4] + '". Nada foi gravado.');
    linhasTf.push({ i: linhasTf.length, id: m[1] ? Number(m[1]) : null, load: m[2] || null, item: m[3] || null, lotes,
      data: m[5] || '', acao: m[6].toLowerCase() });
  }
  if (!linhasTf.length || linhasTf.length > 80) return erroTf('❌ Nenhuma linha (ou mais de 80) na foto de TAB. Nada foi gravado.');
  return output({ tipo: 'tab_foto', linhas: linhasTf, numero: numeroRemetente, nomeContato });
}

// "Coliformes da foto: #12 data 16/10/2026 negativo ; load 43750 item 1233 (1,2) data 16/10/2026 feito"
// feito = no caldo com a data da linha; negativo = lido negativo ("—"); positivo = "+" (depois pergunta se abre lote a lote)
if (/^coliformes?\s+da\s+foto\s*:/.test(ajudaBusca)) {
  const erroCf = (t) => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  if (webhookItem.body.labflowReenvio !== true) {
    return erroCf('❌ Esse comando é usado pela foto da folha de Coliformes. Mande a foto, ou use *coliformes feitos ...* e *coliformes de hoje lidos*.');
  }
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const linhasCf = [];
  for (const p of texto.trim().replace(/^coliformes?\s+da\s+foto\s*:\s*/i, '').split(/\s*;\s*/).filter(Boolean)) {
    const m = p.match(/^(?:#\s*(\d+)|load\s+(\w+)\s+item\s+(\w+)\s*\(([\d,\s\-]+)\))\s+data\s+(\d{2}\/\d{2}\/\d{4})\s+(feito|negativo|positivo)$/i);
    if (!m) return erroCf('❌ Não entendi a linha "' + p + '" da foto de Coliformes. Nada foi gravado.');
    const lotes = m[4] ? expandirLotes(m[4].replace(/\s+/g, '')) : [];
    if (m[4] && !lotes) return erroCf('❌ Não entendi os lotes "' + m[4] + '". Nada foi gravado.');
