const bc = ajudaBusca.replace(/[?,.]?\s*(?:e\s+)?me\s+(?:envia|manda|passa|mostra|da)\b.*$/, '').replace(/[?!.]+$/, '').trim();
const DATA_CONSULTA = /(?:\s+d[oae]s?)?\s+(?:dia\s+)?(hoje|ontem|\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)(?![\d\/])/;
function dataDaConsulta(s) {
  const hojeSP = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
  const fmt = (d) => String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();
  if (s === 'hoje') return fmt(hojeSP);
  if (s === 'ontem') { hojeSP.setDate(hojeSP.getDate() - 1); return fmt(hojeSP); }
  const m = s.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/);
  if (!m) return null;
  let ano = m[3] ? Number(m[3]) : hojeSP.getFullYear();
  if (ano < 100) ano += 2000;
  const d = new Date(ano, Number(m[2]) - 1, Number(m[1]));
  if (d.getFullYear() !== ano || d.getMonth() !== Number(m[2]) - 1 || d.getDate() !== Number(m[1])) return null;
  return fmt(d);
}
// separa "(do dia 14/10/2026) (do navio O.SKY 123)" do resto; devolve null se sobrar texto estranho
function dataENavioDaConsulta(resto) {
  let r = ' ' + (resto || '').trim();
  let dataTxt = '';
  const md = r.match(DATA_CONSULTA);
  if (md) { dataTxt = md[1]; r = r.replace(DATA_CONSULTA, ' '); }
  let navio = '';
  const mn = r.match(/^\s*(?:d[oa]s?\s+)?navio\s+([a-z0-9][a-z0-9. \-]*?)\s*$/);
  if (mn) { navio = mn[1].toUpperCase(); r = ''; }
  if (r.trim()) return null;
  const data = dataTxt ? dataDaConsulta(dataTxt) : '';
  return { data, dataTxt, navio };
}
