}
const matchLoadResultado = bc.match(/\bloads?\s+(\d{3,})\b/);
if (matchLoadResultado
    && (/^(?:quanto|qual|quais|como|resultados?|me\s+(?:da|passa|envia|mostra)|mostra|ver|cade)\b/.test(bc) || /\bate\s+(?:agora|o\s+momento)$/.test(bc))
    && /\b(?:c\.?t|b\.?l|bl\s*72|bl\s*120|resultados?|contagens?)\b/.test(bc)
    && !/\bdeu\b|\blotes?\s+\d|\bitem\b|\bfabrica\b|\bnavio\b/.test(bc)) {
