const p = $input.all().map(i => i.json).find(r => r.tipo);
const item = $('Interpretar comando').first().json;
const acao = item.tipo; // 'confirmar_pendencia' ou 'cancelar_pendencia'
const feitaPor = item.nomeContato || 'Desconhecido';

const ehIA = !!p && p.tipo === 'IA';
const ehTAB = !!p && p.tipo === 'TAB';
const ehDIA = !!p && p.tipo === 'DIA';
const ehDESVIO = !!p && p.tipo === 'DESVIO';
const ehNFC = !!p && (p.tipo === 'PLACAS' || p.tipo === 'DESVIO_TANQUE');
const itens = p && Array.isArray(p.payload) ? p.payload : [];

if (!p || (!ehIA && !ehTAB && !ehDIA && !ehDESVIO && !ehNFC && itens.length === 0)) {
  return [{ json: { ...item, analisesParaAtualizar: [], limparPendencia: false,
    textoResposta: 'ℹ️ Nenhuma confirmação pendente encontrada.' } }];
}

// A idade da pendência vem calculada pelo banco (now() - criado_em), sem ler data em texto.
const minutos = Number(p.minutos);
if (!Number.isFinite(minutos) || minutos > 10) {
  return [{ json: { ...item, analisesParaAtualizar: [], limparPendencia: true,
    textoResposta: '⏰ Essa confirmação expirou. Envie o comando novamente.' } }];
}

if (acao === 'cancelar_pendencia') {
  return [{ json: { ...item, analisesParaAtualizar: [], limparPendencia: true,
    textoResposta: '❌ Operação cancelada. Nada foi alterado.' } }];
}

// Pendência criada pela IA: o payload guarda o comando canônico a executar
if (ehIA) {
  // foto de laudo: o payload traz uma LISTA de comandos, executada em ordem
  const lista = p.payload && Array.isArray(p.payload.comandos) ? p.payload.comandos.filter(Boolean) : [];
  return [{ json: { ...item, analisesParaAtualizar: [], limparPendencia: true,
    reenviarComando: lista.length ? '' : ((p.payload && p.payload.comando) || p.resumo),
    reenviarComandos: lista,
    textoResposta: '' } }];
}

// Pendência de desvio de drop: abrir ou fechar (o resumo já traz a resposta final)
if (ehDESVIO) {
  return [{ json: { ...item, analisesParaAtualizar: [], limparPendencia: true,
    desvioAcao: JSON.stringify(p.payload), textoResposta: p.resumo } }];
}

// Placas de NFC e desvio de tanque (abrir ou repetição feita): o resumo já traz a resposta final
if (ehNFC) {
  return [{ json: { ...item, analisesParaAtualizar: [], limparPendencia: true,
    nfcAcao: JSON.stringify(p.payload), textoResposta: `${p.resumo}\n\nPor: ${feitaPor}` } }];
}

// Pendência da leitura do dia: o resumo já traz a resposta final
if (ehDIA) {
  return [{ json: { ...item, analisesParaAtualizar: [], limparPendencia: true,
    finalizarDia: '1', textoResposta: p.resumo } }];
}

// Pendência do TAB: o payload diz a ação (espalhar, negativos ou resultado) e os testes
if (ehTAB) {
  return [{ json: { ...item, analisesParaAtualizar: [], limparPendencia: true,
    tabAcao: JSON.stringify(p.payload),
    textoResposta: `✅ Feito:\n\n${p.resumo}\n\nPor: ${feitaPor}` } }];
}
const analisesParaAtualizar = itens.map(x => ({
  id: x.id,
  novoStatus: x.novoStatus,
  // Se o novo status é "Concluído", foi a leitura final; senão, foi a pré-leitura.
  estagio: /conclu/i.test(x.novoStatus) ? 'final' : 'pre',
  feitaPor
}));

return [{ json: { ...item, analisesParaAtualizar, limparPendencia: true,
  textoResposta: `✅ Concluído:\n\n${p.resumo}\n\nLeitura feita por: ${feitaPor}` } }];

