if (raw?.limite) {
  return [{ json: {
    numero: principal.numero,
    nomeContato: principal.nomeContato,
    comando_ia: null,
    reenviarComando: '',
    textoResposta: '⚠️ Limite diário de IA atingido (' + (raw.limite_usuario || 100) + ' pedidos por pessoa por dia). Use o formato do comando (mande "comandos" para ver); amanhã o limite volta.'
  }}];
}

if (raw?.error) {
  return [{ json: {
    numero: principal.numero,
    nomeContato: principal.nomeContato,
    comando_ia: null,
    reenviarComando: '',
    textoResposta: '⚠️ A IA está indisponível no momento. Tente de novo em alguns instantes ou use o formato do comando.'
  }}];
}

let texto = raw?.content?.parts?.[0]?.text ?? '';
texto = String(texto).replace(/```json|```/g, '').trim();

let ia;
try { ia = JSON.parse(texto); } catch (e) { ia = { intencao: 'desconhecido' }; }

const tanques = Array.isArray(ia.tanques)
  ? ia.tanques.map(t => String(t).trim().toUpperCase()).filter(Boolean)
  : [];
const dataOk = /^\d{2}\/\d{2}\/\d{4}$/.test(ia.data || '');

// Consultas: só leem a planilha, então executam direto, sem pedir "sim"
const CONSULTAS = {
  consulta_drops: 'drops para hoje',
  consulta_analises_terra: 'Quais analises de tanques terra saem hoje?',
  consulta_analises_navio: 'Quais analises de tanques navio saem hoje?',
  consulta_bags: 'Quais bags posso descartar hoje',
  consulta_potes: 'Quais potes do navio posso descartar hoje'
};

if (CONSULTAS[ia.intencao]) {
  return [{ json: {
    numero: principal.numero,
    nomeContato: principal.nomeContato,
    comando_ia: null,
    reenviarComando: CONSULTAS[ia.intencao],
    textoResposta: ''
  }}];
}

// Reanálise/repetição nunca vira análise nova (spec NFC, decisão 11): a repetição é só
// para tanque que deu não ok, com desvio aberto. Validado no código, não no prompt (Bug 23).
// "coletado por": nome de quem coletou quando foi outra pessoa (eu/mim/vazio = quem mandou, nao entra no comando)
const nomeColetaIa = (ia) => String(ia.coletado_por || '').replace(/\s+/g, ' ').trim();
const nomeColetaOk = (n) => { const x = String(n || '').trim(); return /^(mim|eu|me)$/i.test(x) || (x.length <= 40 && /^\p{L}+(?:['. -]?\p{L}+)*\.?$/u.test(x)); };
const coletadoPorIa = (ia) => { const n = nomeColetaIa(ia); return n && !/^(mim|eu|me)$/i.test(n) ? ' coletado por ' + n : ''; };
if (ia.intencao === 'registro_analise' && /res*-?s*an[aá]lis|repeti[cç]/i.test(principal.mensagem_original || '')) {
  return [{ json: {
    numero: principal.numero,
    nomeContato: principal.nomeContato,
    comando_ia: null,
    reenviarComando: '',
    textoResposta: '⚠️ Repetição (reanálise) não é análise nova: vale só para tanque que deu não ok, com desvio aberto. Para registrar a repetição: repetição do tanque 47 stress bl120. Nada foi gravado.'
  }}];
}

let comando = null, erro = null, leituraCmd = null;
const tipoIA = String(ia.tipo || '').toLowerCase();
const tipoOk = tipoIA === 'terra' || tipoIA === 'navio';
const navioIA = (tipoIA === 'navio' && ia.navio) ? ' ' + String(ia.navio).trim() : '';

const ESCRITAS = ['coleta_terra', 'coleta_navio', 'registro_analise', 'concluir_drops', 'concluir_leitura'];
const nivel = principal.nivelAtual;

// --- Intenção "comando": o Gemini reescreveu a frase num formato oficial do CATÁLOGO do prompt.
// A IA só sugere. A classe decide se roda direto ou pede "sim", e o comando volta ao webhook,
// onde a regex e as permissões rodam de novo (a IA nunca grava o que o código não aceitaria).
//   consulta: só lê, roda direto.  pede_sim: o fluxo do próprio comando já pergunta "sim".
//   grava: o fluxo do comando grava direto, então a IA pergunta "sim" antes.
const CLASSES_IA = [
  ['pede_sim', /^(tabs?|coliformes?) de hoje (espalhados?|estriados?|lidos?)$/],
  ['pede_sim', /^confirmacao (do |da )?tabs? /],
  ['pede_sim', /^coliformes? (da composta )?#\d+ em confirmacao$/],
  ['pede_sim', /^composta .*coliformes? em confirmacao$/],
  ['pede_sim', /^coliformes? (da composta )?#\d+\.\d+ (positivo|negativo)$/],
  ['pede_sim', /^composta .*(positivo|negativo)$/],
  ['pede_sim', /^howard #\d+ /],
  ['pede_sim', /^analise da composta de howard /],
  ['pede_sim', /^(ct|cts|bls?|bl ?72|bl ?120) nfc load .* deu /],
  ['pede_sim', /^(ct|cts|bls?|bl ?72|bl ?120) (load|navio) .* deu /],
  ['pede_sim', /^(leituras? (do dia |de hoje )?finalizadas?|finalizar (a )?leituras?( do dia| de hoje)?)$/],
  ['pede_sim', /^drops? d ?(5|10|15) .*nao ok$/],
  ['pede_sim', /^desvios? (do )?drops? /],
  ['pede_sim', /^(c\.?t|bl ?72|bl ?120|bl|wort (profundidade|superficie) (120|240)) ?h? (do |da )?tanques? /],
  ['pede_sim', /^(c\.?t|bl ?72|bl ?120|bl|wort (profundidade|superficie) (120|240)) ?h? (de )?tod[oa]s (os )?tanques /],
  ['pede_sim', /^(repeticao|reanalise) /],
  ['consulta', /^relatorio\b/],
  ['consulta', /^(quais|qual|temos|tem) /],
  ['grava', /^recebimento nfc /],
  ['grava', /^recebimento (do )?load /],
  ['grava', /^compostas? do (load|navio) /],
  ['grava', /^(tabs?|coliformes?) feitos? /],
  ['grava', /^tabs? (da composta |#\d+|tanque ).*em confirmacao$/],
  ['grava', /^embarque navio /],
  ['grava', /^(corrigir|alterar|trocar|apagar|cancelar|remover|excluir) coleta /]
];
const normIA = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ').replace(/[?!.]+$/, '').trim();

if (ia.intencao === 'incompleto') {
  return [{ json: { numero: principal.numero, nomeContato: principal.nomeContato, comando_ia: null, reenviarComando: '',
    textoResposta: `❓ Faltou ${String(ia.falta || 'um dado').trim()} para eu montar o comando. Pode mandar de novo com essa informação?` } }];
}

if (ia.intencao === 'comando') {
  const cmdIA = String(ia.comando || '').replace(/\s+/g, ' ').trim();
  const achada = CLASSES_IA.find(([, re]) => re.test(normIA(cmdIA)));
  const classe = achada ? achada[0] : null;
  let erroIA = null;
  if (!cmdIA || !classe) {
    erroIA = 'Não consegui transformar sua mensagem num comando válido. Para ver a lista de comandos, escreva o que procura. Por exemplo: *consultar drops*';
  } else if (nivel === 'Coletor' && !/^(corrigir|alterar|trocar|apagar|cancelar|remover|excluir) coleta /.test(normIA(cmdIA))) {
    erroIA = 'O seu cargo (Coletor) permite só registrar coletas e corrigir as suas próprias coletas.';
  } else if (classe !== 'consulta' && nivel === 'Consultor') {
    erroIA = 'Consultores têm acesso somente de consulta. Peça a um administrador para registrar isso.';
  }
  if (erroIA) {
    return [{ json: { numero: principal.numero, nomeContato: principal.nomeContato, comando_ia: null, reenviarComando: '',
      textoResposta: `❌ ${erroIA}` } }];
  }
  if (classe !== 'grava') {
    return [{ json: { numero: principal.numero, nomeContato: principal.nomeContato, comando_ia: null,
      reenviarComando: cmdIA, textoResposta: '' } }];
  }
  return [{ json: { numero: principal.numero, nomeContato: principal.nomeContato, comando_ia: cmdIA, reenviarComando: '',
    idsCSV: 'IA', novosStatusCSV: 'IA', resumo: cmdIA,
    criadoEm: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    textoResposta: `🤖 Entendi:\n${cmdIA}\n\nResponda *sim* para confirmar ou *não* para cancelar.` } }];
}

if (nivel === 'Coletor' && !['coleta_terra', 'coleta_navio', 'incompleto', 'desconhecido'].includes(ia.intencao)) {
  erro = 'O seu cargo (Coletor) permite só registrar coletas e corrigir as suas próprias coletas.';
} else if (nivel === 'Consultor' && (ESCRITAS.includes(ia.intencao) || ia.intencao === 'gerenciar_cargo')) {
  erro = 'Consultores têm acesso somente de consulta. Peça a um administrador para registrar isso.';
} else if (ia.intencao === 'gerenciar_cargo' && nivel && nivel !== 'Admin') {
  erro = 'Só administradores podem alterar cargos de usuários.';
} else if (ia.intencao === 'gerenciar_cargo') {
  // O cargo e o telefone precisam estar escritos na mensagem original: a IA não pode inventar nem "consertar"
  const msg = String(principal.mensagem_original || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const mencionados = new Set();
  if (/\badmin(istrador)?\b/.test(msg)) mencionados.add('Admin');
  if (/\b(analista|operador)\b/.test(msg)) mencionados.add('Analista');  // operador = nome antigo
  if (/\bconsultor\b/.test(msg)) mencionados.add('Consultor');
  if (/\bcoletor\b/.test(msg)) mencionados.add('Coletor');
  const cargo = { admin: 'Admin', administrador: 'Admin', analista: 'Analista', operador: 'Analista', consultor: 'Consultor', coletor: 'Coletor' }[String(ia.cargo || '').trim().toLowerCase()];
  const telDigitado = String(ia.telefone || '').replace(/\D/g, '');
  let tel = telDigitado;
  if (/^\d{10,11}$/.test(tel)) tel = '55' + tel;
  const nome = ia.nome ? String(ia.nome).replace(/\s+/g, ' ').trim() : '';
  if (!cargo || !mencionados.has(cargo)) erro = 'Cargo inválido. Use Admin, Analista, Consultor ou Coletor.';
  else if (!/^\d{12,13}$/.test(tel) || !msg.replace(/\D/g, '').includes(telDigitado)) erro = 'Não identifiquei o número do usuário com DDD (ex: 55 + DDD + número).';
  else comando = `trocar cargo de ${cargo} para o número ${tel}${nome ? ' nome ' + nome : ''}`;
} else if (ia.intencao === 'coleta_terra') {
  if (ia.coletado_por && !nomeColetaOk(ia.coletado_por)) erro = 'Não entendi o nome de quem coletou.';
  else if (!tanques.length || !tanques.every(t => /^\d+$/.test(t))) erro = 'Não identifiquei os tanques de terra.';
  else if (tanques.length > 8) erro = 'Limite de 8 tanques de terra por mensagem.';
  else if (!dataOk) erro = 'Faltou a data da coleta (dd/mm/aaaa).';
  else comando = `registrar coleta tanque terra ${tanques.join(',')} data ${ia.data}${coletadoPorIa(ia)}`;
} else if (ia.intencao === 'coleta_navio') {
  if (ia.coletado_por && !nomeColetaOk(ia.coletado_por)) erro = 'Não entendi o nome de quem coletou.';
  else if (!ia.navio) erro = 'Faltou o nome do navio com a viagem (ex: O.SKY 123).';
  else if (!tanques.length || !tanques.every(t => /^\d+[CPSAF]?$/.test(t))) erro = 'Não identifiquei os tanques do navio.';
  else if (tanques.length > 16) erro = 'Limite de 16 tanques de navio por mensagem.';
  else if (!dataOk) erro = 'Faltou a data da coleta (dd/mm/aaaa).';
  else comando = `Coleta navio ${String(ia.navio).trim()} tanques ${tanques.join(',')} data ${ia.data}${coletadoPorIa(ia)}`;
} else if (ia.intencao === 'registro_analise') {
  const analise = String(ia.analise || '').toLowerCase();
  const ehNavio = !!ia.navio;
  const limite = ehNavio ? 16 : 8;
  const tanqueOk = ehNavio ? /^\d+[CPSAF]?$/ : /^\d+$/;
  if (!['normal', 'stress'].includes(analise)) erro = 'Faltou dizer se a análise é normal ou stress.';
  else if (!tanques.length || !tanques.every(t => tanqueOk.test(t))) erro = 'Não identifiquei os tanques da análise.';
  else if (tanques.length > limite) erro = `Limite de ${limite} tanques por mensagem.`;
  else if (!dataOk) erro = 'Faltou a data da análise (dd/mm/aaaa).';
  else comando = `Analise ${analise} tanques ${tanques.join(',')}${ehNavio ? ' navio ' + String(ia.navio).trim() : ''} data ${ia.data}`;
} else if (ia.intencao === 'concluir_drops') {
  const dia = String(ia.dia || '').toUpperCase();
  if (!tipoOk) erro = 'Não deu para saber se os drops são de terra ou de navio.';
  else if (dia && !['D5', 'D10', 'D15'].includes(dia)) erro = 'Dia de drop inválido. Use D5, D10 ou D15.';
  else comando = `Concluir drops ${dia ? dia + ' ' : ''}${tipoIA}${navioIA}`;
} else if (ia.intencao === 'concluir_leitura') {
  const fase = String(ia.fase || '').toLowerCase();
  const leitura = String(ia.leitura || '').toUpperCase();
  const analise = String(ia.analise || '').toLowerCase();
  if (!tipoOk) erro = 'Não deu para saber se a leitura é de terra ou de navio.';
  else if (fase && !['pre', 'final'].includes(fase)) erro = 'Fase inválida. Use pre ou final.';
  else if (leitura && !['CT', 'BL', 'WORT'].includes(leitura)) erro = 'Leitura inválida. Use CT, BL ou WORT.';
  else if (analise && !['normal', 'stress'].includes(analise)) erro = 'Análise inválida. Use normal ou stress.';
  else leituraCmd = `Concluir ${fase ? fase + ' ' : ''}leitura ${leitura ? leitura + ' ' : ''}${analise ? analise + ' ' : ''}${tipoIA}${navioIA}`;
} else {
  erro = 'Comando inválido. Se desejar consultar a lista de comandos, escreva o que procura. Por exemplo: *consultar drops*\n\n' +
    'Opções: drops, tanques, análises, leituras, descarte, cargos, relatório.';
}

// Concluir leitura já lista e pede "sim" no fluxo normal: não pede confirmação duas vezes
if (leituraCmd) {
  return [{ json: {
    numero: principal.numero,
    nomeContato: principal.nomeContato,
    comando_ia: null,
    reenviarComando: leituraCmd,
    textoResposta: ''
  }}];
}

const criadoEm = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{ json: {
  numero: principal.numero,
  nomeContato: principal.nomeContato,
  comando_ia: comando,
  reenviarComando: '',
  idsCSV: 'IA',
  novosStatusCSV: 'IA',
  resumo: comando,
  criadoEm,
  textoResposta: comando
    ? `🤖 Entendi:\n${comando}\n\nResponda *sim* para confirmar ou *não* para cancelar.`
    : `❌ ${erro}`
}}];

