parameters.jsCode:
// Gravação já feita no node anterior, pela registrar_recebimento (040, a mesma do app). Monta a resposta do recebimento.
const item = $('Interpretar comando').first().json;
let r = $input.first().json.r;
if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) { r = null; } }

// [1,2,3,5,7,8] -> "1-3, 5, 7-8"
function compactar(lista) {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${ns[i]}` : `${ns[i]}-${ns[j]}`);
    i = j;
  }
  return partes.join(', ');
}

if (!r) return [{ json: { ...item, textoResposta: '❌ Não consegui registrar o recebimento. Nada foi gravado.' } }];
if (!r.ok) return [{ json: { ...item, textoResposta: `❌ ${r.erro} Nada foi gravado.` } }];

const novos = Array.isArray(r.novos) ? r.novos.map(Number) : [];
const repetidos = Array.isArray(r.repetidos) ? r.repetidos.map(Number) : [];
const linhas = [`✅ Recebimento do load ${item.load} (item ${item.item}, fábrica ${item.fabrica}) registrado por ${item.nomeContato}.`, ''];
if (novos.length) linhas.push(`Lotes recebidos: ${compactar(novos)} (${novos.length})`);
if (repetidos.length) linhas.push(`Já recebidos antes (ignorados): ${compactar(repetidos)}`);
if (item.fabricaLida) linhas.push(`ℹ️ Li a fábrica como "${item.fabricaLida}" e entendi ${item.fabrica}. Se estiver errado, avise.`);
linhas.push(`Data: ${item.dataRecebimento}`);
if (item.resultadosMenor10 && Number(r.resultados_gravados) > 0) linhas.push(`🧪 C.T, B.L 72h e B.L 120h dos lotes novos gravados como <10 (sem crescimento): ${Number(r.resultados_gravados)} resultados.`);
if (!novos.length) linhas[0] = `ℹ️ Load ${item.load}: todos esses lotes já tinham sido recebidos. Nada novo foi gravado.`;

return [{ json: { ...item, textoResposta: linhas.join('\n') } }];

