const r = $input.first().json;
const item0 = $('Interpretar comando').first().json;
const ehNfc = !!item0.refTanque;
const item = { ...item0, compostaId: item0.compostaId || r.composta_id || '?' };
// o banco recusou (teste_acao, 043): nada foi alterado
if (r.teste_erro) return [{ json: { ...item, textoResposta: '❌ ' + r.teste_erro + ' Nada foi alterado.' } }];
const alvo = ehNfc ? `do tanque ${item0.refTanque} (coleta ${item0.refDataColeta})` : `#${item.compostaId}`;

let texto;
if (!r.status_antes) {
  texto = ehNfc
    ? `❌ O tanque ${item0.refTanque} não tem TAB com coleta em ${item0.refDataColeta}.`
    : `❌ A composta #${item.compostaId} não tem TAB.`;
} else if (Number(r.atualizado) === 0) {
  texto = `❌ O TAB ${alvo} está "${masc(r.status_antes)}". Só TAB incubado vai para confirmação.`;
} else {
  const c = r.composta || {};
  const nome = ehNfc
    ? `do tanque ${item0.refTanque} (coleta ${item0.refDataColeta})`
    : `#${item.compostaId} ${c.rotulo || 'load ' + c.load} (${compactar(c.lotes || [], c.prefixo || '')})`;
  const cmdResultado = ehNfc
    ? `confirmação do tab tanque terra ${item0.refTanque} coleta ${item0.refDataColeta} positivo (ou negativo)`
    : `confirmação do tab #${item.compostaId} positivo (ou negativo)`;
  texto = `✅ TAB ${nome} em confirmação (PCA 24h), por ${item.nomeContato}.\n` +
    `Ler em ${r.ler_em}. Resultado: ${cmdResultado}`;
}

return [{ json: { ...item, textoResposta: texto } }];

// Gravação já feita no node anterior. Monta a resposta do embarque.
const r = $input.first().json;
const item = $('Interpretar comando').first().json;
// o banco recusou (registrar_embarque, 045): nada foi gravado
if (r.erro) return [{ json: { ...item, textoResposta: `❌ ${r.erro} Nada foi gravado.` } }];

// [1,2,3,5,7,8] -> "A1-A3, A5, A7-A8"
function compactar(lista, pref = '') {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${pref}${ns[i]}` : `${pref}${ns[i]}-${pref}${ns[j]}`);
    i = j;
  }
  return partes.join(', ');
}

const novas = Array.isArray(r.novas) ? r.novas : [];
const existentes = Array.isArray(r.existentes) ? r.existentes : [];
const repetidas = item.amostras.filter(a => !novas.includes(a));
const rotulo = `${item.navio} linha ${item.linha} fase ${item.fase}`;

const linhas = [];
if (!novas.length) {
  linhas.push(`ℹ️ ${rotulo}: todas essas amostras já estavam registradas. Nada novo foi gravado.`);
} else {
  linhas.push(`✅ Embarque registrado por ${item.nomeContato}: ${rotulo}, load ${item.load} (item ${item.item}).`, '');
  linhas.push(`Amostras: ${compactar(novas, 'A')} (${novas.length})`);
}
if (repetidas.length) {
  const detalhe = repetidas.map(a => {
    const e = existentes.find(x => Number(x.numero) === a);
    return e ? `A${a} (load ${e.load})` : `A${a}`;
  }).join(', ');
  linhas.push(`Já registradas antes (ignoradas): ${detalhe}`);
}
linhas.push(`Data: ${item.dataEmbarque}`);

if (r.load_novo) {
  linhas.push('', `⚠️ O load ${item.load} (item ${item.item}) não estava cadastrado: cadastrei agora, sem fábrica. Confira se o número do load e o item estão certos.`);
}
if (r.outros_itens) {
  linhas.push('', `⚠️ Já existe o load ${item.load} com outro item (${r.outros_itens}). Se o item digitado estiver errado, avise um administrador.`);
}

return [{ json: { ...item, textoResposta: linhas.join('\n') } }];

parameters.query:
-- Compostas do embarque pela criar_compostas_embarque (045, a mesma do app): uma composta (#N) por grupo de amostras.
-- $1 navio e viagem, $2 linha, $3 fase, $4 grupos (jsonb), $5 telefone. Erro da regra em r.erro.
SELECT compostas_embarque_criar_pelo_bot($5::text, $1::text, $2::text, $3::text, $4::jsonb) AS r;

parameters.jsCode:
// Gravação já feita (ou recusada) no node anterior, pela criar_compostas_embarque (045, a mesma do app).
let r = $input.first().json.r;
if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) { r = null; } }
const item = $('Interpretar comando').first().json;

function compactar(lista, pref = '') {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${pref}${ns[i]}` : `${pref}${ns[i]}-${pref}${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}

const rotulo = `${item.navio} linha ${item.linha} fase ${item.fase}`;
let texto;
if (!r) {
  texto = '❌ Não consegui criar as compostas. Nada foi gravado.';
} else if (!r.ok && /não encontrado/.test(r.erro || '')) {
  texto = `❌ Embarque ${rotulo} não encontrado. Registre o embarque primeiro: embarque navio ${item.navio} linha ${item.linha} fase ${item.fase} load 77010 item 444 amostras 1-10`;
} else if (!r.ok) {
  texto = `❌ ${r.erro} Nada foi gravado.`;
} else {
  const ids = Array.isArray(r.ids) ? r.ids : [];
  const linhas = item.compostas.map((amostras, i) => `#${ids[i]} amostras ${compactar(amostras, 'A')}`);
  texto = `✅ ${ids.length} composta${ids.length === 1 ? '' : 's'} criada${ids.length === 1 ? '' : 's'} em ${rotulo}:\n${linhas.join('\n')}\n\nUse o número (#) nos próximos comandos, ex.: tab feito das compostas #${ids[0]}`;
}

return [{ json: { ...item, textoResposta: texto } }];

// Pergunta antes de gravar o Howard (a gravação acontece depois do "sim", em "BD · Atualizar TABs").
function compactar(lista, pref = '') {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${pref}${ns[i]}` : `${pref}${ns[i]}-${pref}${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}
const r = $input.all().map(i => i.json).find(x => x.composta_id);
const item = $('Interpretar comando').first().json;
const erro = t => [{ json: { ...item, salvar: false, payload: '{}', resumo: '', textoResposta: t } }];

if (!r) {
  const ref = item.compostaId
    ? `#${item.compostaId}`
    : `${item.refNavio} linha ${item.refLinha} fase ${item.refFase} (${compactar((item.refGrupos || [])[0] || [], 'A')})`;
  return erro(`❌ Não achei a composta ${ref}. Crie a composta do embarque primeiro: compostas do navio O.SKY 133 linha 2 fase 2 (A1-A5)`);
}
if (r.origem !== 'embarque') {
  return erro(`❌ Howard só vale para composta de embarque. A #${r.composta_id} é do recebimento (${r.rotulo}).`);
}

const nome = `#${r.composta_id} ${r.rotulo} (${compactar(r.lotes, 'A')})`;
const perc = Number(item.percentual);
const campos = perc / 2;
const campoTxt = `${campos} campo${campos === 1 ? '' : 's'} positivo${campos === 1 ? '' : 's'} de 50`;
const antes = (r.howard_atual === null || r.howard_atual === undefined || r.howard_atual === '') ? null : Number(r.howard_atual);
const aviso = antes === null ? '' : `\n⚠️ Essa composta já tem Howard (${antes}%). O novo valor substitui o anterior.`;

return [{ json: { ...item, salvar: true,
  payload: JSON.stringify({ acao: 'howard', tipo: 'HOWARD', ids: [Number(r.composta_id)], percentual: perc }),
  resumo: `Howard ${perc}% (${campoTxt}) — ${nome}`,
  textoResposta: `❓ Gravar Howard *${perc}%* (${campoTxt})?\n${nome}${aviso}\n\nResponda *sim* ou *não*.` } }];

// Consultas do Howard: compostas de embarque sem Howard e Howards gravados hoje.
function compactar(lista, pref = '') {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${pref}${ns[i]}` : `${pref}${ns[i]}-${pref}${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}
const rows = $input.all().map(i => i.json).filter(r => r.composta_id);
const item = $('Interpretar comando').first().json;
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const nome = r => `#${r.composta_id} ${r.rotulo} (${compactar(r.lotes, r.prefixo || 'A')})`;

let texto;
if (item.etapa === 'lidos') {
  texto = rows.length
    ? `✅ Howards lidos hoje (${hoje}):\n` + rows.map(r => `${nome(r)} — ${Number(r.percentual)}%`).join('\n')
    : `Nenhum Howard lido hoje (${hoje}).`;
} else {
  texto = rows.length
    ? `🔬 Compostas de embarque sem Howard (${hoje}):\n` + rows.map(nome).join('\n') + '\n\nPara registrar: howard #N 2%'
    : `Todas as compostas de embarque já têm Howard (${hoje}).`;
}
return [{ json: { ...item, textoResposta: texto } }];

// Gravação já feita (ou recusada) no node anterior. Resposta do "tab feito dos tanques terra ... coleta ...".
// Admin com tanque sem coleta: vira pergunta; o "sim" roda o comando "completo" (coleta, análises, placas <1 e TAB).
const r = $input.first().json;
const item = $('Interpretar comando').first().json;

const criados = Array.isArray(r.criados) ? r.criados : [];
// vários grupos de coleta: o nome de cada tanque já vem com a data ("39 (coleta 17/10)")
const multi = Array.isArray(item.grupos) && new Set(item.grupos.map((g) => g.coleta)).size > 1;
const emColeta = multi ? '' : ` em ${item.dataColeta}`;
const faltam = String(r.sem_coleta || '').split(',').map(s => s.trim()).filter(Boolean);
if (faltam.length && !item.completo && item._nivelAtual === 'Admin') {
  const comando = `Tab feito dos tanques terra ${item.gruposTxt || item.tanques.join(',') + ' coleta ' + item.dataColeta} data ${item.dataFeito} completo`;
  // pergunta objetiva (combinado em 21/10/2026); o "sim" faz o completo: coleta, análises, placas <1 vencidas e TAB
  const varios = faltam.length > 1;
  const onde = multi ? '' : ` (coleta ${item.dataColeta})`;
  const outros = item.tanques.length > faltam.length
    ? ` e o TAB dos tanques ${item.tanques.join(', ')}`
    : ' e o TAB';
  const texto = `❓ ${varios ? 'Tanques' : 'Tanque'} ${faltam.join(', ')}${onde}: não há coleta no sistema.\n` +
    `Registrar ${varios ? 'as coletas' : 'a coleta'}${outros}? Responda *sim* ou *não*.`;
  return [{ json: { ...item, salvar: '1', tipoPendencia: 'IA', payload: JSON.stringify({ comandos: [comando] }), resumo: comando, textoResposta: texto } }];
}

let texto;
if (r.sem_coleta) {
  texto = `❌ Não há coleta de terra do(s) tanque(s) ${r.sem_coleta}${emColeta}. Nada foi gravado.\nConfira o número e a data da coleta.` +
    (item.completo ? '' : '\nSó um Admin registra o TAB junto com a coleta: peça a ele, ou registre a coleta antes.');
} else if (!criados.length) {
  texto = `ℹ️ Tanque(s) ${r.ja_tinham} já tinha(m) TAB${multi ? '' : ` nessa coleta (${item.dataColeta})`}. Nada novo foi gravado.`;
} else {
  const linhas = criados.map(t => multi ? `tanque ${t}` : `tanque ${t} (coleta ${item.dataColeta})`);
  texto = `🧪 TAB de NFC no caldo (${criados.length} tanque${criados.length === 1 ? '' : 's'}), feito por ${item.nomeContato} em ${item.dataFeito}:\n` +
    `${linhas.join('\n')}\n\nEspalhar em ${r.espalhar_em}.`;
  if (r.ja_tinham) texto += `\nJá tinham TAB (ignorados): ${r.ja_tinham}`;
}
if (item.completo && !r.sem_coleta) {
  if (r.coletas_criadas) texto += `\n🆕 Coleta registrada (com os drops D5, D10, D15 e o arquivo): tanque ${r.coletas_criadas}${multi ? '' : ', ' + item.dataColeta}.`;
  if (Number(r.frascos_novos)) texto += `\n🧪 Análises registradas (C.T, B.L e WORT) em ${Number(r.frascos_novos)} frasco(s) normal/stress que não tinham.`;
  const leituras = Math.round(Number(r.placas_gravadas) / 3);
  if (leituras) texto += `\n✅ Placas <1,<1,<1 marcadas em ${leituras} leitura${leituras === 1 ? '' : 's'} que já venceram até ${item.dataFeito}; o que ainda não chegou na data ficou sem marcar.`;
  else texto += `\nℹ️ Nenhuma leitura tinha vencido até ${item.dataFeito}: nada de placa marcada.`;
  const nDrops = Number(r.drops_marcados);
  if (nDrops) texto += `\n💧 ${nDrops} drop${nDrops === 1 ? '' : 's'} (D5, D10, D15) já vencido${nDrops === 1 ? '' : 's'} até ${item.dataFeito} marcado${nDrops === 1 ? '' : 's'} como feito${nDrops === 1 ? '' : 's'}; os que ainda não chegaram na data seguem pendentes.`;
}

return [{ json: { ...item, salvar: '0', payload: '{}', textoResposta: texto } }];

// Pergunta antes de gravar os resultados de C.T / B.L. A gravação acontece depois do "sim",
// em "BD · Atualizar TABs" (ação "contagem"). Lote ou amostra que não existe cancela tudo.
function compactar(lista, pref = '') {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${pref}${ns[i]}` : `${pref}${ns[i]}-${pref}${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}
const LIMITE = { CT: 200, BL72: 50, BL120: 50 };
const ROTULO = { CT: 'C.T 48h', BL72: 'B.L 72h', BL120: 'B.L 120h' };

// Com "todos", o banco acrescenta os que saem na data e ainda não têm resultado (via_todos) e devolve sempre uma linha.
const todasLinhas = $input.all().map(i => i.json);
const rows = todasLinhas.filter(r => r.numero !== undefined && r.numero !== null);
const item = $('Interpretar comando').first().json;
const erro = t => [{ json: { ...item, salvar: false, payload: '{}', resumo: '', textoResposta: t } }];
const ehEmbarque = item.origem === 'embarque';
const pref = ehEmbarque ? 'A' : '';
const palavra = ehEmbarque ? 'amostra' : 'lote';
const alvoTxt = ehEmbarque ? `${item.navio} linha ${item.linha} fase ${item.fase}` : `load ${item.load}${item.item ? ' item ' + item.item : ''}`;

const loadsAchados = todasLinhas.length ? Number(todasLinhas[0].loads_encontrados) : 0;
const embAchados = todasLinhas.length ? Number(todasLinhas[0].embarques_encontrados) : 0;
if (ehEmbarque && embAchados === 0) {
  return erro(`❌ Embarque ${alvoTxt} não encontrado. Registre o embarque primeiro: embarque navio ${item.navio} linha ${item.linha} fase ${item.fase} load 77010 item 444 amostras 1-10`);
}
if (!ehEmbarque && loadsAchados === 0) {
  return erro(`❌ Load ${item.load}${item.item ? ' item ' + item.item : ''} não encontrado. Registre o recebimento primeiro.`);
}
if (!ehEmbarque && loadsAchados > 1) {
  return erro(`❌ Existe mais de um load ${item.load}. Informe o item: ${item.analise === 'CT' ? 'ct' : item.analise.toLowerCase()} load ${item.load} item 444 lote 4 deu 10`);
}
const faltam = rows.filter(r => r.alvo_id === null || r.alvo_id === undefined).map(r => Number(r.numero));
if (faltam.length) {
  return erro(`❌ ${faltam.length === 1 ? `${palavra[0].toUpperCase() + palavra.slice(1)} ${pref}${faltam[0]} não foi ${ehEmbarque ? 'registrada' : 'recebido'}` : `${palavra[0].toUpperCase() + palavra.slice(1)}s ${compactar(faltam, pref)} não foram ${ehEmbarque ? 'registradas' : 'recebidos'}`} em ${alvoTxt}. Nada foi gravado.`);
}

const idPorNumero = {};
const atualPorNumero = {};
rows.forEach(r => { idPorNumero[Number(r.numero)] = Number(r.alvo_id); atualPorNumero[Number(r.numero)] = r.atual; });

const fmtValor = (sinal, valor) => `${sinal === '=' ? '' : sinal}${String(valor).replace('.', ',')}`;
const limite = LIMITE[item.analise];
const nomeAn = ROTULO[item.analise];
const viaTodos = rows.filter(r => r.via_todos === true || r.via_todos === 't').map(r => Number(r.numero)).sort((a, b) => a - b);
const infos = [];
if (item.todos) {
  const excl = (item.excluidos || []).map(Number);
  if (!viaTodos.length && !item.grupos.length) {
    return erro(`ℹ️ Nenhum ${palavra} de ${alvoTxt} com ${nomeAn} para ${item.todos.data} sem resultado${excl.length ? ` (fora: ${compactar(excl, pref)})` : ''}. Nada foi gravado.` +
      `\nPara corrigir um ${palavra} que já tem resultado, mande o ${palavra}: ${item.analise.toLowerCase()} ${ehEmbarque ? `navio ${item.navio} linha ${item.linha} fase ${item.fase} amostra 3` : `load ${item.load} lote 3`} deu 20`);
  }
  if (!viaTodos.length) infos.push(`ℹ️ Nenhum outro ${palavra} com ${nomeAn} para ${item.todos.data} sem resultado.`);
  if (excl.length) infos.push(`Fora do "todos": ${palavra}${excl.length > 1 ? 's' : ''} ${compactar(excl, pref)}`);
}
const grupos = item.todos && viaTodos.length
  ? [{ numeros: viaTodos, sinal: item.todos.sinal, valor: item.todos.valor, todos: true }, ...item.grupos]
  : item.grupos;
const itens = [];
const linhas = [];
const alarmes = [];
const correcoes = [];
for (const g of grupos) {
  const v = fmtValor(g.sinal, g.valor);
  linhas.push(`${palavra}${g.numeros.length > 1 ? 's' : ''} ${compactar(g.numeros, pref)} = ${v}${g.todos ? ` (todos de ${item.todos.data} sem resultado)` : ''}`);
  for (const n of g.numeros) {
    itens.push({ id: idPorNumero[n], sinal: g.sinal, valor: g.valor });
    if (g.sinal !== '<' && g.valor >= limite) alarmes.push(`${pref}${n} = ${v}`);
    if (atualPorNumero[n] !== null && atualPorNumero[n] !== undefined && atualPorNumero[n] !== '') correcoes.push(`${pref}${n} (era ${String(atualPorNumero[n]).replace('.', ',')})`);
  }
}
const avisos = [...infos];
if (alarmes.length) avisos.push(`🚨 Acima do limite (${item.analise === 'CT' ? 'C.T' : 'B.L'} ≥ ${limite}): ${alarmes.join(', ')}`);
if (correcoes.length) avisos.push(`⚠️ Corrige resultado anterior: ${correcoes.join(', ')}`);

const resumo = `${nomeAn} — ${alvoTxt}:\n${linhas.join('\n')}` + (avisos.length ? `\n${avisos.join('\n')}` : '');
return [{ json: { ...item, salvar: true,
  payload: JSON.stringify({ acao: 'contagem', analise: item.analise, alvo: ehEmbarque ? 'amostra' : 'lote', itens }),
  resumo,
  textoResposta: `❓ Gravar ${nomeAn} — ${alvoTxt}?\n${linhas.join('\n')}` + (avisos.length ? `\n${avisos.join('\n')}` : '') + `\n\nResponda *sim* ou *não*.` } }];

// Consultas de C.T / B.L: o que vence hoje (com atrasados e a data prevista) e o que foi lido hoje.
function compactar(lista, pref = '') {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${pref}${ns[i]}` : `${pref}${ns[i]}-${pref}${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}
const ROTULO = { CT: 'C.T 48h', BL72: 'B.L 72h', BL120: 'B.L 120h' };
const LIMITE = { CT: 200, BL72: 50, BL120: 50 };
const rows = $input.all().map(i => i.json).filter(r => r.numero !== undefined && r.numero !== null);
const item = $('Interpretar comando').first().json;
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const nomeAn = ROTULO[item.analise];

// agrupa por onde (load, ou navio+linha+fase e load)
function agrupa(lista) {
  const grupos = new Map();
  for (const r of lista) {
    const chave = r.origem === 'embarque' ? `${r.rotulo} · load ${r.load}` : r.rotulo;
    if (!grupos.has(chave)) grupos.set(chave, { origem: r.origem, rows: [] });
    grupos.get(chave).rows.push(r);
  }
  return grupos;
}
const prefDe = origem => (origem === 'embarque' ? 'A' : '');

let texto;
if (!rows.length) {
  texto = item.etapa === 'lidos' ? `Nenhum ${nomeAn} lido hoje (${hoje}).` : `Nenhum ${nomeAn} para ler hoje (${hoje}).`;
} else if (item.etapa === 'lidos') {
  const linhas = [`✅ ${nomeAn} lidos hoje (${hoje}):`];
  for (const [chave, g] of agrupa(rows)) {
    const pref = prefDe(g.origem);
    const palavra = g.origem === 'embarque' ? 'amostra' : 'lote';
    const porResultado = new Map();
    g.rows.forEach(r => { const k = String(r.resultado).replace('.', ','); if (!porResultado.has(k)) porResultado.set(k, []); porResultado.get(k).push(r.numero); });
    const partes = [...porResultado].map(([res, nums]) => `${palavra}${nums.length > 1 ? 's' : ''} ${compactar(nums, pref)} = ${res}`);
    linhas.push(`${chave}: ${partes.join('; ')}`);
    const alarmes = g.rows.filter(r => r.alarme).map(r => `${pref}${r.numero} = ${String(r.resultado).replace('.', ',')}`);
    if (alarmes.length) linhas.push(`🚨 Acima do limite (≥ ${LIMITE[item.analise]}): ${alarmes.join(', ')}`);
  }
  texto = linhas.join('\n');
} else {
  const linhas = [`🔬 ${nomeAn} para ler hoje (${hoje}):`];
  const doDia = rows.filter(r => !r.atrasado);
  const linhaGrupo = (chave, g) => `${chave}: ${compactar(g.rows.map(r => r.numero), prefDe(g.origem))}`;
  if (doDia.length) { for (const [chave, g] of agrupa(doDia)) linhas.push(linhaGrupo(chave, g)); } else { linhas.push('-'); }
  const porData = new Map();
  rows.filter(r => r.atrasado).forEach(r => { if (!porData.has(r.prevista)) porData.set(r.prevista, []); porData.get(r.prevista).push(r); });
  for (const [data, lista] of porData) {
    linhas.push('', `⚠️ Atrasados — previsto ${data}:`);
    for (const [chave, g] of agrupa(lista)) linhas.push(linhaGrupo(chave, g));
  }
  texto = linhas.join('\n');
}

return [{ json: { ...item, textoResposta: texto } }];

// Relatório do dia: FCOJ (recebimento e embarque) e NFC (tank farm e navio), no formato do relatório
// oficial de microbiologia. Toda linha aparece, mesmo vazia ("-"), na ordem da planilha.
//   acompanhamento: tudo o que sai hoje; ✅ = lido, 🚨 = fora do limite (B.L >= 50, C.T >= 200; NFC: placa acima
//   do limite, com a contagem; Howard acima do limite) ou positivo
//   completo: só o que já foi lido, com a Situação (ok / não ok) nas linhas do concentrado
const nfcRows = $('BD · Relatório NFC').all().map(i => i.json).filter(r => r.linha);
const concRows = $('BD · Relatório concentrado').all().map(i => i.json).filter(r => r.linha);
const fin = $input.first().json;
// Desvios de drop do dia: drop "não ok" de hoje vira 🚨; leitura de desvio vencendo hoje entra na linha "Desvios"
const desvios = Array.isArray(fin && fin.desvios) ? fin.desvios : [];
const chaveDrop = (bloco, linha, tanque, navio) => [bloco, linha, tanque, navio || ''].join('|');
const dropsNaoOk = new Set(desvios.filter(d => d.drop_hoje).map(d => chaveDrop(d.bloco, d.linha, d.tanque, d.navio)));
const tempsTxt = (lista) => (lista || []).map(t => t + ' °C').join(', ');
const item = $('Interpretar comando').first().json;
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const completo = !!item.completo;
const blocosNfc = item.blocosNfc || [];
const blocosConc = item.blocosConc || [];

const estadoDe = r => (r.alarme ? '🚨' : (r.lido ? '✅' : ''));
const visivel = r => !completo || r.lido;
const LIMITE = { 'C.T 48h': 200, 'B.L 72h': 50, 'B.L 120h': 50 };

function faixas(nums) {
  const ns = [...new Set(nums.map(Number))].sort((a, b) => a - b);
  const out = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    out.push([ns[i], ns[j]]);
    i = j;
  }
  return out;
}
const txtFaixa = ([a, b], pref) => (a === b ? `${pref}${a}` : `${pref}${a}-${pref}${b}`);

// C.T / B.L: "1-5 ✅, 6 🚨, 7-14"  (cada trecho com o mesmo estado)
function tokensContagem(lista, pref) {
  const ord = [...lista].sort((a, b) => a.numero - b.numero);
  const out = [];
  let i = 0;
  while (i < ord.length) {
    const est = estadoDe(ord[i]);
    let j = i;
    while (j + 1 < ord.length && ord[j + 1].numero === ord[j].numero + 1 && estadoDe(ord[j + 1]) === est) j++;
    const txt = txtFaixa([ord[i].numero, ord[j].numero], pref);
    out.push(est ? `${txt} ${est}` : txt);
    i = j + 1;
  }
  return out;
}
const rotuloOnde = (onde, load) => (onde ? `${onde} - ${load}` : `${load}`);

let total = 0, lidos = 0;
const partes = [`📋 *Relatório do dia ${hoje}${completo ? ' — completo' : ''}*`];

// ---------------- FCOJ ----------------
const LINHAS_CONC = {
  'Recebimento': ['C.T 48h', 'B.L 72h', 'B.L 120h', 'TAB', 'Coliformes'],
  'Embarque': ['C.T 48h', 'B.L 72h', 'B.L 120h', 'Coliformes', 'Howard', 'TAB']
};
for (const bloco of ['Recebimento', 'Embarque']) {
  if (!blocosConc.includes(bloco)) continue;
  const pref = bloco === 'Embarque' ? 'A' : '';
  const palavra = bloco === 'Embarque' ? 'amostra' : 'lote';
  partes.push('', `*FCOJ — ${bloco}*`);
  const alertas = [];
  for (const linha of LINHAS_CONC[bloco]) {
    const todas = concRows.filter(r => r.bloco === bloco && r.linha === linha);
    total += todas.length;
    lidos += todas.filter(r => r.lido).length;
    const lista = todas.filter(visivel);
    let entradas = [];
    if (['C.T 48h', 'B.L 72h', 'B.L 120h'].includes(linha)) {
      const grupos = new Map();
      lista.forEach(r => { const k = `${r.onde}|${r.load}`; if (!grupos.has(k)) grupos.set(k, []); grupos.get(k).push(r); });
      for (const g of grupos.values()) {
        entradas.push(`${rotuloOnde(g[0].onde, g[0].load)} (${tokensContagem(g, pref).join(', ')})`);
        const alarmes = g.filter(r => r.alarme).sort((a, b) => a.numero - b.numero);
        if (alarmes.length) {
          alertas.push(`🚨 ${linha} ≥ ${LIMITE[linha]} — ${rotuloOnde(g[0].onde, g[0].load)}: ` +
            alarmes.map(r => `${palavra} ${pref}${r.numero} = ${String(r.resultado).replace('.', ',')}`).join(', '));
        }
      }
    } else if (linha === 'Howard') {
      entradas = lista.map(r => `${rotuloOnde(r.onde, r.load)} (${faixas(r.lotes).map(f => txtFaixa(f, pref)).join(',')}): ${r.resultado}${r.alarme ? ' 🚨' : ''}`);
      lista.filter(r => r.alarme).forEach(r => alertas.push(`🚨 Howard acima do limite — ${rotuloOnde(r.onde, r.load)} (${faixas(r.lotes).map(f => txtFaixa(f, pref)).join(',')}): ${r.resultado}`));
    } else {
      // TAB e Coliformes: uma composta por parêntese, "(1-5 ✅)(6-10 🚨)"
      const grupos = new Map();
      lista.forEach(r => { const k = `${r.onde}|${r.load}`; if (!grupos.has(k)) grupos.set(k, []); grupos.get(k).push(r); });
      for (const g of grupos.values()) {
        const parenteses = g.map(r => {
          const est = estadoDe(r);
          const txt = faixas(r.lotes).map(f => txtFaixa(f, pref)).join(',');
          return `(${txt}${est ? ' ' + est : ''})`;
        }).join('');
        entradas.push(`${rotuloOnde(g[0].onde, g[0].load)} ${parenteses}`);
        const positivas = g.filter(r => r.alarme);
        if (positivas.length) {
          alertas.push(`🚨 ${linha} POSITIVO — ${rotuloOnde(g[0].onde, g[0].load)} ` +
            positivas.map(r => `(${faixas(r.lotes).map(f => txtFaixa(f, pref)).join(',')})`).join(''));
        }
      }
    }
    let texto = entradas.length ? entradas.join('; ') : '-';
    if (completo && lista.length) texto += lista.some(r => r.alarme) ? ' — não ok' : ' — ok';
    partes.push(`${linha}: ${texto}`);
  }
  partes.push(...alertas);
}

// ---------------- NFC ----------------
const LINHAS_ANALISE = ['C.T 48h', 'B.L 72h', 'B.L 120h', 'Psicrotróficos 120h', 'Psicrotróficos 240h'];
const SECOES = [
  ['Normal', 'AMOSTRA NORMAL', LINHAS_ANALISE],
  ['Stress', 'AMOSTRA STRESS', LINHAS_ANALISE],
  ['Drops',  'DROPS',          ['Drop 5', 'Drop 10', 'Drop 15']]
];
const TITULOS = { 'Tank farm': 'NFC — Tank farm', 'Navio': 'NFC — Navio' };
const naoOkNfc = r => r.nao_ok || dropsNaoOk.has(chaveDrop(r.bloco, r.linha, r.tanque, r.navio));
const rotuloNfc = r => {
  const nome = r.repeticao ? `${r.tanque} (repetição)` : r.tanque;
  if (naoOkNfc(r)) return `${nome} 🚨${r.contagem ? ' (' + r.contagem + ')' : ''}`;
  return r.lido ? `${nome} ✅` : nome;
};
const desviosTanque = Array.isArray(fin && fin.desvios_tanque) ? fin.desvios_tanque : [];
function celulaNfc(lista, bloco) {
  if (lista.length === 0) return '-';
  if (bloco === 'Tank farm') return lista.map(rotuloNfc).join(', ');
  const porNavio = {};
  lista.forEach(r => (porNavio[r.navio || 'sem navio'] ??= []).push(rotuloNfc(r)));
  return Object.entries(porNavio).map(([navio, tanques]) => `${navio} (${tanques.join(', ')})`).join('; ');
}
for (const bloco of ['Tank farm', 'Navio']) {
  if (!blocosNfc.includes(bloco)) continue;
  partes.push('', `*${TITULOS[bloco]}*`);
  const alertasNfc = [];
  for (const [amostra, titulo, linhas] of SECOES) {
    partes.push('', titulo);
    for (const linha of linhas) {
      const todas = nfcRows.filter(r => r.bloco === bloco && r.amostra === amostra && r.linha === linha);
      total += todas.length;
      lidos += todas.filter(r => r.lido).length;
      const visiveis = todas.filter(visivel);
      let celula = celulaNfc(visiveis, bloco);
      if (completo && visiveis.length) celula += visiveis.some(naoOkNfc) ? ' — não ok' : ' — ok';
      partes.push(`${linha}: ${celula}`);
      todas.filter(r => r.nao_ok).forEach(r => alertasNfc.push(
        `🚨 ${linha} NÃO OK — tanque ${r.tanque}${r.navio ? ' (' + r.navio + ')' : ''} (${amostra}${r.repeticao ? ', repetição' : ''}): ${r.contagem || 'acima do limite'}`));
    }
    // Desvios de tanque (C.T, B.L e WORT não ok): em repetição ou fechados hoje, depois da amostra Stress
    if (amostra === 'Stress') {
      const dts = desviosTanque.filter(d => d.bloco === bloco);
      if (dts.length) {
        partes.push('', `Desvios de tanque: ${dts.map(d => `${d.tanque}${d.navio ? ' (' + d.navio + ')' : ''} ${d.analise} ${d.frasco} ` +
          (d.status === 'Em repetição' ? `(em repetição${d.ler_ate ? ', ler até ' + d.ler_ate : ''})` : (d.resultado === 'Não ok' ? '🚨 repetição não ok' : '✅ repetição ok'))).join(', ')}`);
        dts.filter(d => d.aberto_hoje).forEach(d => alertasNfc.push(
          `⚠️ Desvio criado do tanque ${d.tanque}${d.navio ? ' (' + d.navio + ')' : ''} (${d.analise}, ${d.frasco}): repetição com o frasco de arquivo`));
      }
    }
    // Drops não ok de hoje (desvio aberto) e leituras de desvio que vencem hoje
    if (amostra === 'Drops') {
      const doBloco = desvios.filter(d => d.bloco === bloco);
      doBloco.filter(d => d.drop_hoje).forEach(d => alertasNfc.push(
        `🚨 Drop D${d.dia} NÃO OK — tanque ${d.tanque}${d.navio ? ' (' + d.navio + ')' : ''} (coleta ${d.coleta}): desvio aberto, ler até ${d.ler_ate}`));
      const leituras = doBloco.filter(d => d.ler_hoje || d.lido_hoje || (d.status === 'Em confirmação' && !d.drop_hoje));
      total += leituras.length;
      lidos += leituras.filter(d => d.status === 'Concluído').length;
      const txt = leituras.filter(d => !completo || d.status === 'Concluído').map(d => {
        const nome = `${d.tanque} D${d.dia}`;
        if (d.status !== 'Concluído') return `${nome} (ler até ${d.ler_ate})`;
        return d.resultado === 'Confirmado' ? `${nome} 🚨 confirmou em ${tempsTxt(d.temperaturas)}` : `${nome} ✅ não confirmado`;
      }).join(', ');
      if (leituras.length || doBloco.length) partes.push(`Desvios: ${txt || '-'}`);
      leituras.filter(d => d.resultado === 'Confirmado').forEach(d => alertasNfc.push(
        `🚨 Desvio CONFIRMADO — drop D${d.dia} do tanque ${d.tanque} (coleta ${d.coleta}) em ${tempsTxt(d.temperaturas)}`));
    }
    // TAB do tank farm, por tanque (com a data da coleta)
    if (amostra === 'Drops' && bloco === 'Tank farm') {
      const tabs = concRows.filter(r => r.bloco === 'Tank farm' && r.linha === 'TAB');
      total += tabs.length;
      lidos += tabs.filter(r => r.lido).length;
      const lista = tabs.filter(visivel);
      const txt = lista.map(r => {
        const est = estadoDe(r);
        return `${r.tanque} (coleta ${String(r.data_coleta).slice(0, 5)})${est ? ' ' + est : ''}`;
      }).join(', ');
      partes.push(`TAB: ${txt || '-'}`);
      tabs.filter(r => r.alarme).forEach(r => alertasNfc.push(`🚨 TAB POSITIVO — tanque ${r.tanque} (coleta ${String(r.data_coleta).slice(0, 5)})`));
    }
  }
  partes.push(...alertasNfc);
}

// ---------------- rodapé ----------------
const nAlarmes = partes.filter(p => p.startsWith('🚨')).length;
if (!total) {
  partes.push('', 'Nenhuma leitura prevista para hoje.');
} else if (completo) {
  partes.push('', `✅ lido: ${lidos} de ${total}.` + (lidos < total ? `\n⚠️ Ainda há ${total - lidos} leitura${total - lidos === 1 ? '' : 's'} de hoje por fazer: este relatório traz só o que já foi lido.` : ''));
  if (nAlarmes) partes.push(`🚨 ${nAlarmes} alerta${nAlarmes === 1 ? '' : 's'} acima.`);
} else {
  partes.push('', `✅ = lido (${lidos} de ${total})` + (nAlarmes ? ` · 🚨 = fora do limite ou positivo` : ''));
}

if (fin && fin.finalizado_por) partes.push(`✅ Leitura do dia finalizada por ${fin.finalizado_por} às ${fin.finalizado_as}.`);

return [{ json: { ...item, textoResposta: partes.join('\n') } }];

// Pergunta do "leitura do dia finalizada": mostra o que vai ser marcado como lido.
const r = $input.first().json;
const item = $('Interpretar comando').first().json;
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const n = (k) => Number(r[k]) || 0;

const partes = [];
if (n('nfc_terra')) partes.push(`NFC tank farm: ${n('nfc_terra')} leitura${n('nfc_terra') === 1 ? '' : 's'}`);
if (n('nfc_navio')) partes.push(`NFC navio: ${n('nfc_navio')} leitura${n('nfc_navio') === 1 ? '' : 's'}`);
if (n('drops')) partes.push(`Drops: ${n('drops')}`);
if (n('tab')) partes.push(`TAB: ${n('tab')}`);
if (n('coliformes')) partes.push(`Coliformes: ${n('coliformes')}`);

const linhas = [];
if (partes.length) {
  linhas.push(`❓ Marcar como lido tudo o que sai hoje (${hoje.slice(0, 5)})?`, partes.join(' · '));
  if (n('tab') || n('coliformes')) linhas.push('TAB e Coliformes sem crescimento ficam *Negativo*.');
  if (n('nfc_terra') || n('nfc_navio')) linhas.push('Leituras de NFC sem placa digitada ficam *<1* nas 3 placas.');
} else {
  linhas.push(`❓ Não há leitura pendente hoje (${hoje.slice(0, 5)}). Registrar a leitura do dia como finalizada?`);
}
if (n('contagens_sem_valor')) {
  linhas.push(`⚠️ C.T/B.L do concentrado: ${n('contagens_sem_valor')} resultado${n('contagens_sem_valor') === 1 ? '' : 's'} sem valor. Continuam pendentes até você digitar.`);
}
if (n('em_confirmacao')) {
  linhas.push(`ℹ️ ${n('em_confirmacao')} em confirmação não entra${n('em_confirmacao') === 1 ? '' : 'm'} (precisa do resultado).`);
}
if (r.ja_finalizado_por) linhas.push(`ℹ️ Hoje já foi finalizada por ${r.ja_finalizado_por}.`);
linhas.push('Responda *sim* ou *não*.');

const falta = n('contagens_sem_valor');
const resumo = `✅ Leitura do dia finalizada por ${item.nomeContato}. Relatório do dia: ` +
  (falta ? `todo lido, menos ${falta} resultado${falta === 1 ? '' : 's'} de C.T/B.L (digite os valores).` : 'todo lido.');

return [{ json: { ...item, salvar: true, payload: JSON.stringify({ acao: 'finalizar_dia' }), resumo,
  textoResposta: linhas.join('\n') } }];

// Pergunta antes de abrir ou fechar um desvio de drop.
const r = $input.all().map(i => i.json).find(x => x.drop_id);
const item = $('Interpretar comando').first().json;
const nomeDrop = (x) => `drop D${x.dia} do tanque ${x.tanque}${x.navio ? ' (navio ' + x.navio + ')' : ''} (coleta ${x.data_coleta})`;
const temps = (lista) => lista.map(t => `${t} °C`).join(lista.length === 2 ? ' e ' : ', ').replace(/, ([^,]*)$/, ' e $1');
const erro = (t) => [{ json: { ...item, salvar: false, payload: '{}', resumo: '', textoResposta: t } }];
const ref = `drop D${item.dia} do tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''}`;

if (item.tipo === 'desvio_abrir') {
  if (!r) return erro(`❌ Não achei o ${ref} da coleta ${item.dataColeta}. Confira o tanque e a data da coleta.`);
  if (r.desvio_id) return erro(`ℹ️ O ${nomeDrop(r)} já tem desvio (${r.desvio_status === 'Concluído' ? r.desvio_resultado.toLowerCase() : 'em confirmação, ler até ' + r.desvio_ler_ate}).`);
  return [{ json: { ...item, salvar: true,
    payload: JSON.stringify({ acao: 'abrir', drop_id: Number(r.drop_id) }),
    resumo: `⚠️ Desvio aberto: ${nomeDrop(r)}.\nRepetição do drop de arquivo em 7 °C, 13 °C e 25 °C. Leitura até ${r.ler_ate}.\n` +
      `Resultado: desvio do drop d${r.dia} tanque ${r.tanque} confirmou em 13 e 25 graus (ou: não confirmou)`,
    textoResposta: `❓ Drop *não ok*: abrir desvio do ${nomeDrop(r)}?\nRepetição do drop de arquivo em 7 °C, 13 °C e 25 °C, leitura até ${r.ler_ate}. Responda *sim* ou *não*.` } }];
}

// resultado
if (!r) return erro(`❌ Não achei desvio aberto para o ${ref}${item.dataColeta ? ' (coleta ' + item.dataColeta + ')' : ''}.`);
if (r.desvio_status !== 'Em confirmação') return erro(`ℹ️ O desvio do ${nomeDrop(r)} já foi fechado: ${String(r.desvio_resultado).toLowerCase()}.`);
const confirmou = item.temps.length > 0;
const textoRes = confirmou ? `CONFIRMOU em ${temps(item.temps)}` : 'NÃO CONFIRMOU';
return [{ json: { ...item, salvar: true,
  payload: JSON.stringify({ acao: 'fechar', desvio_id: Number(r.desvio_id), temps: item.temps }),
  resumo: `✅ Desvio do ${nomeDrop(r)} fechado: ${confirmou ? 'confirmou em ' + temps(item.temps) : 'não confirmado'}.`,
  textoResposta: `❓ Resultado do desvio do ${nomeDrop(r)}: *${textoRes}*? Responda *sim* ou *não*.` } }];

// Consultas de desvio (drop e tanque): últimos do tanque, ou os abertos.
const rows = $input.all().map(i => i.json).filter(r => r.kind);
const item = $('Interpretar comando').first().json;
const temps = (lista) => (lista || []).map(t => `${t} °C`).join(', ').replace(/, ([^,]*)$/, ' e $1');
const quem = (r) => `lido ${r.lido_dia}${r.resultado_por ? ' por ' + r.resultado_por : ''}`;
const situacaoDrop = (r) => r.status === 'Em confirmação'
  ? `em confirmação, ler até ${r.ler_ate}${r.atrasado ? ' ⚠️ atrasado' : ''}`
  : (r.resultado === 'Confirmado' ? `🚨 confirmou em ${temps(r.temperaturas)} (${quem(r)})` : `✅ não confirmado (${quem(r)})`);
const situacaoTanque = (r) => r.status === 'Em repetição'
  ? `em repetição${r.ler_ate ? ', leitura até ' + r.ler_ate : ''}${r.atrasado ? ' ⚠️ atrasado' : ''}`
  : (r.resultado === 'Não ok' ? `🚨 repetição não ok (${quem(r)})` : `✅ repetição ok (${quem(r)})`);
const deu = (r) => (r.contagem ? ` (deu ${r.contagem})` : '');
const alvo = item.modo === 'tanque' ? `tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''}${item.data ? ' · coleta ' + item.data : ''}` : '';
const navioDe = (r) => (r.navio ? ' (navio ' + r.navio + ')' : '');

let texto;
if (!rows.length) {
  texto = item.modo === 'tanque' ? `Nenhum desvio registrado para o ${alvo}.` : 'Nenhum desvio aberto.';
} else if (item.modo === 'tanque') {
  texto = `🧪 Últimos desvios — ${alvo}:\n` + rows.map(r => r.kind === 'drop'
    ? `Drop D${r.dia} · coleta ${r.data_coleta} · aberto ${r.aberto_dia}${r.aberto_por ? ' por ' + r.aberto_por : ''} · ${situacaoDrop(r)}`
    : `${r.analise} ${r.frasco}${deu(r)} · coleta ${r.data_coleta} · aberto ${r.aberto_dia}${r.aberto_por ? ' por ' + r.aberto_por : ''} · ${situacaoTanque(r)}`).join('\n');
} else {
  texto = '🧪 Desvios abertos:\n' + rows.map(r => r.kind === 'drop'
    ? `Tanque ${r.tanque}${navioDe(r)} drop D${r.dia} · coleta ${r.data_coleta} · ler até ${r.ler_ate}${r.atrasado ? ' ⚠️ atrasado' : ''}`
    : `Tanque ${r.tanque}${navioDe(r)} ${r.analise} ${r.frasco}${deu(r)} · coleta ${r.data_coleta} · ${situacaoTanque(r)}`).join('\n');
}

return [{ json: { ...item, textoResposta: texto } }];

// Pergunta antes de gravar as placas de uma leitura de NFC (mostra ok / não ok).
const r = $input.all().map(i => i.json).find(x => x.analise_id);
const item = $('Interpretar comando').first().json;
const erro = (t) => [{ json: { ...item, salvar: false, tipoPendencia: 'PLACAS', payload: '{}', resumo: '', textoResposta: t } }];
const onde = `do tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''}`;
if (!r) {
  return erro(`❌ Não achei leitura de ${item.rotulo} ${onde} (${item.frasco}) ${item.dataColeta ? 'da coleta ' + item.dataColeta : 'em aberto (vencendo hoje, atrasada ou ainda por vir)'}.` +
    `\nConfira se a análise desse tanque e frasco foi registrada (ex.: *Analise do ${item.frasco.toLowerCase()} do tanque ${item.tanque}, data dd/mm/aaaa*)` +
    (item.dataColeta ? ' e a data da coleta.' : ' ou, se for de outra coleta, acrescente *coleta dd/mm/aaaa* no fim.'));
}
if (Number(r.coletas_abertas) > 1 && !item.dataColeta) {
  return erro(`⚠️ O tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''} tem ${r.coletas_abertas} coletas com ${item.rotulo} (${item.frasco}) para ler: ${r.opcoes}.` +
    `\nDe qual é? Mande de novo acrescentando *coleta dd/mm/aaaa* no fim. Nada foi gravado.`);
}
const txt = (p) => (p.sinal === '=' ? String(p.valor) : p.sinal + p.valor);
const contagem = item.placas.map(txt).join(', ');
const limite = r.limite === null || r.limite === undefined ? null : Number(r.limite);
const acima = item.placas.some(p => p.sinal === '>' || (limite !== null && p.sinal === '=' && p.valor > limite));
const situacao = acima ? 'não ok' : (limite === null ? 'sem limite cadastrado' : 'ok');
const marca = acima ? '🚨' : (limite === null ? 'ℹ️' : '✅');
const nome = `${item.rotulo} ${onde} (${item.frasco}), coleta ${r.data_coleta}${r.repeticao ? ', repetição' : ''}`;
const abreDesvio = acima && !r.tem_desvio && !r.repeticao;
const rotuloDesvio = `tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''} (${item.rotulo}, ${item.frasco})`;
const payload = {
  acao: 'placas', analise_id: Number(r.analise_id), etapa: item.etapa, placas: item.placas,
  nao_ok: abreDesvio,
  pergunta_desvio: `❓ Abrir desvio do ${rotuloDesvio}? A análise é repetida com o frasco de arquivo, em triplicata e com os mesmos prazos. Responda *sim* ou *não*.`,
  resumo_desvio: `⚠️ Desvio criado do ${rotuloDesvio}. Repetição com o frasco de arquivo, em triplicata e com os mesmos prazos.`
};
const linhas = [`❓ ${nome}: ${contagem} → ${marca} *${situacao}*.`];
if (r.prevista && r.antecipada) linhas.push(`⏩ Leitura antecipada: prevista para ${r.prevista}.`);
else if (r.prevista && !r.hoje) linhas.push(`ℹ️ Leitura prevista para ${r.prevista}.`);
if (Number(r.ja_lidas)) linhas.push('ℹ️ Essa leitura já tinha placas: os valores novos substituem os antigos.');
if (r.repeticao && acima) linhas.push('A repetição deu não ok: o desvio fecha como *não ok*.');
if (abreDesvio) linhas.push('Depois de gravar, pergunto se abre o desvio.');
linhas.push('Responda *sim* para gravar ou *não* para cancelar.');
return [{ json: { ...item, salvar: true, tipoPendencia: 'PLACAS', payload: JSON.stringify(payload),
  resumo: `✅ Gravado: ${nome}: ${contagem} → ${marca} ${situacao}.`, textoResposta: linhas.join('\n') } }];

// Repetição (reanálise) feita: só para tanque com desvio aberto (leitura acima do limite).
const rows = $input.all().map(i => i.json).filter(x => x.desvio_id);
const item = $('Interpretar comando').first().json;
const erro = (t) => [{ json: { ...item, salvar: false, tipoPendencia: 'DESVIO_TANQUE', payload: '{}', resumo: '', textoResposta: t } }];
const ROT = (x) => x.sub_analise === 'CT' ? 'C.T 48h'
  : x.sub_analise === 'BL' ? (x.etapa === 'pre' ? 'B.L 72h' : 'B.L 120h')
  : `WORT ${x.metodo === 'Superficie' ? 'Superfície' : 'Profundidade'} ${x.etapa === 'pre' ? '120h' : '240h'}`;
const CMD = (x) => x.sub_analise === 'CT' ? 'ct' : x.sub_analise === 'BL' ? (x.etapa === 'pre' ? 'bl72' : 'bl120')
  : `wort ${x.metodo === 'Superficie' ? 'superficie' : 'profundidade'} ${x.etapa === 'pre' ? '120h' : '240h'}`;
const tanque = `tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''}`;
const filtro = [item.rotulo, item.frasco].filter(Boolean).join(' ');
if (!rows.length) {
  return erro(`❌ O ${tanque} não tem desvio aberto${filtro ? ' no ' + filtro : ''}. A repetição só vale para leitura acima do limite.`);
}
if (rows.length > 1) {
  return erro(`❓ O ${tanque} tem ${rows.length} desvios abertos: ${rows.map(x => `${ROT(x)} ${x.frasco}`).join('; ')}. ` +
    `Diga qual. Ex.: repetição do tanque ${item.tanque} ${rows[0].frasco.toLowerCase()} ${CMD(rows[0])}`);
}
const x = rows[0];
const nome = `${ROT(x)} do ${tanque} (${x.frasco}), coleta ${x.data_coleta}`;
const leituras = [x.rep_pre && `pré-leitura ${x.rep_pre}`, x.rep_final && `leitura final ${x.rep_final}`].filter(Boolean).join(', ');
if (x.repeticao_feita) return erro(`ℹ️ A repetição do ${nome} já foi registrada. Leituras: ${leituras}.`);
return [{ json: { ...item, salvar: true, tipoPendencia: 'DESVIO_TANQUE',
  payload: JSON.stringify({ acao: 'repeticao', desvio_id: Number(x.desvio_id) }),
  resumo: `✅ Repetição feita: ${nome}, com o frasco de arquivo. Leituras: ${leituras}.`,
  textoResposta: `❓ Registrar a repetição feita do ${nome} (deu ${x.contagem || 'não ok'}), com o frasco de arquivo? Leituras: ${leituras}. Responda *sim* ou *não*.` } }];

// Bug 29: a resposta do "sim" só sai depois das gravações (os nodes BD acima rodam em fila).
const base = $('Processar sim ou não').first().json;
// C.T/B.L pela lancar_contagem (040): se o banco recusou, nada foi gravado e a resposta diz por quê
const lerNo = (n, k) => { try { return $(n).first().json[k] || ''; } catch (e) { return ''; } };
// leituras e placas pela 042: idem
const erroLeit = (() => { try { const r = $('BD · Concluir leituras').first().json.r; return r && r.ok === false ? r.erro : ''; } catch (e) { return ''; } })();
const erroCont = lerNo('BD · Atualizar TABs', 'contagem_erro') || lerNo('BD · Gravar contagens da foto', 'contagem_foto_erro')
  || lerNo('BD · Gravar contagens NFC', 'contagem_nfc_erro') || lerNo('BD · Executar desvio', 'desvio_erro') || lerNo('BD · Atualizar TABs', 'teste_erro') || lerNo('BD · Executar NFC', 'placas_erro') || lerNo('BD · Executar placas da foto', 'placas_lote_erro') || erroLeit;
if (erroCont) return [{ json: { ...base, textoResposta: '❌ ' + erroCont + ' Nada foi gravado.' } }];
const nfc = $input.first().json || {};
const extra = nfc.perguntaDesvio ? '\n\n' + nfc.perguntaDesvio : '';
return [{ json: { ...base, textoResposta: (base.textoResposta || '') + extra } }];

// base64 da Evolution -> arquivo (binário "data") para o Gemini
const r = $input.first().json;
if (!r.base64) throw new Error('A Evolution não devolveu o áudio');
const tipo = String(r.mimetype || 'audio/ogg').split(';')[0];
// o base64 tambem segue no json, porque o Gemini recebe o audio dentro do pedido
return [{ json: { audio_b64: r.base64, mime: tipo }, binary: { data: { data: r.base64, mimeType: tipo, fileName: 'audio.ogg' } } }];

// Texto do áudio: "🎤 Ouvi" para a pessoa conferir; vazio pede para repetir.
// Áudio de até 2 s (clique sem querer) só vale "sim" ou "não": nenhum comando cabe nisso, e no silêncio
// a transcrição pode inventar palavras do vocabulário.
const r = $input.first().json;
// limite diario de IA atingido, ou nenhum provedor respondeu: avisa em vez de dizer que nao entendeu
if (r.limite) {
  return [{ json: { transcricao: '', textoResposta: '⚠️ Limite diário de IA atingido. Mande por escrito no formato do comando (mande "comandos" para ver); amanhã o limite volta.' } }];
}
if (r.error) {
  return [{ json: { transcricao: '', textoResposta: '⚠️ A IA de áudio está indisponível agora. Mande por escrito ou tente de novo em instantes.' } }];
}
const segundos = Number($('Interpretar comando').first().json.segundos) || 0;
let t = String(r?.content?.parts?.[0]?.text ?? '').replace(/\s+/g, ' ').trim().replace(/^["“]+|["”]+$/g, '');
// resposta curta falada: "Sim, sim.", "sim, pode gravar", "não, cancela" (sem números) vira "sim" ou "não"
const palavras = t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]+/g, ' ').trim().split(/\s+/);
if (palavras.length <= 4 && !/\d/.test(t) && palavras[0] === 'sim') t = 'sim';
else if (palavras.length <= 4 && !/\d/.test(t) && palavras[0] === 'nao') t = 'não';
const simNao = /^(sim|n[aã]o)[.!]?$/i.test(t);
const vazio = !t || /^vazio\.?$/i.test(t) || (segundos <= 2 && !simNao);
return [{ json: { transcricao: vazio ? '' : t.slice(0, 500),
  textoResposta: vazio ? '🎤 Não entendi o áudio. Pode repetir ou mandar por escrito?' : `🎤 Ouvi: "${t.slice(0, 500)}"` } }];

