// Padroniza a resposta de qualquer provedor de IA (Gemini, Groq) para o formato que o resto do fluxo ja le:
//   { content: { parts: [{ text }] }, provedor }   ou   { error, provedor }
const r = $input.first().json || {};
let texto = '';
let provedor = '';
if (Array.isArray(r.candidates)) {                 // Gemini (REST)
  texto = (r.candidates[0]?.content?.parts || []).map((p) => p.text || '').join('');
  provedor = 'gemini';
} else if (Array.isArray(r.choices)) {              // Groq (chat)
  texto = r.choices[0]?.message?.content || '';
  provedor = 'groq';
} else if (typeof r.text === 'string') {            // Groq Whisper (transcricao)
  texto = r.text;
  provedor = 'groq';
} else if (Array.isArray(r.content?.parts)) {       // ja no formato padrao
  texto = r.content.parts.map((p) => p.text || '').join('');
  provedor = r.provedor || 'gemini';
}
texto = String(texto).trim();
if (!texto) {
  const motivo = (r.error && (r.error.message || r.error)) || r.message || (r.promptFeedback ? 'resposta bloqueada' : 'sem resposta');
  return [{ json: { error: String(motivo).slice(0, 200), provedor: provedor || 'nenhum' } }];
}
return [{ json: { content: { parts: [{ text: texto }] }, provedor } }];

// Pedido de IA acima do limite diario: nao chama nenhum provedor.
const l = $input.first().json || {};
return [{ json: { limite: true, tipo: 'texto', usuario_hoje: l.usuario_hoje, limite_usuario: l.limite_usuario, total_hoje: l.total_hoje, limite_total: l.limite_total } }];

// O Groq recebe o arquivo de audio como anexo: religa o binario do node "Áudio em arquivo".
const a = $('Áudio em arquivo').first();
return [{ json: {}, binary: a.binary }];

// Padroniza a resposta de qualquer provedor de IA (Gemini, Groq) para o formato que o resto do fluxo ja le:
//   { content: { parts: [{ text }] }, provedor }   ou   { error, provedor }
const r = $input.first().json || {};
let texto = '';
let provedor = '';
if (Array.isArray(r.candidates)) {                 // Gemini (REST)
  texto = (r.candidates[0]?.content?.parts || []).map((p) => p.text || '').join('');
  provedor = 'gemini';
} else if (Array.isArray(r.choices)) {              // Groq (chat)
  texto = r.choices[0]?.message?.content || '';
  provedor = 'groq';
} else if (typeof r.text === 'string') {            // Groq Whisper (transcricao)
  texto = r.text;
  provedor = 'groq';
} else if (Array.isArray(r.content?.parts)) {       // ja no formato padrao
  texto = r.content.parts.map((p) => p.text || '').join('');
  provedor = r.provedor || 'gemini';
}
texto = String(texto).trim();
if (!texto) {
  const motivo = (r.error && (r.error.message || r.error)) || r.message || (r.promptFeedback ? 'resposta bloqueada' : 'sem resposta');
  return [{ json: { error: String(motivo).slice(0, 200), provedor: provedor || 'nenhum' } }];
}
return [{ json: { content: { parts: [{ text: texto }] }, provedor } }];

// Pedido de IA acima do limite diario: nao chama nenhum provedor.
const l = $input.first().json || {};
return [{ json: { limite: true, tipo: 'audio', usuario_hoje: l.usuario_hoje, limite_usuario: l.limite_usuario, total_hoje: l.total_hoje, limite_total: l.limite_total } }];

// A fala tratada já é um comando completo: devolve no formato da IA, sem chamar nenhum provedor.
const r = $input.first().json;
return [{ json: { content: { parts: [{ text: r.ia_pronta }] }, provedor: 'regra' } }];

// Consulta de quem coletou: um tanque (com ou sem data/navio) ou todos os tanques de um navio.
// "Coletou" é quem registrou a coleta no bot.
const rows = $input.all().map(i => i.json).filter(r => r.tanque);
const item = $('Interpretar comando').first().json;
const ordem = (a, b) => String(a).localeCompare(String(b), 'pt-BR', { numeric: true });
const onde = (r) => r.origem === 'navio' ? `navio ${r.navio}` : 'terra';
const quemDe = (r) => r.quem || 'sem nome cadastrado';
const filtro = (item.data ? ` no dia ${item.data}` : '') + (item.navio && item.modo === 'tanque' ? ` (navio ${item.navio})` : '');

let texto;
if (!rows.length) {
  texto = item.modo === 'navio'
    ? `Nenhuma coleta encontrada para o navio ${item.navio}${item.data ? ' no dia ' + item.data : ''}.`
    : `Nenhuma coleta encontrada para o tanque ${item.tanque}${filtro}.`;
} else if (item.modo === 'navio') {
  const datas = new Set(rows.map(r => r.data_coleta));
  const grupos = new Map();
  for (const r of rows) {
    const chave = datas.size > 1 ? `${quemDe(r)} (${r.data_coleta.slice(0, 5)})` : quemDe(r);
    if (!grupos.has(chave)) grupos.set(chave, []);
    grupos.get(chave).push(r.tanque);
  }
  const linhas = [`🚢 Quem coletou os tanques do navio ${item.navio}:`];
  for (const [quem, tanques] of grupos) linhas.push(`👤 ${quem}: ${[...tanques].sort(ordem).join(', ')}`);
  linhas.push('', `Total: ${rows.length} tanque${rows.length > 1 ? 's' : ''}.`);
  texto = linhas.join('\n');
} else {
  const linhas = [`🧪 Quem coletou o tanque ${item.tanque}${filtro}:`];
  for (const r of rows) {
    linhas.push(`• ${r.data_coleta} · ${onde(r)} · ${quemDe(r)} (registrado em ${r.registrado_em})`);
  }
  texto = linhas.join('\n');
}
return [{ json: { ...item, textoResposta: texto } }];

// Resultados de C.T e B.L de um load até agora: o que já foi lido e o que ainda falta.
function compactar(lista, pref = '') {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${pref}${ns[i]}` : `${pref}${ns[i]}-${pref}${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}
const ROTULO = { CT: 'C.T 48h', BL72: 'B.L 72h', BL120: 'B.L 120h' };
const LIMITE = { CT: 200, BL72: 50, BL120: 50 };
const ORDEM = ['CT', 'BL72', 'BL120'];
const rows = $input.all().map(i => i.json).filter(r => r.analise);
const item = $('Interpretar comando').first().json;
const filtrou = item.analises ? item.analises.split(',').map(a => ROTULO[a]).join(' e ') : 'C.T e B.L';

let texto;
if (!rows.length) {
  texto = `Não encontrei o load ${item.load}. Confira o número (o load precisa ter recebimento ou embarque registrado).`;
} else {
  // um bloco por origem e por item/fábrica (o mesmo número de load pode ter mais de um)
  const blocos = new Map();
  for (const r of rows) {
    const chave = r.origem === 'embarque'
      ? `${r.navio} linha ${r.linha} fase ${r.fase} · load ${r.load} item ${r.item}`
      : (r.origem === 'nfc' ? `NFC load ${r.load} · item ${r.item} · fábrica ${r.fabrica} · ${r.amostra}` : `load ${r.load} · item ${r.item} · fábrica ${r.fabrica}`);
    if (!blocos.has(chave)) blocos.set(chave, { origem: r.origem, rows: [] });
    blocos.get(chave).rows.push(r);
  }
  const linhas = [`🔬 ${filtrou} do load ${item.load} até agora:`];
  for (const [chave, b] of blocos) {
    const pref = b.origem === 'embarque' ? 'A' : '';
    const palavra = b.origem === 'embarque' ? 'amostra' : 'lote';
    linhas.push('', `📦 ${chave}`);
    for (const an of ORDEM) {
      const doTipo = b.rows.filter(r => r.analise === an);
      if (!doTipo.length) continue;
      const lidos = doTipo.filter(r => r.resultado !== null && r.resultado !== undefined)
        .sort((x, y) => x.numero - y.numero);
      const faltam = doTipo.filter(r => r.resultado === null || r.resultado === undefined);
      if (lidos.length) {
        const partes = lidos.map(r => {
          const v = String(r.resultado).replace('.', ',');
          return `${pref}${r.numero} = ${v}${r.alarme ? ' 🚨' : ''}`;
        });
        linhas.push(`${ROTULO[an]}: ${partes.join(' · ')}`);
      } else {
        linhas.push(`${ROTULO[an]}: nenhum ${palavra} lido ainda`);
      }
      if (faltam.length && lidos.length) {
        const prazos = [...new Set(faltam.map(r => r.prevista))];
        linhas.push(`   ⏳ faltam ${palavra}${faltam.length > 1 ? 's' : ''} ${compactar(faltam.map(r => r.numero), pref)} (previsto ${prazos.join(', ')})`);
      } else if (faltam.length) {
        const prazos = [...new Set(faltam.map(r => r.prevista))];
        linhas.push(`   ⏳ previsto ${prazos.join(', ')}`);
      }
    }
  }
  if (rows.some((r) => r.origem !== 'nfc')) linhas.push('', `🚨 = acima do limite (B.L ≥ ${LIMITE.BL120}, C.T ≥ ${LIMITE.CT}).`);
  texto = linhas.join('\n');
}
return [{ json: { ...item, textoResposta: texto } }];

// Resultado das placas (C.T, B.L e WORT) de um tanque, por coleta. Só as leituras já lançadas mostram contagem.
const rows = $input.all().map(i => i.json).filter(r => r.sub_analise);
const item = $('Interpretar comando').first().json;
const NOME = (r) => r.sub_analise === 'CT' ? 'C.T 48h'
  : r.sub_analise === 'BL' ? (r.etapa === 'pre' ? 'B.L 72h' : 'B.L 120h')
  : `WORT ${r.metodo === 'Superficie' ? 'superfície' : 'profundidade'} ${r.etapa === 'pre' ? '120h' : '240h'}`;
const SITUACAO = (r) => {
  if (r.situacao === 'Ok') return '✅ ok';
  if (r.situacao === 'Não ok') return '🚨 não ok';
  if (r.situacao === 'Sem limite') return 'sem limite cadastrado';
  return `aguardando leitura (prevista ${r.prevista})`;
};
// leitura prevista (pré) que ninguém lançou: se a leitura final da mesma análise já saiu ok, a pré conta como ok
const finalDe = new Map(rows.filter((x) => x.etapa === 'final').map((x) => [String(x.analise_id), x]));
const coberta = (r) => r.etapa === 'pre' && !r.contagem && r.situacao === 'Pendente' && (finalDe.get(String(r.analise_id)) || {}).situacao === 'Ok';
const filtro = (item.data ? ` do dia ${item.data}` : '') + (item.navio ? ` (navio ${item.navio})` : '');

let texto;
if (!rows.length) {
  texto = `Nenhuma coleta/análise encontrada para o tanque ${item.tanque}${filtro}.`;
} else {
  const grupos = new Map();
  for (const r of rows) {
    const chave = `${r.data_coleta}|${r.origem}|${r.navio || ''}`;
    if (!grupos.has(chave)) grupos.set(chave, { r, linhas: [] });
    grupos.get(chave).linhas.push(r);
  }
  const todos = [...grupos.values()];
  const mostrar = item.data ? todos : todos.slice(0, 2);
  const out = [`🧪 Resultados do tanque ${item.tanque}${filtro}:`];
  for (const g of mostrar) {
    out.push('', `Coleta ${g.r.data_coleta} · ${g.r.origem === 'navio' ? 'navio ' + g.r.navio : 'terra'}`);
    for (const r of g.linhas) {
      const cont = r.contagem ? r.contagem : '—';
      if (coberta(r)) {
        out.push(`• ${NOME(r)} ${String(r.frasco).toLowerCase()}${r.repeticao ? ' (repetição)' : ''}: — · ✅ ok (a leitura final de ${NOME(finalDe.get(String(r.analise_id))).split(' ').pop()} está ok)`);
        continue;
      }
      out.push(`• ${NOME(r)} ${String(r.frasco).toLowerCase()}${r.repeticao ? ' (repetição)' : ''}: ${cont} · ${SITUACAO(r)}`);
    }
  }
  if (!item.data && todos.length > 2) out.push('', `Há ${todos.length - 2} coleta(s) mais antiga(s) deste tanque; peça com a data (ex.: resultado do tanque ${item.tanque} do dia dd/mm/aaaa).`);
  texto = out.join('\n');
}
return [{ json: { ...item, textoResposta: texto } }];

// base64 da Evolution -> foto para o Gemini (visão)
const r = $input.first().json;
if (!r.base64) throw new Error('A Evolution não devolveu a foto');
const mime = String(r.mimetype || 'image/jpeg').split(';')[0];
return [{ json: { foto_b64: r.base64, mime } }];

// Pedido de IA acima do limite diario: nao chama nenhum provedor.
const l = $input.first().json || {};
return [{ json: { limite: true, tipo: 'foto', usuario_hoje: l.usuario_hoje, limite_usuario: l.limite_usuario, total_hoje: l.total_hoje, limite_total: l.limite_total } }];

// Padroniza a resposta de qualquer provedor de IA (Gemini, Groq) para o formato que o resto do fluxo ja le:
//   { content: { parts: [{ text }] }, provedor }   ou   { error, provedor }
const r = $input.first().json || {};
let texto = '';
let provedor = '';
if (Array.isArray(r.candidates)) {                 // Gemini (REST)
  texto = (r.candidates[0]?.content?.parts || []).map((p) => p.text || '').join('');
  provedor = 'gemini';
} else if (Array.isArray(r.choices)) {              // Groq (chat)
  texto = r.choices[0]?.message?.content || '';
  provedor = 'groq';
} else if (typeof r.text === 'string') {            // Groq Whisper (transcricao)
  texto = r.text;
  provedor = 'groq';
} else if (Array.isArray(r.content?.parts)) {       // ja no formato padrao
  texto = r.content.parts.map((p) => p.text || '').join('');
  provedor = r.provedor || 'gemini';
}
texto = String(texto).trim();
if (!texto) {
  const motivo = (r.error && (r.error.message || r.error)) || r.message || (r.promptFeedback ? 'resposta bloqueada' : 'sem resposta');
  return [{ json: { error: String(motivo).slice(0, 200), provedor: provedor || 'nenhum' } }];
}
return [{ json: { content: { parts: [{ text: texto }] }, provedor } }];

// Foto de laudo: valida o que a IA leu e monta a LISTA de comandos oficiais (nada grava aqui).
const ctx = $('Interpretar comando').first().json;
const raw = $input.first().json || {};
const base = { numero: ctx.numero, nomeContato: ctx.nomeContato, nivel: ctx.nivelAtual, comandos: [], buscas: [], duvidas: [], problemas: [], formulario: 'desconhecido', data: '' };
const falha = (texto) => [{ json: { ...base, textoResposta: texto, falha: true } }];

if (raw.limite) return falha('⚠️ Limite diário de IA atingido. Mande por escrito ou por áudio no formato do comando (escreva "comandos"); amanhã o limite volta.');
if (raw.error) return falha('⚠️ A IA de leitura de foto está indisponível agora. Tente de novo em instantes ou mande o comando por escrito ou por áudio.');

let ia;
try {
  ia = JSON.parse(String(raw?.content?.parts?.[0]?.text ?? '').replace(/```json|```/g, '').trim());
} catch (e) { ia = null; }
if (!ia || typeof ia !== 'object') return falha('📷 Não consegui ler essa foto. Tire outra com o papel inteiro, reto e bem iluminado, ou mande o comando por escrito.');

const FORMULARIOS = { recebimento: 'recebimento', tab: 'TAB', coliformes: 'Coliformes', nfc: 'NFC (placas dos tanques)', embarque: 'embarque (FCOJ)', recebimento_nfc: 'recebimento NFC' };
let formulario = String(ia.formulario || '').toLowerCase();
// O laudo de recebimento do NFC tem o MESMO título do recebimento do concentrado: o que decide é o item (129 = NFC).
const problemasMistura = [];
if ((formulario === 'recebimento' || formulario === 'recebimento_nfc') && Array.isArray(ia.blocos)) {
  const ehNfc = (b) => String((b && b.item) || '').replace(/\D/g, '') === '129';
  const blocosNfc = ia.blocos.filter(ehNfc);
  if (blocosNfc.length) {
    ia.blocos.filter((b) => !ehNfc(b)).forEach((b) => problemasMistura.push('load ' + String((b && b.load) || '?').replace(/\D/g, '') + ' (item ' + (String((b && b.item) || '').replace(/\D/g, '') || '?') + '): o laudo mistura NFC (item 129) com concentrado; mande o concentrado em outra foto'));
    ia.blocos = blocosNfc;
    formulario = 'recebimento_nfc';
  }
}
if (!FORMULARIOS[formulario]) return falha('📷 Não reconheci o formulário. Por enquanto leio recebimento (com compostas), TAB e Coliformes de caldo e as placas do laudo de NFC. Mande o comando por escrito ou por áudio.');

// ---- apoio ----
const hoje = String(ctx.hoje || '');
const [hd, hm, ha] = hoje.split('/').map(Number);
const anoHoje = ha || new Date().getFullYear();
const SIGLAS = ['AQA', 'CON', 'COL', 'UCH', 'ITA', 'TMG'];
const NOMES = { ARARAQUARA: 'AQA', CONCHAL: 'CON', COLINA: 'COL', UCHOA: 'UCH', ITAPOLIS: 'ITA', TERMINALGUARUJA: 'TMG', GUARUJA: 'TMG' };
const TORTAS = { AOQ: 'AQA', AOQA: 'AQA', AOA: 'AQA', AKA: 'AQA', A0A: 'AQA', AQ0: 'AQA', AQ4: 'AQA', AO4: 'AQA', A04: 'AQA', C0N: 'CON', COI: 'COL' };
function fabrica(x) {
  const s = String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (SIGLAS.includes(s)) return { sigla: s };
  if (NOMES[s]) return { sigla: NOMES[s] };
  if (TORTAS[s]) return { sigla: TORTAS[s], lido: String(x).trim() };
  return null;
}
const dd = (n) => String(n).padStart(2, '0');
// "17/08" -> dd/mm/aaaa (ano de hoje; se cair no futuro, o ano anterior); "17/08/2026" fica; invalida -> ''
function dataCompleta(s, passado) {
  const m = String(s || '').trim().match(/^(\d{1,2})[\/.\-](\d{1,2})(?:[\/.\-](\d{2,4}))?$/);
  if (!m) return '';
  const dia = Number(m[1]), mes = Number(m[2]);
  let ano = m[3] ? Number(m[3]) : anoHoje;
  if (ano < 100) ano += 2000;
  const d = new Date(ano, mes - 1, dia);
  if (d.getFullYear() !== ano || d.getMonth() !== mes - 1 || d.getDate() !== dia) return '';
  if (!m[3] && passado && (mes > hm || (mes === hm && dia > hd))) ano -= 1;
  return `${dd(dia)}/${dd(mes)}/${ano}`;
}
function compactar(lista) {
  const ns = [...new Set(lista.map(Number))].sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${ns[i]}` : `${ns[i]}-${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}
// "1-5,7" -> [1,2,3,4,5,7]; texto estranho -> null
function lotesDe(texto) {
  const out = [];
  for (const parte of String(texto || '').replace(/\s+/g, '').split(/[,;e]/).filter(Boolean)) {
    const m = parte.match(/^(\d{1,3})(?:[-–a](\d{1,3}))?$/);
    if (!m) return null;
    const a = Number(m[1]), b = m[2] ? Number(m[2]) : a;
    if (a < 1 || b < a || b - a > 300) return null;
    for (let n = a; n <= b; n++) out.push(n);
  }
  return out.length ? out : null;
}

// ---- Recebimento NFC: load, fábrica, lotes com tipo (fresh/past), diluição e resultados de C.T/B.L ----
if (formulario === 'recebimento_nfc') {
  const comN = [];
  const probN = [...problemasMistura];
  const dubN = (Array.isArray(ia.duvidas) ? ia.duvidas : []).map((d) => String(d).trim()).filter(Boolean).slice(0, 8);
  const dataG = ia.data ? dataCompleta(ia.data, false) : '';
  const reqs = [];        // lotes a procurar no banco (existência) e resultados (valor atual)
  const resultadosN = []; // resultados válidos lidos do papel (como saíram na placa)
  const COLN = { ct: 'CT', bl72: 'BL72', bl120: 'BL120' };
  const tipoDe = (x) => {
    const s = String(x || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    if (/^past/.test(s)) return 'past';
    if (/^fresh|^fresc|natura/.test(s)) return 'fresh';
    return '';
  };
  const valorN = (v) => {
    if (v === null || v === undefined) return null;
    const s = String(v).trim().replace(/\s+/g, '').replace(',', '.');
    if (!s || /^[-–—_.xX*]+$/.test(s)) return null;
    const m = s.match(/^([<>]?)(\d+(?:\.\d+)?)$/);
    if (!m) return { erro: String(v) };
    return { sinal: m[1] || '=', valor: Number(m[2]) };
  };
  (Array.isArray(ia.blocos) ? ia.blocos : []).slice(0, 10).forEach((b, i) => {
    const load = String(b.load || '').replace(/\D/g, '');
    if (!/^\d{4,6}$/.test(load)) { probN.push('linha ' + (i + 1) + ' do papel: não li o número do load'); return; }
    const fab = fabrica(b.fabrica);
    if (!fab) { probN.push('load ' + load + ': fábrica "' + (b.fabrica || '?') + '" não é uma das seis (AQA, CON, COL, UCH, ITA, TMG)'); return; }
    if (fab.lido) dubN.push('load ' + load + ': li a fábrica como "' + fab.lido + '" e entendi ' + fab.sigla);
    const itemN = String(b.item || '129').replace(/\D/g, '') || '129';
    if (itemN !== '129') { probN.push('load ' + load + ': o item do recebimento NFC é 129 e o papel diz ' + itemN); return; }
    const vistos = new Map();
    const ruins = [];
    const regras = [];
    (Array.isArray(b.lotes) ? b.lotes : []).forEach((l) => {
      const lote = Number(String(l && l.lote).replace(/\D/g, ''));
      const tipo = tipoDe(l && l.tipo);
      const dilTxt = String(l && l.diluicao).replace(/[¹²³⁴]/g, (ch) => ({ '¹': '1', '²': '2', '³': '3', '⁴': '4' })[ch]);
      const expo = dilTxt.match(/(?:\^|elevado\s+a|a\s+)\s*(-?\d)\s*$/i);   // "10^1", "10 elevado a 1"
      // o 10 escrito colado no expoente ("101", "103", "104", ou "10³" lido sem o expoente pequeno) é 10^1, 10^3, 10^4
      const colado = dilTxt.match(/^\s*10\s*(\d)\s*$/);
      const dil = expo ? Math.abs(Number(expo[1])) : colado ? Number(colado[1]) : Math.abs(parseInt(dilTxt.replace(/[^\d-]/g, ''), 10));
      if (!Number.isInteger(lote) || lote < 1 || !tipo || !Number.isInteger(dil) || dil > 9) { ruins.push('lote ' + ((l && l.lote) || '?')); return; }
      if (tipo === 'past' && fab.sigla !== 'AQA') { regras.push('lote ' + lote + ' past: só a AQA tem pasteurizado'); return; }
      if (tipo === 'past' ? dil !== 1 : (dil < 2 || dil > 4)) { regras.push('lote ' + lote + ' ' + tipo + ': diluição 10^' + dil + ' fora do padrão (past = 1; fresh = 2 a 4)'); return; }
      const k = lote + '|' + tipo;
      if (vistos.has(k) && vistos.get(k).dil !== dil) { ruins.push('lote ' + lote + ' ' + tipo + ' (diluições diferentes)'); return; }
      vistos.set(k, { lote, tipo, dil });
      reqs.push({ idx: reqs.length, load, lote, amostra: tipo, analise: null });
      for (const [col, an] of Object.entries(COLN)) {
        const v = valorN(l && l[col]);
        if (!v) continue;
        if (v.erro) { dubN.push('load ' + load + ' lote ' + lote + ' ' + tipo + ' ' + an + ': não entendi "' + v.erro + '"; fica de fora'); continue; }
        const req = { idx: reqs.length, load, lote, amostra: tipo, analise: an };
        reqs.push(req);
        resultadosN.push({ idx: req.idx, load, lote, amostra: tipo, dilPapel: dil, analise: an, sinal: v.sinal, lido: v.valor });
      }
    });
    if (regras.length) probN.push('load ' + load + ': ' + regras.join('; '));
    if (ruins.length) probN.push('load ' + load + ': não li o tipo ou a diluição de ' + ruins.join(', '));
    if (!vistos.size) return;
    const data = b.data ? dataCompleta(b.data, false) : dataG;
    if (!data) dubN.push('load ' + load + ': sem a data do recebimento, vale a de hoje');
    // um lote por comando (uma linha do papel = um comando)
    [...vistos.values()].sort((x, y) => x.lote - y.lote || x.tipo.localeCompare(y.tipo)).forEach((v) => {
      comN.push({ tipo: 'recebimento_nfc', load, fabrica: fab.sigla, lote: v.lote, amostra: v.tipo, dil: v.dil, data,
        texto: 'Recebimento NFC load ' + load + ' fab ' + fab.sigla + ' item 129 lote ' + v.lote + ' ' + v.tipo + ' 10 elevado a ' + v.dil + (data ? ' data ' + data : ''),
        resumo: 'lote ' + v.lote + ' ' + v.tipo + ' 10^' + v.dil });
    });
  });
  if (!comN.length) {
    const motivo = probN.length ? '\n• ' + probN.join('\n• ') : '';
    return [{ json: { ...base, formulario, textoResposta: '📷 Li o laudo de recebimento NFC, mas não consegui montar nenhum comando.' + motivo + '\n\nTire outra foto ou mande o comando por escrito (escreva *comandos recebimento nfc*). Nada foi gravado.', falha: true } }];
  }
  return [{ json: { ...base, formulario, data: dataG, comandos: comN, buscas: [], buscasNfc: reqs, resultadosNfc: resultadosN, duvidas: dubN, problemas: probN } }];
}

// ---- Embarque (FCOJ): uma linha por load (linha/fase, load, item, amostras) ----
if (formulario === 'embarque') {
  const viagem = String(ia.viagem || '').replace(/\D/g, '');
  let navioE = String(ia.navio || '').toUpperCase().replace(/^ORANGE\s+/, 'O.').replace(/\s*\.\s*/g, '.').replace(/\s+/g, ' ').trim();
  if (viagem && !/\d$/.test(navioE)) navioE = (navioE + ' ' + viagem).trim();
  const comE = [];
  const probE = [];
  const reqs = [];        // amostras a procurar no banco (existencia e resultado atual)
  const resultadosE = []; // resultados válidos lidos do papel
  const COLE = { ct: 'CT', bl72: 'BL72', bl120: 'BL120' };
  const valorDe = (v) => {
    if (v === null || v === undefined) return null;
    const s = String(v).trim().replace(/\s+/g, '').replace(',', '.');
    if (!s || /^[-–—_.xX*]+$/.test(s)) return null;
    const m = s.match(/^([<>]?)(\d+(?:\.\d+)?)$/);
    if (!m) return { erro: String(v) };
    return { sinal: m[1] || '=', valor: Number(m[2]) };
  };
  const dubE = (Array.isArray(ia.duvidas) ? ia.duvidas : []).map((d) => String(d).trim()).filter(Boolean).slice(0, 8);
  if (!/^[A-Z.]+\s?\d+$/.test(navioE)) {
    return [{ json: { ...base, formulario, textoResposta: '📷 Li o laudo de embarque, mas não entendi o navio e a viagem (ex.: O.STAR 112). Tire outra foto ou mande o comando por escrito. Nada foi gravado.', falha: true } }];
  }
  const dataGlobal = ia.data ? dataCompleta(ia.data, false) : '';
  (Array.isArray(ia.blocos) ? ia.blocos : []).slice(0, 12).forEach((b, i) => {
    const nome = 'linha ' + (i + 1) + ' do papel';
    const linha = String(b.linha || '').replace(/\D/g, '');
    const fase = String(b.fase || '').replace(/\D/g, '');
    const load = String(b.load || '').replace(/\D/g, '');
    const item = String(b.item || '').replace(/\D/g, '');
    if (!/^\d{1,2}$/.test(linha) || !/^\d{1,2}$/.test(fase)) { probE.push(nome + ': não li a linha e a fase'); return; }
    if (!/^\d{4,6}$/.test(load)) { probE.push('linha ' + linha + ' fase ' + fase + ': não li o número do load'); return; }
    if (!/^\d{3,4}$/.test(item)) { probE.push('load ' + load + ': não li o item (está na Observação, “Item: 2648”)'); return; }
    const am = [...new Set((Array.isArray(b.amostras) ? b.amostras : []).map((x) => Number(String(x).replace(/\D/g, ''))).filter((n) => Number.isInteger(n) && n > 0 && n < 100))].sort((x, y) => x - y);
    if (!am.length) { probE.push('load ' + load + ': não li as amostras (A1, A2...)'); return; }
    const data = b.data ? dataCompleta(b.data, false) : dataGlobal;
    if (!data) dubE.push('load ' + load + ': sem a data da análise, vale a de hoje');
    am.forEach((n) => reqs.push({ idx: reqs.length, navio: navioE, linha: Number(linha), fase: Number(fase), numero: n, analise: null }));
    const resB = b.resultados && typeof b.resultados === 'object' ? b.resultados : {};
    for (const [chave, cel] of Object.entries(resB)) {
      const n = Number(String(chave).replace(/\D/g, ''));
      if (!am.includes(n) || !cel || typeof cel !== 'object') continue;
      for (const [col, an] of Object.entries(COLE)) {
        const v = valorDe(cel[col]);
        if (!v) continue;
        if (v.erro) { dubE.push('load ' + load + ' A' + n + ' ' + an + ': não entendi "' + v.erro + '"; fica de fora'); continue; }
        const req = { idx: reqs.length, navio: navioE, linha: Number(linha), fase: Number(fase), numero: n, analise: an };
        reqs.push(req);
        resultadosE.push({ idx: req.idx, analise: an, numero: n, linha, fase, load, sinal: v.sinal, valor: v.valor });
      }
    }
    comE.push({ tipo: 'embarque', load, linha, fase, amostras: compactar(am), texto: 'Embarque navio ' + navioE + ' linha ' + linha + ' fase ' + fase + ' load ' + load + ' item ' + item + ' amostras ' + compactar(am) + (data ? ' data ' + data : ''), item });
  });
  if (!comE.length) {
    const motivo = probE.length ? '\n• ' + probE.join('\n• ') : '';
    return [{ json: { ...base, formulario, textoResposta: '📷 Li o laudo de embarque, mas não consegui montar nenhum comando.' + motivo + '\n\nTire outra foto ou mande o comando por escrito. Nada foi gravado.', falha: true } }];
  }
  return [{ json: { ...base, formulario, navio: navioE, data: dataGlobal, comandos: comE, buscas: [], buscasAmostras: reqs, resultados: resultadosE, duvidas: dubE, problemas: probE } }];
}

// ---- NFC: resultados das placas dos tanques (triplicata) ----
if (formulario === 'nfc') {
  // coluna do papel -> [análise, método, etapa, nome no comando]
  const COLUNAS = {
    ct: ['CT', 'Profundidade', 'final', 'ct'],
    bl72: ['BL', 'Profundidade', 'pre', 'bl72'],
    bl120: ['BL', 'Profundidade', 'final', 'bl120'],
    wort_prof_120: ['WORT', 'Profundidade', 'pre', 'wort profundidade 120h'],
    wort_prof_240: ['WORT', 'Profundidade', 'final', 'wort profundidade 240h'],
    wort_sup_120: ['WORT', 'Superficie', 'pre', 'wort superficie 120h'],
    wort_sup_240: ['WORT', 'Superficie', 'final', 'wort superficie 240h'],
  };
  const FRASCOS = [['normal', 'Normal'], ['stress', 'Stress']];
  // 3 placas: lista de 3 textos, ou texto corrido ("<1<1<1", "954", "11<1"); com mais de 3 unidades não dá para separar
  function placasDe(v) {
    if (v === null || v === undefined) return { vazio: true };
    let toks;
    if (Array.isArray(v) && v.length === 3 && v.every((x) => /^[<>]?\d+$/.test(String(x).replace(/\s+/g, '')))) {
      toks = v.map((x) => String(x).replace(/\s+/g, ''));
    } else {
      // lista de 1 item ("392") ou de tamanho errado: trata como o texto corrido da celula
      const s = (Array.isArray(v) ? v.join(' ') : String(v)).trim();
      if (!s || /^[-–—_.]+$/.test(s)) return { vazio: true };
      if (/[,;\s]/.test(s)) toks = s.split(/[,;\s]+/).filter(Boolean);
      else {
        // so digitos: 3 = 1+1+1 e 6 = 2+2+2 (nenhuma placa passa de 99); 4 ou 5 digitos nao da para separar
        if (/^\d{6}$/.test(s)) toks = s.match(/\d\d/g);
        else {
          const un = s.match(/[<>]?\d/g);
          if (!un || un.join('') !== s || s.includes('>') || un.length !== 3) return { ambiguo: true, escrito: s };
          toks = un;
        }
      }
      if (toks.length !== 3 || !toks.every((x) => /^[<>]?\d+$/.test(x))) return { ambiguo: true, escrito: s };
    }
    const placas = [];
    for (const [i, x] of toks.entries()) {
      const m = x.match(/^([<>]?)(\d+)$/);
      const valor = Number(m[2]);
      if (m[1] === '<' && valor !== 1) return { ambiguo: true, escrito: toks.join(' ') };
      placas.push(m[1] === '>' ? { placa: i + 1, sinal: '>', valor }
        : (valor === 0 || m[1] === '<') ? { placa: i + 1, sinal: '<', valor: 1 } : { placa: i + 1, sinal: '=', valor });
    }
    return { placas };
  }
  const navioDe = (x) => String(x || '').toUpperCase().replace(/^ORANGE\s+/, 'O.').replace(/\s*\.\s*/g, '.').replace(/\s+/g, ' ').trim();

  const itens = [];
  const excluidos = [];
  const problemasN = [];
  const duvidasN = (Array.isArray(ia.duvidas) ? ia.duvidas : []).map((d) => String(d).trim()).filter(Boolean).slice(0, 8);
  const blocosN = Array.isArray(ia.blocos) ? ia.blocos.slice(0, 4) : [];
  const resumoBlocos = [];
  blocosN.forEach((b) => {
    const navio = navioDe(b.navio);
    if (navio && !/^[A-Z.]+\s?\d+$/.test(navio)) { problemasN.push(`navio "${b.navio}" não parece nome e viagem (ex.: O.STAR 112)`); return; }
    const coleta = b.coleta ? dataCompleta(b.coleta, true) : '';
    if (b.coleta && !coleta) duvidasN.push(`data da coleta "${b.coleta}" ilegível`);
    if (!coleta) duvidasN.push('sem a data da coleta: uso a leitura mais recente que está para ler');
    resumoBlocos.push({ navio, coleta });
    (Array.isArray(b.tanques) ? b.tanques : []).slice(0, 40).forEach((t) => {
      const tanque = String(t && t.tanque || '').toUpperCase().replace(/[^0-9A-Z]/g, '');
      if (!/^\d{1,3}[A-Z]?$/.test(tanque)) { problemasN.push(`tanque "${t && t.tanque}" ilegível`); return; }
      if (navio && !/[CPS]$/.test(tanque)) { problemasN.push(`tanque ${tanque}: faltou a letra (C, P ou S)`); return; }
      for (const [chaveF, frasco] of FRASCOS) {
        const cel = t && t[chaveF];
        if (!cel || typeof cel !== 'object') continue;
        for (const [col, [sub, metodo, etapa, cmd]] of Object.entries(COLUNAS)) {
          const r = placasDe(cel[col]);
          if (r.vazio) continue;
          if (r.ambiguo) { excluidos.push({ tanque, frasco, col, escrito: r.escrito, cmd, navio, coleta }); continue; }
          itens.push({ idx: itens.length, tanque, navio, frasco, sub, metodo, etapa, coleta, col, cmd, placas: r.placas });
        }
      }
    });
  });
  if (!itens.length) {
    const motivo = [...problemasN, ...excluidos.map((e) => `tanque ${e.tanque} ${e.frasco.toLowerCase()} ${e.col}: não separei as 3 placas ("${e.escrito}")`)];
    return [{ json: { ...base, formulario, textoResposta: `📷 Li o papel (NFC), mas não consegui montar nenhuma leitura.${motivo.length ? '\n• ' + motivo.join('\n• ') : ''}\n\nTire outra foto ou mande os comandos de placa (escreva *comandos placas*). Nada foi gravado.`, falha: true } }];
  }
  const buscasPlacas = itens.map((i) => ({ idx: i.idx, tanque: i.tanque, navio: i.navio, frasco: i.frasco, sub: i.sub, metodo: i.metodo, etapa: i.etapa, coleta: i.coleta }));
  return [{ json: { ...base, formulario, nfc: { itens, excluidos, blocos: resumoBlocos, analise: ia.data ? dataCompleta(ia.data, false) : '' },
    buscasPlacas, duvidas: duvidasN, problemas: problemasN } }];
}


// ---- Coliformes em suco: folha CUMULATIVA, cada linha é uma composta com a data do seu grupo ----
// Recebimento (load + lotes, fábrica e item na Observação) ou embarque (navio, linha/fase ou load, amostras A1-A3).
// Só valem as linhas a partir de 13/10/2026 (início do piloto). "—" = lido negativo, "+" = positivo, vazio = no caldo.
// E.coli "+" só gera aviso (o sistema guarda o resultado de Coliformes Totais).
if (formulario === 'coliformes') {
  const INICIO = '13/10/2026';
  const ymd = (d) => String(d).split('/').reverse().join('');
  // dúvidas da IA que só fazem barulho: resultado em branco (vai para o caldo) e data "assumida" (cada linha já tem a sua data)
  const RUIDO = [/em branco|vazi[ao]s?|n[ãa]o preenchid|sem resultado/i, /data.*(assumid|considerad|interpretad|entendid)|(assumid|considerad).*data/i];
  const dub = (Array.isArray(ia.duvidas) ? ia.duvidas : []).map((d) => String(d).trim()).filter((d) => d && !RUIDO.some((r) => r.test(d))).slice(0, 8);
  const prob = [];
  const linhasColi = [];
  let ignoradas = 0;
  const res = (v) => {
    const s = String(v == null ? '' : v).trim();
    if (!s) return null;
    if (/^\+/.test(s) || /^pos/i.test(s)) return 'positivo';
    if (/^[-–—_]+$/.test(s) || /^neg/i.test(s)) return 'negativo';
    return '?';
  };
  const navioDe = (x) => {
    const s = String(x || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s*\.\s*/g, '.').replace(/\s+/g, ' ').trim()
      .replace(/^ORANGE\s+/, 'O.').replace(/^O\s+/, 'O.');
    const m = s.match(/^(O\.?[A-Z]+)\s*(\d{1,4})$/);
    return m ? m[1].replace(/^O(?!\.)/, 'O.') + ' ' + m[2] : '';
  };
  let dataAnt = ia.data ? dataCompleta(ia.data, false) : '';
  (Array.isArray(ia.blocos) ? ia.blocos : []).slice(0, 60).forEach((b, i) => {
    const data = b.data ? dataCompleta(b.data, false) : dataAnt;
    if (b.data && !data) { prob.push(`linha ${i + 1}: data "${b.data}" ilegível`); return; }
    if (!data) { prob.push(`linha ${i + 1}: sem data`); return; }
    dataAnt = data;
    if (ymd(data) < ymd(INICIO)) { ignoradas++; return; }
    if (ymd(data) > ymd(hoje)) { prob.push(`linha ${i + 1}: data ${data} no futuro; confira`); return; }
    const resultado = res(b.coliformes);
    const ecoli = res(b.ecoli);
    const quem = b.navio ? String(b.navio) : `load ${b.load || '?'}`;
    if (resultado === '?') { dub.push(`${quem} (${data}): não entendi o resultado de Coliformes "${b.coliformes}"; ficou como no caldo`); }
    if (ecoli === 'positivo') dub.push(`${quem} (${data}): E.coli positivo (+) no papel; o sistema guarda só Coliformes Totais: confira`);
    const r = resultado === '?' ? null : resultado;
    const load = String(b.load || '').replace(/\D/g, '');
    const item = String(b.item || '').replace(/\D/g, '');
    if (b.navio || b.linha || (Array.isArray(b.amostras) && b.amostras.length)) {
      const navio = navioDe(b.navio);
      const amostras = (Array.isArray(b.amostras) ? b.amostras : []).map((x) => Number(String(x).replace(/\D/g, ''))).filter((n) => n > 0);
      const linha = Number(String(b.linha || '').replace(/\D/g, '')) || null;
      const fase = Number(String(b.fase || '').replace(/\D/g, '')) || null;
      if (!navio) { prob.push(`linha ${i + 1} (embarque): não li o navio e a viagem`); return; }
      if (!amostras.length) { prob.push(`${navio} (${data}): não li as amostras (A1-A3) da linha ${i + 1}`); return; }
      if (!(linha && fase) && !/^\d{4,6}$/.test(load)) { prob.push(`${navio} (${data}): a linha ${i + 1} não tem linha/fase nem load`); return; }
      linhasColi.push({ idx: linhasColi.length, kind: 'emb', data, navio, linha: linha && fase ? linha : null, fase: linha && fase ? fase : null,
        load: /^\d{4,6}$/.test(load) ? load : '', amostras: [...new Set(amostras)].sort((x, y) => x - y), item, resultado: r });
      return;
    }
    if (!/^\d{4,6}$/.test(load)) { prob.push(`linha ${i + 1}: não li o número do load`); return; }
    const fab = fabrica(b.fabrica);
    if (b.fabrica && !fab) dub.push(`load ${load}: fábrica "${b.fabrica}" não é uma das seis; para abrir a composta, mande o comando`);
    if (fab && fab.lido) dub.push(`load ${load}: li a fábrica como "${fab.lido}" e entendi ${fab.sigla}`);
    const faixas = Array.isArray(b.compostas) ? b.compostas : (b.lotes ? [b.lotes] : []);
    if (!faixas.length) { prob.push(`load ${load} (${data}): não li os lotes da composta`); return; }
    faixas.forEach((c) => {
      const lotes = lotesDe(c);
      if (!lotes) { prob.push(`load ${load}: não entendi a composta "${c}"`); return; }
      linhasColi.push({ idx: linhasColi.length, kind: 'receb', data, load, item, fabrica: fab ? fab.sigla : '', lotes, resultado: r });
    });
  });
  if (!linhasColi.length) {
    const motivo = [...prob, ...(ignoradas ? [`${ignoradas} linha(s) com data antes de ${INICIO} (início do piloto) não entram`] : [])];
    return [{ json: { ...base, formulario, textoResposta: '📷 Li a folha de Coliformes, mas não há linha para registrar.' + (motivo.length ? '\n• ' + motivo.join('\n• ') : '') +
      '\n\nNada foi gravado.', falha: true } }];
  }
  const buscasColi = linhasColi.map((x) => ({ idx: x.idx, load: x.kind === 'receb' ? x.load : '', item: x.item || '', lotes: x.lotes || [],
    navio: x.navio || '', linha: x.linha, fase: x.fase, load_emb: x.kind === 'emb' ? x.load : '', amostras: x.amostras || [] }));
  return [{ json: { ...base, formulario, data: '', linhasColi, buscasColi, ignoradas, inicio: INICIO, duvidas: dub, problemas: prob } }];
}

const dataAnalise = ia.data ? dataCompleta(ia.data, false) : '';
const duvidas = (Array.isArray(ia.duvidas) ? ia.duvidas : []).map((d) => String(d).trim()).filter(Boolean).slice(0, 8);
const problemas = [];
const comandos = [];
const buscas = [];
if (ia.data && !dataAnalise) duvidas.push(`data "${ia.data}" ilegível`);

// bloco só de tanques (TAB de NFC, "TQ 44 16/10"): não tem load; a data é a da coleta
function tanquesSemLoad(b) {
  const porData = new Map();
  b.tanques.forEach((t) => {
    const tanque = String(t && t.tanque || '').replace(/\D/g, '');
    const data = dataCompleta(t && t.data, true);
    if (!tanque || !data) { problemas.push(`tanque "${t && t.tanque}" com data ilegível`); return; }
    if (!porData.has(data)) porData.set(data, []);
    porData.get(data).push(tanque);
  });
  for (const [data, tanques] of porData) {
    comandos.push({ tipo: 'tab_tanques', tanques: [...new Set(tanques)], coleta: data, texto: `Tab feito dos tanques terra ${[...new Set(tanques)].join(',')} coleta ${data}` });
  }
}
const blocos = Array.isArray(ia.blocos) ? ia.blocos.slice(0, 10) : [];
blocos.forEach((b, i) => {
  const nome = `bloco ${i + 1}`;
  const load = String(b.load || '').replace(/\D/g, '');
  const item = String(b.item || '').replace(/\D/g, '');
  if (!/^\d{4,6}$/.test(load)) {
    if (formulario === 'tab' && Array.isArray(b.tanques) && b.tanques.length) { tanquesSemLoad(b); return; }
    problemas.push(`${nome}: não li o número do load`); return;
  }
  if (b.navio) { problemas.push(`load ${load}: laudo de embarque ainda não leio; mande o comando`); return; }
  if (!/^\d{3,4}$/.test(item) && formulario === 'recebimento') { problemas.push(`load ${load}: não li o item`); return; }
  const itemTxt = item ? ` item ${item}` : '';

  if (formulario === 'recebimento') {
    const fab = fabrica(b.fabrica);
    if (!fab) { problemas.push(`load ${load}: fábrica "${b.fabrica || '?'}" não é uma das seis (AQA, CON, COL, UCH, ITA, TMG)`); return; }
    if (fab.lido) duvidas.push(`load ${load}: li a fábrica como "${fab.lido}" e entendi ${fab.sigla}`);
    const lista = (Array.isArray(b.lotes) ? b.lotes : []).map((l) => ({ n: Number(l && l.n), fecha: !!(l && l.fecha) }))
      .filter((l) => Number.isInteger(l.n) && l.n > 0);
    if (!lista.length) { problemas.push(`load ${load}: não li os lotes`); return; }
    if (new Set(lista.map((l) => l.n)).size !== lista.length) { problemas.push(`load ${load}: lotes repetidos, confira a foto`); return; }
    comandos.push({ tipo: 'recebimento', load, lotes: compactar(lista.map((l) => l.n)), texto: `Recebimento load ${load} item ${item} fabrica ${fab.sigla} lotes ${compactar(lista.map((l) => l.n))}${dataAnalise ? ' data ' + dataAnalise : ''}` });
    if (!dataAnalise) duvidas.push(`load ${load}: sem a data da análise, vale a de hoje`);
    // composta = lotes até a marca; o último lote fecha a última composta
    if (lista.some((l) => l.fecha)) {
      const grupos = [[]];
      lista.forEach((l) => { grupos[grupos.length - 1].push(l.n); if (l.fecha) grupos.push([]); });
      const cheios = grupos.filter((g) => g.length);
      comandos.push({ tipo: 'compostas', load, texto: `Compostas do load ${load}${itemTxt} ${cheios.map((g) => `(${compactar(g)})`).join('')}`, compostas: cheios.length, grupos: cheios.map((g) => compactar(g)) });
    } else {
      duvidas.push(`load ${load}: sem marca de composta na foto, gravo só o recebimento`);
    }
    return;
  }

  // TAB e Coliformes de caldo: uma composta por linha, achada pelo load e pelos lotes
  const rotulo = formulario === 'tab' ? 'Tab' : 'Coliformes';
  const verbo = formulario === 'tab' ? 'feito' : 'feitos';
  // uma composta não pode repetir lote de outra: recusa antes do "sim", sem gravar o recebimento pela metade
  const donos = new Map();
  const repetidos = [];
  (Array.isArray(b.compostas) ? b.compostas : []).forEach((cc) => {
    const ls = lotesDe(cc);
    if (ls) ls.forEach((n) => { if (donos.has(n) && donos.get(n) !== cc) repetidos.push(`lote ${n} em (${donos.get(n)}) e em (${cc})`); else donos.set(n, cc); });
  });
  if (repetidos.length) { problemas.push(`load ${load}: ${repetidos.slice(0, 3).join('; ')}. Uma composta não pode repetir lote; confira a foto ou mande o comando`); return; }
  let achou = false;
  // TAB: o resultado de cada composta, na mesma ordem ("+" positivo já confirmado, "-" negativo, em branco = caldo)
  const resTab = (v) => { const s = String(v == null ? '' : v).trim().toLowerCase(); if (/^(\+|positivo|detectado)$/.test(s)) return 'positivo'; if (/^(-|—|–|−|negativo|nao detectado|não detectado)$/.test(s)) return 'negativo'; return null; };
  (Array.isArray(b.compostas) ? b.compostas : []).forEach((c, k) => {
    const lotes = lotesDe(c);
    if (!lotes) { problemas.push(`load ${load}: não entendi a composta "${c}"`); return; }
    achou = true;
    const texto = `${rotulo} ${verbo} do load ${load}${itemTxt} lotes ${compactar(lotes)}`;
    buscas.push({ idx: comandos.length, load, item, lotes });
    const fabT = fabrica(b.fabrica);
    const resultado = formulario === 'tab' && Array.isArray(b.resultados) ? resTab(b.resultados[k]) : null;
    comandos.push({ tipo: formulario, load, item, texto, lotes: compactar(lotes), fabrica: fabT ? fabT.sigla : '', resultado });
  });
  if (formulario === 'tab') {
    const porData = new Map();
    (Array.isArray(b.tanques) ? b.tanques : []).forEach((t) => {
      const tanque = String(t && t.tanque || '').replace(/\D/g, '');
      const data = dataCompleta(t && t.data, true);
      if (!tanque || !data) { problemas.push(`tanque "${t && t.tanque}" com data ilegível`); return; }
      if (!porData.has(data)) porData.set(data, []);
      porData.get(data).push(tanque);
    });
    for (const [data, tanques] of porData) {
      achou = true;
      comandos.push({ tipo: 'tab_tanques', tanques: [...new Set(tanques)], coleta: data, texto: `Tab feito dos tanques terra ${[...new Set(tanques)].join(',')} coleta ${data}` });
    }
  }
  if (!achou) problemas.push(`load ${load}: não li nenhuma composta`);
});

if (!comandos.length) {
  const motivo = problemas.length ? '\n• ' + problemas.join('\n• ') : '';
  return [{ json: { ...base, formulario, textoResposta: `📷 Li o papel (${FORMULARIOS[formulario]}), mas não consegui montar nenhum comando.${motivo}\n\nTire outra foto ou mande o comando por escrito. Nada foi gravado.`, falha: true } }];
}
// data do TAB/Coliformes: a do papel quando é de hoje ou dos últimos 3 dias; senão vale hoje (e avisa)
let dataFeito = '';
if ((formulario === 'tab' || formulario === 'coliformes') && dataAnalise) {
  const [d0, m0, a0] = dataAnalise.split('/').map(Number);
  const dif = Math.round((new Date(anoHoje, hm - 1, hd) - new Date(a0, m0 - 1, d0)) / 86400000);
  if (dif >= 0 && dif <= 3) dataFeito = dataAnalise === hoje ? '' : dataAnalise;
  else duvidas.push('a data do papel (' + dataAnalise + ') não é de hoje nem dos últimos 3 dias: vale a data de hoje');
}
// TAB de tanque de terra: o banco diz se a coleta existe e se já tem TAB (o que já tem fica de fora)
const buscasTanques = comandos.flatMap((c, i) => (c.tipo === 'tab_tanques' ? c.tanques.map((t) => ({ idx: i, tanque: t, coleta: c.coleta })) : []));
return [{ json: { ...base, formulario, data: dataAnalise, dataFeito, comandos, buscas, buscasTanques, duvidas, problemas } }];

// Foto de laudo: junta a lista de comandos com as compostas achadas no banco e monta a confirmação.
const d = $('Foto · Interpretar').first().json;
if (d.falha) return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '0', payload: '{}', textoResposta: d.textoResposta } }];

if (d.formulario === 'nfc') {
// ---- NFC: leituras de placas lidas da foto ----
const rowsP = $input.all().map((i) => i.json).filter((r) => r && r.kind === 'placa');
const porIdx = new Map(rowsP.map((r) => [Number(r.idx), r]));
const nfc = d.nfc;
const ROT = { ct: 'CT', bl72: 'BL72', bl120: 'BL120', wort_prof_120: 'WP120', wort_prof_240: 'WP240', wort_sup_120: 'WS120', wort_sup_240: 'WS240' };
const txt = (p) => (p.sinal === '=' ? String(p.valor) : p.sinal + p.valor);
const lerItens = [];
const semAnalise = new Map();
nfc.itens.forEach((it) => {
  const r = porIdx.get(it.idx);
  if (!r || !r.analise_id) {
    const k = `${it.tanque} ${it.frasco.toLowerCase()}`;
    if (!semAnalise.has(k)) semAnalise.set(k, []);
    semAnalise.get(k).push(ROT[it.col]);
    return;
  }
  const limite = r.limite === null || r.limite === undefined ? null : Number(r.limite);
  const acima = it.placas.some((p) => p.sinal === '>' || (limite !== null && p.sinal === '=' && p.valor > limite));
  lerItens.push({ ...it, analise_id: Number(r.analise_id), acima, semLimite: limite === null, jaLida: Number(r.ja_lidas) > 0, temDesvio: !!r.tem_desvio, dataColeta: r.data_coleta });
});

const avisos = [...d.duvidas.map((x) => `• ${x}`), ...d.problemas.map((x) => `• ${x}`)];
// comando pronto para a pessoa corrigir a célula que ficou de fora (V1,V2,V3 = as 3 placas, na ordem do papel)
const cmdExcl = (e) => `${e.cmd} do tanque ${e.tanque}${e.navio ? ' navio ' + e.navio : ''} ${e.frasco.toLowerCase()} V1,V2,V3${e.coleta ? ' coleta ' + e.coleta : ''}`;
nfc.excluidos.forEach((e) => avisos.push(`• tanque ${e.tanque} ${e.frasco.toLowerCase()} ${ROT[e.col]} ("${e.escrito}"): não separei as 3 placas; fica de fora. Depois do sim, mande: ${cmdExcl(e)}`));
const dicaExcl = nfc.excluidos.length ? '\n\nNos comandos acima, troque V1,V2,V3 pelas 3 placas, na ordem do papel (0 ou <1 = sem colônia).' : '';
for (const [k, an] of semAnalise) avisos.push(`• tanque ${k}: não achei análise para ler (${an.join(', ')}); fica de fora`);

if (!lerItens.length) {
  return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '0', payload: '{}', tipoPendencia: 'PLACAS',
    textoResposta: `📷 NFC: nenhuma leitura ficou pronta para gravar.\n${avisos.join('\n')}\n\nNada foi gravado. Confira se as análises desses tanques foram registradas (escreva *comandos analise*).` } }];
}

const bloco = nfc.blocos[0] || {};
const cab = `${bloco.navio ? 'navio ' + bloco.navio : 'tanques de terra'}${bloco.coleta ? ', coleta ' + bloco.coleta : ''}`;
// uma linha por tanque e frasco
const grupos = new Map();
lerItens.forEach((it) => {
  const k = `${it.tanque}|${it.frasco}`;
  if (!grupos.has(k)) grupos.set(k, []);
  grupos.get(k).push(it);
});
const linhas = [];
for (const [k, lista] of grupos) {
  const [tanque, frasco] = k.split('|');
  linhas.push(`${tanque} ${frasco.toLowerCase()}: ` + lista.map((it) => `${ROT[it.col]} ${it.placas.map(txt).join(',')}${it.acima ? ' 🚨' : (it.semLimite ? ' ℹ️' : '')}`).join(' · '));
}
const naoOk = lerItens.filter((it) => it.acima);
const semLimite = lerItens.filter((it) => it.semLimite && !it.acima);
const substituem = lerItens.filter((it) => it.jaLida).length;
const placasTotal = lerItens.length * 3;

const resumoCab = `${lerItens.length} leitura${lerItens.length > 1 ? 's' : ''} (${placasTotal} placas): ${lerItens.length - naoOk.length - semLimite.length} ok${naoOk.length ? ` · ${naoOk.length} 🚨 não ok` : ''}${semLimite.length ? ` · ${semLimite.length} sem limite cadastrado` : ''}`;
const comandoDe = (it) => `${it.cmd} do tanque ${it.tanque}${it.navio ? ' navio ' + it.navio : ''} ${it.frasco.toLowerCase()} ${it.placas.map(txt).join(',')}${it.dataColeta ? ' coleta ' + it.dataColeta : ''}`;
const listaNaoOk = naoOk.map((it) => `• ${it.tanque} ${it.frasco.toLowerCase()} ${ROT[it.col]}: ${it.placas.map(txt).join(', ')}${it.temDesvio ? ' (já tem desvio)' : ''}\n   ${it.temDesvio ? '' : 'para abrir o desvio, mande: ' + comandoDe(it)}`.trimEnd()).join('\n');

const pergunta = `📷 NFC — ${cab}:\n\n${linhas.join('\n')}\n\n` +
  `${resumoCab}.` +
  (avisos.length ? `\n\n⚠️ Confira:\n${avisos.join('\n')}${dicaExcl}` : '') +
  (substituem ? `\n\nℹ️ ${substituem} leitura(s) já tinham placas: os valores novos substituem os antigos.` : '') +
  '\n\nResponda *sim* para gravar tudo ou *não* para cancelar.';

const final = `✅ Gravado: laudo de NFC — ${cab}.\n${resumoCab}.` +
  (naoOk.length ? `\n\n🚨 Não ok (nenhum desvio foi aberto):\n${listaNaoOk}` : '') +
  (avisos.length ? `\n\nFicaram de fora (troque V1,V2,V3 pelas 3 placas, 0 ou <1 = sem colônia):\n${[...nfc.excluidos.map((e) => `• tanque ${e.tanque} ${e.frasco.toLowerCase()} ${ROT[e.col]} ("${e.escrito}"): mande ${cmdExcl(e)}`), ...[...semAnalise].map(([k, an]) => `• tanque ${k} (${an.join(', ')}): sem análise`)].join('\n') || '• (nada além dos avisos acima)'}` : '');

const payload = { acao: 'placas_lote', itens: lerItens.map((it) => ({ analise_id: it.analise_id, etapa: it.etapa, placas: it.placas })) };
return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '1', tipoPendencia: 'PLACAS', payload: JSON.stringify(payload), resumo: final, textoResposta: pergunta } }];

}

if (d.formulario === 'embarque') {
  // resultados de C.T/B.L por amostra: gravam em lote (um sim) quando o embarque já está registrado
  const ams = new Map($input.all().map((i) => i.json).filter((x) => x && x.kind === 'amostra').map((x) => [Number(x.idx), x]));
  const existem = (d.buscasAmostras || []).filter((x) => x.analise === null);
  const todasExistem = existem.length > 0 && existem.every((x) => (ams.get(x.idx) || {}).alvo_id);
  const resultados = d.resultados || [];
  if (todasExistem) {
    const avisosR = d.duvidas.map((x) => `• ${x}`).concat(d.problemas.map((x) => `• ${x}`));
    existem.forEach((x) => {
      const a = ams.get(x.idx);
      const doLoad = d.comandos.find((c) => String(c.linha) === String(x.linha) && String(c.fase) === String(x.fase));
      if (doLoad && a.load_num && String(a.load_num) !== String(doLoad.load)) avisosR.push(`• linha ${x.linha} fase ${x.fase}: A${x.numero} está no load ${a.load_num} no sistema e o papel diz ${doLoad.load}`);
    });
    if (!resultados.length) {
      return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '0', payload: '{}', tipoPendencia: 'TAB',
        textoResposta: `📷 Embarque ${d.navio}: nada novo para registrar.${avisosR.length ? '\n\n⚠️ Confira:\n' + avisosR.join('\n') : ''}` } }];
    }
    const LIM = { CT: 200, BL72: 50, BL120: 50 };
    const fmt = (x) => (x.sinal === '=' ? '' : x.sinal) + String(x.valor).replace('.', ',');
    const grupos = new Map();
    resultados.forEach((x) => {
      const k = `${x.linha}|${x.fase}|${x.load}`;
      if (!grupos.has(k)) grupos.set(k, new Map());
      const g = grupos.get(k);
      if (!g.has(x.numero)) g.set(x.numero, []);
      g.get(x.numero).push(x);
    });
    const linhasR = [];
    const alarmes = [];
    const correcoes = [];
    for (const [k, g] of grupos) {
      const [linha, fase, load] = k.split('|');
      linhasR.push(`linha ${linha} fase ${fase} · load ${load}:`);
      [...g.keys()].sort((x, y) => x - y).forEach((n) => {
        linhasR.push(`   A${n}: ` + g.get(n).map((x) => {
          const alarme = x.sinal !== '<' && x.valor >= LIM[x.analise];
          if (alarme) alarmes.push(`A${n} ${x.analise} = ${fmt(x)}`);
          const atual = (ams.get(x.idx) || {}).atual;
          if (atual !== null && atual !== undefined && atual !== '') correcoes.push(`A${n} ${x.analise} (era ${String(atual).replace('.', ',')})`);
          return `${x.analise} ${fmt(x)}${alarme ? ' 🚨' : ''}`;
        }).join(' · '));
      });
    }
    const extra = [];
    if (alarmes.length) extra.push(`🚨 Acima do limite (C.T ≥ 200, B.L ≥ 50): ${alarmes.join(', ')}`);
    if (correcoes.length) extra.push(`⚠️ Corrige resultado anterior: ${correcoes.join(', ')}`);
    const cab = `${resultados.length} resultado${resultados.length > 1 ? 's' : ''} de C.T/B.L`;
    const texto = `📷 Embarque ${d.navio} — resultados:\n\n${linhasR.join('\n')}\n\n${cab}.` +
      (extra.length ? '\n' + extra.join('\n') : '') +
      (avisosR.length ? `\n\n⚠️ Confira:\n${avisosR.join('\n')}` : '') +
      '\n\nResponda *sim* para gravar tudo ou *não* para cancelar.';
    const payload = { acao: 'contagem_lote', itens: resultados.map((x) => ({ analise: x.analise, alvo: 'amostra', id: Number((ams.get(x.idx) || {}).alvo_id), sinal: x.sinal, valor: x.valor })) };
    return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '1', tipoPendencia: 'TAB', payload: JSON.stringify(payload),
      resumo: `Resultados do laudo de embarque ${d.navio} gravados:\n${linhasR.join('\n')}\n${cab}.${extra.length ? '\n' + extra.join('\n') : ''}`, textoResposta: texto } }];
  }
  // embarque ainda não registrado: registra agora; os resultados são lidos quando a foto for enviada de novo
  if (resultados.length) d.duvidas.push(`li ${resultados.length} resultado(s) de C.T/B.L, mas o embarque ainda não está registrado: registre agora (sim) e mande a foto de novo para gravar os resultados`);
}

if (d.formulario === 'recebimento_nfc') {
  // Recebimento NFC: cada linha do papel é um lote com a sua data. Só entra na pergunta o que é NOVO: lote que ainda não
  // está registrado (registra e grava os resultados da linha) e resultado que falta ou mudou num lote já registrado.
  // O que já está igual no banco não aparece. Tudo vai num comando só e um sim, sem mandar a foto de novo.
  // O chat mostra o número do laudo; o banco grava também o valor multiplicado pela diluição (Power BI).
  const nf = new Map($input.all().map((i) => i.json).filter((x) => x && x.kind === 'nfc').map((x) => [Number(x.idx), x]));
  const reqDe = (c) => (d.buscasNfc || []).find((x) => x.analise === null && x.load === c.load && x.lote === c.lote && x.amostra === c.amostra);
  const fmtN = (sinal, valor) => (sinal === '=' ? '' : sinal) + String(Number(Number(valor).toFixed(6)));
  const mesmo = (a, b) => String(a || '').replace(',', '.').replace(/^=/, '') === String(b || '').replace(',', '.').replace(/^=/, '');
  const avisosN = d.duvidas.map((x) => `• ${x}`).concat(d.problemas.map((x) => `• ${x}`));
  const novos = [];
  const novosRes = [];
  const correcoes = [];
  const comandosN = [];
  d.comandos.forEach((c) => {
    const ex = nf.get(Number((reqDe(c) || {}).idx)) || {};
    const registrado = !!ex.alvo_id;
    const res = (d.resultadosNfc || []).filter((x) => x.load === c.load && x.lote === c.lote && x.amostra === c.amostra);
    const gravar = [];
    const textos = [];
    res.forEach((x) => {
      const atual = (nf.get(x.idx) || {}).atual;
      const papel = fmtN(x.sinal, x.lido);
      if (registrado && atual !== null && atual !== undefined && atual !== '' && mesmo(atual, papel)) return; // já está igual
      gravar.push(`${x.analise.toLowerCase()} ${papel}`);
      textos.push(`${x.analise} ${papel}` + (registrado && atual ? ` (era ${atual})` : ''));
      if (registrado && atual) correcoes.push(x);
    });
    const sufixo = gravar.length ? ' resultados ' + gravar.join(' ') : '';
    if (!registrado) {
      comandosN.push(c.texto + sufixo);
      novos.push(`• load ${c.load} (${c.fabrica}) lote ${c.lote} · ${c.amostra} · 10^${c.dil}${c.data ? ' · ' + c.data : ''}${textos.length ? ': ' + textos.join(' · ') : ''}`);
      return;
    }
    if (!gravar.length) return; // lote já registrado e nada novo: não aparece
    const dil = Number(ex.diluicao);
    if (Number(c.dil) !== dil) avisosN.push(`• load ${c.load} lote ${c.lote} (${c.amostra}): o papel diz 10^${c.dil} e o sistema tem 10^${dil}; usei a do sistema`);
    // o lote já existe: o comando repete o que está no banco (diluição e data do sistema), só para gravar os resultados
    comandosN.push(`Recebimento NFC load ${c.load} fab ${c.fabrica} item 129 lote ${c.lote} ${c.amostra} 10 elevado a ${dil}${ex.data_coleta ? ' data ' + ex.data_coleta : ''}${sufixo}`);
    novosRes.push(`• load ${c.load} lote ${c.lote} · ${c.amostra}: ${textos.join(' · ')}`);
  });
  if (!comandosN.length) {
    return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '0', payload: '{}',
      textoResposta: '📷 Recebimento NFC: nada novo para registrar.' +
        (d.problemas.length ? `\n\n⚠️ Confira:\n${d.problemas.map((x) => `• ${x}`).join('\n')}` : '') } }];
  }
  const partes = [];
  if (novos.length) partes.push(`🆕 Registrar (recebimento${novos.some((l) => l.includes(': ')) ? ' e resultados' : ''}):\n${novos.join('\n')}`);
  if (novosRes.length) partes.push(`➕ Resultados novos${correcoes.length ? ' ou corrigidos' : ''}:\n${novosRes.join('\n')}`);
  const comandoUnico = comandosN.join(' ; ');
  return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '1', payload: JSON.stringify({ comandos: [comandoUnico] }),
    resumo: comandoUnico.slice(0, 900),
    textoResposta: `📷 Recebimento NFC:\n\n${partes.join('\n\n')}` +
      (avisosN.length ? `\n\n⚠️ Confira:\n${avisosN.join('\n')}` : '') +
      '\n\nResponda *sim* para gravar ou *não* para cancelar.' } }];
}

if (d.formulario === 'coliformes') {
  const compacta = (lista) => { const ns = [...new Set(lista)].sort((p, q) => p - q); const o = []; for (let i = 0; i < ns.length; i++) { let j = i; while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++; o.push(i === j ? String(ns[i]) : ns[i] + '-' + ns[j]); i = j; } return o.join(','); };
  // Folha de Coliformes (cumulativa): só entra o que é NOVO. Composta sem Coliformes vai para o caldo com a data da linha;
  // "—" grava lido negativo e "+" grava positivo (depois do sim o bot pergunta se abre a composta lote a lote).
  // O que já está igual no sistema não aparece. Composta de recebimento que falta: só o Admin abre (como no TAB);
  // composta de embarque a foto não cria. Tudo depois de um sim: abrir compostas e o comando interno "coliformes da foto".
  const rc = new Map();
  $input.all().map((i) => i.json).filter((x) => x && x.kind === 'coli').forEach((x) => { const k = Number(x.idx); if (!rc.has(k)) rc.set(k, []); rc.get(k).push(x); });
  const admin = d.nivel === 'Admin';
  const lotesTxt = (L) => (L.kind === 'emb' ? 'A' + compacta(L.amostras).replace(/,/g, ',A').replace(/-/g, '-A') : compacta(L.lotes));
  const nomeL = (L, b) => (b && b.composta_id ? `#${b.composta_id} ` : '') +
    (L.kind === 'emb' ? `${L.navio}${L.linha ? ` linha ${L.linha} fase ${L.fase}` : ''}${L.load ? ` load ${L.load}` : ''} (${lotesTxt(L)})` : `load ${L.load} (${lotesTxt(L)})`);
  const RES = { negativo: 'Negativo', positivo: 'Positivo' };
  const grupos = { feito: [], negativo: [], positivo: [] };
  const fora = [];
  const refs = [];
  const criarC = new Map();
  const avisosItem = [];
  for (const L of d.linhasColi) {
    const achadas = (rc.get(L.idx) || []).filter((x) => x.composta_id);
    const pend = achadas.filter((x) => {
      const [status, resAntes] = String(x.atual || '').split('|');
      if (x.analise_id) {
        if (!L.resultado) return false; // já está no caldo
        if (status === 'Em confirmação') return false; // aberta lote a lote: segue pela confirmação
        if (status === 'Concluída' && resAntes === RES[L.resultado]) return false; // já está igual
      }
      return true;
    });
    const itemSis = achadas.map((x) => x.load_num).find(Boolean);
    if (itemSis && pend.length) avisosItem.push(`load ${L.load}: o papel diz item ${L.item} e o sistema tem ${itemSis}; usei a composta que já existe`);
    if (achadas.length) {
      if (!pend.length) continue;
      const acao = L.resultado || 'feito';
      const ids = pend.map((x) => '#' + x.composta_id);
      pend.forEach((x) => refs.push(`#${x.composta_id} data ${L.data} ${acao}`));
      const antes = pend.length === 1 && pend[0].analise_id && String(pend[0].atual || '').split('|')[1] ? ` (era ${String(pend[0].atual).split('|')[1]})` : '';
      grupos[acao].push({ data: L.data, txt: `${ids.join(' + ')} ${L.kind === 'emb' ? nomeL(L) : `load ${L.load} (${lotesTxt(L)})`}${antes}` });
      continue;
    }
    if (L.kind === 'emb') { fora.push(`${nomeL(L)}: não achei a composta do embarque (crie com *compostas do navio ...*; a foto não cria composta de embarque)`); continue; }
    if (!admin) { fora.push(`${nomeL(L)}: não achei essa composta (só um Admin abre a composta pelo Coliformes)`); continue; }
    if (!L.item || !L.fabrica) { fora.push(`${nomeL(L)}: para abrir a composta a foto precisa do item e da fábrica (Observação)`); continue; }
    const k = L.load + '|' + L.item + '|' + L.fabrica;
    if (!criarC.has(k)) criarC.set(k, { load: L.load, item: L.item, fabrica: L.fabrica, data: L.data, grupos: [] });
    const o = criarC.get(k);
    if (L.data.split('/').reverse().join('') < o.data.split('/').reverse().join('')) o.data = L.data;
    o.grupos.push(L.lotes);
    const acao = L.resultado || 'feito';
    refs.push(`load ${L.load} item ${L.item} (${compacta(L.lotes)}) data ${L.data} ${acao}`);
    grupos[acao].push({ data: L.data, txt: `load ${L.load} (${lotesTxt(L)}) (composta nova)` });
  }
  const porData = (lista) => {
    const m = new Map();
    lista.forEach((x) => { if (!m.has(x.data)) m.set(x.data, []); m.get(x.data).push(x.txt); });
    return [...m].map(([dt, xs]) => `• ${dt}: ${xs.join(' · ')}`).join('\n');
  };
  const avisosC = [...d.duvidas.map((x) => `• ${x}`), ...avisosItem.map((x) => `• ${x}`), ...d.problemas.map((x) => `• ${x}`), ...fora.map((x) => `• ${x} (ficou de fora)`)];
  if (!refs.length) {
    return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '0', payload: '{}',
      textoResposta: (fora.length ? '📷 Coliformes: nenhuma linha ficou pronta para gravar. Nada foi gravado.'
        : '📷 Coliformes: nada novo para gravar.') +
        (avisosC.length ? `\n\n⚠️ Confira:\n${avisosC.join('\n')}` : '') } }];
  }
  const comandosC = [];
  const abertas = [];
  for (const o of criarC.values()) {
    const gs = o.grupos.map((g) => '(' + compacta(g) + ')').join('');
    const todos = compacta(o.grupos.flat());
    comandosC.push(`Recebimento load ${o.load} item ${o.item} fabrica ${o.fabrica} lotes ${todos} data ${o.data} resultados <10`);
    comandosC.push(`Compostas do load ${o.load} item ${o.item} ${gs}`);
    abertas.push(`• load ${o.load} item ${o.item} (${o.fabrica}): recebimento dos lotes ${todos} (C.T e B.L = <10, só nos lotes novos) e compostas ${gs}`);
  }
  comandosC.push('Coliformes da foto: ' + refs.join(' ; '));
  const partes = [];
  if (grupos.feito.length) partes.push(`🧪 Vão para o caldo (sem resultado):\n${porData(grupos.feito)}`);
  if (grupos.negativo.length) partes.push(`✅ Resultado NEGATIVO (traço no papel):\n${porData(grupos.negativo)}`);
  if (grupos.positivo.length) partes.push(`🚨 Resultado POSITIVO (+):\n${porData(grupos.positivo)}\nDepois do sim, pergunto se abre a composta lote a lote para a confirmação.`);
  if (abertas.length) partes.push(`🆕 Abrir antes:\n${abertas.join('\n')}`);
  return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '1', payload: JSON.stringify({ comandos: comandosC }),
    resumo: comandosC.join(' | ').slice(0, 900),
    textoResposta: `📷 Coliformes:\n\n${partes.join('\n\n')}` +
      (avisosC.length ? `\n\n⚠️ Confira:\n${avisosC.join('\n')}` : '') +
      '\n\nResponda *sim* para gravar ou *não* para cancelar.' } }];
}

const compacta = (lista) => { const ns = [...new Set(lista)].sort((p, q) => p - q); const o = []; for (let i = 0; i < ns.length; i++) { let j = i; while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++; o.push(i === j ? String(ns[i]) : ns[i] + '-' + ns[j]); i = j; } return o.join(','); };
const rows = $input.all().map((i) => i.json).filter((r) => r && r.kind === 'composta');
const achadas = new Map(rows.map((r) => [Number(r.idx), r.composta_id]));
// item lido errado (ex.: 2653 no lugar de 2655): o load só tem um item no sistema, então vale o do sistema (e avisa)
const trocasItem = new Map();
rows.filter((r) => r.load_num).forEach((r) => {
  const c = d.comandos[Number(r.idx)];
  if (c && c.item && String(c.item) !== String(r.load_num)) { trocasItem.set(c.load, [c.item, String(r.load_num)]); c.item = String(r.load_num); }
});
for (const [load, [lido, sis]] of trocasItem) d.duvidas.push(`li o item ${lido} no load ${load}, mas no sistema ele é ${sis}: usei ${sis}`);
// TAB: o que cada composta já tem ("status|resultado"); resultado da foto (+/—) vira o comando interno "TAB da foto"
const tabSit = new Map(rows.map((r) => [Number(r.idx), r.atual || '']));
const resTab = [];
const jaResultado = [];
const jaCaldo = [];
// TAB de tanque de terra: situação de cada tanque + coleta no banco ('tab', 'coleta' ou 'sem')
const tanqueSit = new Map($input.all().map((i) => i.json).filter((r) => r && r.kind === 'tanque').map((r) => [r.load_num + '|' + r.data_coleta, r.atual]));
const gruposTq = [];
const jaTab = [];
const semColetaTq = [];
const NOME = { recebimento: 'recebimento', TAB: 'TAB', Coliformes: 'Coliformes' };
const titulo = { recebimento: 'recebimento', tab: 'TAB', coliformes: 'Coliformes', embarque: 'embarque', recebimento_nfc: 'recebimento NFC' }[d.formulario] || d.formulario;
const linhas = [];
const comandos = [];
const faltando = [];
const achados = [];
// Admin: a composta que não existe pode ser aberta pelo próprio TAB/Coliformes (recebimento + compostas + teste)
const admin = d.nivel === 'Admin';
const criar = new Map();
const lotesDe = (t) => String(t).split(',').flatMap((p) => { const x = p.match(/^(\d+)-(\d+)$/); if (!x) return [Number(p)]; const o = []; for (let i = Number(x[1]); i <= Number(x[2]); i++) o.push(i); return o; });
d.comandos.forEach((c, i) => {
  if (d.buscas.some((b) => b.idx === i)) {
    const id = achadas.get(i);
    const resF = d.formulario === 'tab' ? c.resultado : null;
    if (!id && admin && c.item && c.fabrica) {
      const k = c.load + '|' + c.item + '|' + c.fabrica;
      if (!criar.has(k)) criar.set(k, { load: c.load, item: c.item, fabrica: c.fabrica, grupos: [] });
      criar.get(k).grupos.push(c.lotes);
      if (resF) resTab.push({ id: null, load: c.load, item: c.item, lotes: c.lotes, acao: resF });
      return;
    }
    if (!id) { faltando.push(`load ${c.load} lotes ${c.lotes}: não achei essa composta`); return; }
    if (d.formulario === 'tab') {
      const st = String(tabSit.get(i) || '').split('|')[0];
      if (st === 'Concluída') { jaResultado.push(`#${id} (${c.lotes})`); return; }
      if (resF) { resTab.push({ id: Number(id), load: c.load, item: c.item, lotes: c.lotes, acao: resF }); return; }
      if (st) { jaCaldo.push(`#${id} (${c.lotes})`); return; }
    }
    achados.push({ id: Number(id), load: c.load, item: c.item, lotes: c.lotes });
    return;
  }
  // TAB de tanque de terra: tanque que já tem TAB nessa coleta fica de fora; os grupos vão juntos num comando só
  if (c.tipo === 'tab_tanques' && Array.isArray(c.tanques)) {
    const nomeTq = (t) => `${t} (coleta ${c.coleta.slice(0, 5)})`;
    const novos = [];
    c.tanques.forEach((t) => {
      const s = tanqueSit.get(t + '|' + c.coleta);
      if (s === 'tab') jaTab.push(nomeTq(t));
      else if (s === 'sem' && !admin) faltando.push(`tanque ${nomeTq(t)}: não achei a coleta; registre a coleta antes ou peça a um Admin`);
      else { if (s === 'sem') semColetaTq.push(nomeTq(t)); novos.push(t); }
    });
    if (novos.length) gruposTq.push(`${novos.join(',')} coleta ${c.coleta}`);
    return;
  }
  const txt = c.texto;
  comandos.push(txt);
  linhas.push(txt);
});
// o Admin registra também a coleta, as análises e as placas <1 já vencidas
if (gruposTq.length) {
  const txtTq = `Tab feito dos tanques terra ${gruposTq.join(' ; ')}` + (admin ? (d.dataFeito ? ' data ' + d.dataFeito : '') + ' completo' : '');
  comandos.push(txtTq);
  linhas.push(txtTq);
}
const avisoTanques = (admin && gruposTq.length)
  ? `\n\n🛢️ Tanques de terra (só o Admin faz isso pelo TAB): registro a coleta e as análises normal e stress que faltarem, marco <1,<1,<1 nas leituras e como feitos os drops que já venceram até a data do TAB, ${d.dataFeito || 'hoje'} (o que ainda não chegou na data fica sem marcar) e registro o TAB.`
  + (semColetaTq.length ? `\n🆕 Sem coleta no sistema (registro a coleta): tanque ${semColetaTq.join(', ')}.` : '')
  : '';
const jaTabTxt = jaTab.length ? `\n\nℹ️ Já têm TAB (ficam de fora): tanque ${jaTab.join(', ')}.` : '';
// composta que falta: o Admin abre pelo próprio teste (precisa da fábrica na foto); os outros cargos são orientados
if (faltando.length && ['tab', 'coliformes'].includes(d.formulario)) {
  d.duvidas.push(admin ? 'para abrir a composta que falta, a foto precisa mostrar a fábrica; ou mande o comando com fabrica AQA'
    : 'só um Admin abre a composta direto pelo ' + (d.formulario === 'tab' ? 'TAB' : 'Coliformes') + ': registre o recebimento e as compostas antes, ou peça a um Admin');
}
// TAB/Coliformes: UM comando só com todas as compostas achadas (vão juntas para o caldo, uma mensagem só)
let oQueCriaTab = '';
if (achados.length) {
  const ids = [...new Set(achados.map((a) => a.id))].sort((x, y) => x - y);
  const partes = [];
  for (let i = 0; i < ids.length; i++) {
    let j = i;
    while (j + 1 < ids.length && ids[j + 1] === ids[j] + 1) j++;
    partes.push(i === j ? `#${ids[i]}` : (j === i + 1 ? `#${ids[i]}, #${ids[j]}` : `#${ids[i]} a #${ids[j]}`));
    i = j;
  }
  const rotuloT = d.formulario === 'tab' ? 'Tab feito' : 'Coliformes feitos';
  const unico = `${rotuloT} das compostas ${partes.join(', ')}${d.dataFeito ? ' data ' + d.dataFeito : ''}`;
  comandos.unshift(unico);
  linhas.unshift(unico);
  const porLoad = new Map();
  achados.forEach((a) => { const k = `${a.load}|${a.item || ''}`; if (!porLoad.has(k)) porLoad.set(k, []); porLoad.get(k).push(a); });
  const ls = [];
  for (const [k, lista] of porLoad) { const [load, item] = k.split('|'); ls.push(`• load ${load}${item ? ` (item ${item})` : ''}: ` + lista.map((a) => `#${a.id} (${a.lotes})`).join(' · ')); }
  oQueCriaTab = `\n\n🧪 ${d.formulario === 'tab' ? 'TAB' : 'Coliformes'} no caldo, ${ids.length > 1 ? 'as ' + ids.length + ' compostas juntas' : 'a composta'}:\n${ls.join('\n')}`;
}

// Admin: abre as compostas que faltam, antes do teste (comandos oficiais, na ordem: recebimento, compostas, teste)
if (criar.size) {
  const rotuloT2 = d.formulario === 'tab' ? 'Tab feito' : 'Coliformes feitos';
  const nomeT = d.formulario === 'tab' ? 'TAB' : 'Coliformes';
  const novos = [];
  const abertas = [];
  for (const o of criar.values()) {
    const gs = o.grupos.map((g) => '(' + g + ')').join('');
    novos.push(`Recebimento load ${o.load} item ${o.item} fabrica ${o.fabrica} lotes ${compacta(o.grupos.flatMap(lotesDe))}${d.dataFeito ? ' data ' + d.dataFeito : ''} resultados <10`);
    novos.push(`Compostas do load ${o.load} item ${o.item} ${gs}`);
    novos.push(`${rotuloT2} do load ${o.load} item ${o.item} ${gs}${d.dataFeito ? ' data ' + d.dataFeito : ''}`);
    abertas.push(`• load ${o.load} (item ${o.item}, ${o.fabrica}): recebimento dos lotes ${compacta(o.grupos.flatMap(lotesDe))} (C.T, B.L 72h e B.L 120h = <10), compostas ${gs} e ${nomeT} no caldo`);
  }
  comandos.unshift(...novos); linhas.unshift(...novos);
  oQueCriaTab += `\n\n🧾 Compostas que ainda não existem (só o Admin abre pelo ${nomeT}; os lotes recebem a data do ${nomeT}):\n${abertas.join('\n')}`;
}

// TAB: os resultados (+ positivo já confirmado, — negativo) vão juntos num comando interno, depois de abrir o que faltava
if (resTab.length) {
  const ymd = (s) => String(s).split('/').reverse().join('');
  const dataRes = d.data && ymd(d.data) >= '20261013' ? d.data : '';
  comandos.push('TAB da foto: ' + resTab.map((x) => (x.id ? '#' + x.id : `load ${x.load} item ${x.item} (${x.lotes})`) + (dataRes ? ' data ' + dataRes : '') + ' ' + x.acao).join(' ; '));
}
// recebimento NFC: a lista mostra uma linha por lote, mas vai gravar tudo junto (uma mensagem só)
if (d.formulario === 'recebimento_nfc' && comandos.length > 1) comandos.splice(0, comandos.length, comandos.join(' ; '));
// TAB só com resultado (nada vai para o caldo nem é aberto): o resultado usa a data do papel, então o aviso de data não vale
if (d.formulario === 'tab' && resTab.length && !achados.length && !criar.size) d.duvidas = d.duvidas.filter((x) => !/não é de hoje nem dos últimos 3 dias/.test(x));
const avisos = [...d.duvidas.map((x) => `• ${x}`), ...d.problemas.map((x) => `• ${x}`), ...faltando.map((x) => `• ${x} (ficou de fora)`)];
if (!comandos.length && (jaTab.length || jaResultado.length || jaCaldo.length) && !faltando.length) {
  return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '0', payload: '{}',
    textoResposta: `📷 ${d.formulario === 'tab' ? 'TAB' : 'Laudo de ' + titulo}: nada novo para registrar.${avisos.length ? '\n\n⚠️ Confira:\n' + avisos.join('\n') : ''}` } }];
}
if (!comandos.length) {
  return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '0', payload: '{}',
    textoResposta: `📷 Li o laudo de ${titulo}, mas nenhum comando ficou pronto.\n${avisos.join('\n')}\n\nNada foi gravado. Confira se a composta já foi criada ou mande o comando por escrito.` } }];
}
// TAB: resposta objetiva; só o que vai para o caldo e o que se abre antes (as regras ficam por dentro, a lista de comandos não aparece)
if (d.formulario === 'tab') {
  const secoes = [];
  if (achados.length) {
    const porLoadT = new Map();
    achados.forEach((a) => { const k = `${a.load}|${a.item || ''}`; if (!porLoadT.has(k)) porLoadT.set(k, []); porLoadT.get(k).push(a); });
    const ls = [];
    for (const [k, lista] of porLoadT) { const [load, item] = k.split('|'); ls.push(`• load ${load}${item ? ` (item ${item})` : ''}: ` + lista.map((a) => `#${a.id} (${a.lotes})`).join(' · ')); }
    secoes.push(`🧪 TAB no caldo:\n${ls.join('\n')}`);
  }
  if (criar.size) {
    const ls = [];
    for (const o of criar.values()) ls.push(`• load ${o.load} (item ${o.item}, ${o.fabrica}): lotes ${compacta(o.grupos.flatMap(lotesDe))}, compostas ${o.grupos.map((g) => '(' + g + ')').join('')}`);
    secoes.push(`🆕 Compostas novas, já no caldo:\n${ls.join('\n')}`);
  }
  if (resTab.length) {
    const fmt = (lista) => { const porLoad = new Map(); lista.forEach((x) => { const k = `${x.load}|${x.item || ''}`; if (!porLoad.has(k)) porLoad.set(k, []); porLoad.get(k).push(x); });
      const ls = []; for (const [k, l] of porLoad) { const [load, item] = k.split('|'); ls.push(`• load ${load}${item ? ` (item ${item})` : ''}: ` + l.map((x) => (x.id ? `#${x.id} ` : '') + `(${x.lotes})`).join(' · ')); } return ls.join('\n'); };
    const pos = resTab.filter((x) => x.acao === 'positivo'), neg = resTab.filter((x) => x.acao === 'negativo');
    if (pos.length) secoes.push(`🚨 TAB positivo, já confirmado (+):\n${fmt(pos)}`);
    if (neg.length) secoes.push(`✅ TAB negativo (—):\n${fmt(neg)}`);
  }
  if (jaResultado.length) secoes.push(`ℹ️ Já com resultado (ficam como estão): ${jaResultado.join(' · ')}`);
  if (gruposTq.length) {
    const ls = gruposTq.map((g) => {
      const [tqs, coleta] = g.split(' coleta ');
      const dm = String(coleta || '').slice(0, 5);
      const lista = tqs.split(',');
      const semCol = lista.filter((t) => semColetaTq.some((s) => s.startsWith(t + ' ')));
      return `• tanque ${lista.join(', ')} (coleta ${dm})` + (semCol.length === lista.length ? ' — coleta nova' : semCol.length ? ` — coleta nova: ${semCol.join(', ')}` : '');
    });
    secoes.push(`🛢️ Tanques de terra no caldo:\n${ls.join('\n')}`);
  }
  return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '1', payload: JSON.stringify({ comandos }), resumo: comandos.join(' | ').slice(0, 900),
    textoResposta: `📷 TAB${d.data ? ' de ' + d.data : ''}:\n\n${secoes.join('\n\n')}` +
      (avisos.length ? `\n\n⚠️ Confira:\n${avisos.join('\n')}` : '') +
      '\n\nResponda *sim* para registrar ou *não* para cancelar.' } }];
}
// o que a foto vai criar, em linguagem simples (a lista acima mostra so os comandos)
let oQueCria = oQueCriaTab + avisoTanques + jaTabTxt;
if (d.formulario === 'recebimento') {
  const porLoad = new Map();
  d.comandos.forEach((c) => {
    if (!porLoad.has(c.load)) porLoad.set(c.load, {});
    const o = porLoad.get(c.load);
    if (c.tipo === 'recebimento') o.lotes = c.lotes;
    if (c.tipo === 'compostas') o.grupos = c.grupos;
  });
  const linhasR = [];
  for (const [load, o] of porLoad) {
    const n = (o.grupos || []).length;
    linhasR.push(`• load ${load}: recebimento dos lotes ${o.lotes}` + (n ? ` e ${n} composta${n > 1 ? 's' : ''}:` : ' (nenhuma composta: sem marca na foto)'));
    (o.grupos || []).forEach((g, i) => linhasR.push(`     ${i + 1}ª composta = ${/[-,]/.test(g) ? 'lotes' : 'lote'} ${g}`));
  }
  oQueCria = '\n\n🧪 Registrar:\n' + linhasR.join('\n');
}
if (d.formulario === 'embarque') {
  const linhasE = d.comandos.map((c) => `• linha ${c.linha} fase ${c.fase}: load ${c.load} (item ${c.item}), amostras ${/[-,]/.test(c.amostras) ? 'A' + c.amostras.replace(/(\d+)/g, '$1').replace(/,/g, ', A').replace(/-/g, '-A') : 'A' + c.amostras}`);
  oQueCria = '\n\n🚢 ' + d.navio + ':\n' + linhasE.join('\n');
}
if (d.formulario === 'recebimento_nfc') {
  oQueCria = '\n\n🧪 Recebimento NFC — o que isso registra:\n' + d.comandos.map((c) => '• load ' + c.load + ' (' + c.fabrica + ', item 129): ' + c.resumo).join('\n');
}
const num = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣', '6️⃣', '7️⃣', '8️⃣', '9️⃣', '🔟'];
const lista = linhas.map((l, i) => `${num[i] || (i + 1) + '.'} ${l}`).join('\n');
const semLista = ['recebimento', 'embarque'].includes(d.formulario);
const texto = (semLista ? `📷 ${d.formulario === 'embarque' ? 'Embarque' : 'Recebimento'}${d.data ? ' de ' + d.data : ''}:${oQueCria}` : `📷 Li o laudo de ${titulo}${d.data ? ' (data ' + d.data + ')' : ''}:\n\n${lista}${oQueCria}`) +
  (avisos.length ? `\n\n⚠️ Confira:\n${avisos.join('\n')}` : '') +
  `\n\nResponda *sim* para registrar ${linhas.length > 1 ? 'tudo' + (d.formulario === 'recebimento_nfc' ? '' : ', na ordem,') : 'isso'} ou *não* para cancelar.`;
return [{ json: { numero: d.numero, nomeContato: d.nomeContato, salvar: '1', payload: JSON.stringify({ comandos }), resumo: comandos.join(' | ').slice(0, 900), textoResposta: texto } }];

// Foto de laudo: uma pendência com vários comandos vira um item por comando (executados em ordem).
const j = $input.first().json;
const lista = Array.isArray(j.reenviarComandos) && j.reenviarComandos.length ? j.reenviarComandos : [j.reenviarComando];
return lista.map((comando) => ({ json: { ...j, reenviarComando: comando } }));

// Gravação já feita no node anterior. Monta a resposta do recebimento de NFC (uma mensagem só, mesmo com vários loads).
// Os resultados que vieram na linha (foto do laudo) aparecem como no laudo; o banco guarda também o valor multiplicado.
const r = $input.first().json;
const item = $('Interpretar comando').first().json;
// o banco recusou (registrar_recebimento_nfc, 046): nada foi gravado
if (r.erro) return [{ json: { ...item, textoResposta: '❌ ' + r.erro + ' Nada foi gravado.' } }];
const exp = (d) => '10^' + d;
const blocos = Array.isArray(item.blocos) && item.blocos.length ? item.blocos : [{ load: item.load, fabrica: item.fabrica, item: item.item, itens: [] }];
const conflitos = Array.isArray(r.conflitos) ? r.conflitos : [];
const g = Array.isArray(r.gravados) ? r.gravados : [];
const fmt = (x) => (x.sinal === '=' ? '' : x.sinal) + String(Number(Number(x.valor).toFixed(6))).replace('.', ',');
const resDe = new Map();
const dataDe = new Map();
blocos.forEach((b) => b.itens.forEach((it) => {
  const k = b.load + '|' + it.lote + '|' + it.amostra;
  dataDe.set(k, it.data);
  if (Array.isArray(it.resultados) && it.resultados.length) resDe.set(k, it.resultados.map((x) => x.analise + ' ' + fmt(x)).join(' · '));
}));
const nota = (x, temRes) => {
  if (x.novo) return '';
  if (x.era !== null && x.era !== undefined && Number(x.era) !== Number(x.diluicao)) return ' (corrigido: era ' + exp(x.era) + ')';
  return temRes ? '' : ' (já estava assim)';
};
const resultados = (load, x) => { const t = resDe.get(load + '|' + x.lote + '|' + x.amostra); return t ? ' — ' + t : ''; };

if (blocos.length === 1) {
  if (conflitos.length) {
    return [{ json: { ...item, textoResposta:
      '❌ O load ' + item.load + ' (item ' + item.item + ') já está cadastrado com a fábrica ' + conflitos[0].cadastrada + ', não ' + item.fabrica + '. Nada foi gravado.' } }];
  }
  const linhas = ['✅ Recebimento NFC do load ' + item.load + ' (item ' + item.item + ', fábrica ' + item.fabrica + ') registrado por ' + item.nomeContato + '.', ''];
  g.forEach((x) => { const t = resultados(item.load, x); linhas.push('lote ' + x.lote + ' · ' + x.amostra + ' · ' + exp(x.diluicao) + nota(x, !!t) + t); });
  if (Number(r.recalculados) > 0) linhas.push('↻ ' + r.recalculados + ' resultado(s) de C.T/B.L já gravado(s) foram recalculados com a nova diluição.');
  if (item.fabricaLida) linhas.push('ℹ️ Li a fábrica como "' + item.fabricaLida + '" e entendi ' + item.fabrica + '. Se estiver errado, avise.');
  linhas.push('Data: ' + item.dataRecebimento);
  return [{ json: { ...item, textoResposta: linhas.join('\n') } }];
}

// vários loads (foto): uma mensagem com tudo
const comConflito = new Set(conflitos.map((x) => String(x.load)));
const nRes = Number(r.resultados_gravados) || 0;
const linhas = ['✅ Recebimento NFC registrado por ' + item.nomeContato + ': ' + g.length + ' lote' + (g.length === 1 ? '' : 's') + ' em ' + (blocos.length - comConflito.size) + ' load' + (blocos.length - comConflito.size === 1 ? '' : 's') +
  (nRes ? ', ' + nRes + ' resultado' + (nRes === 1 ? '' : 's') + ' de C.T/B.L' : '') + '.', ''];
blocos.forEach((b) => {
  if (comConflito.has(String(b.load))) {
    const cad = conflitos.find((x) => String(x.load) === String(b.load)).cadastrada;
    linhas.push('❌ load ' + b.load + ' (item ' + b.item + '): já está cadastrado com a fábrica ' + cad + ', não ' + b.fabrica + '. Nada foi gravado desse load.');
    return;
  }
  linhas.push('load ' + b.load + ' (' + b.fabrica + ', item ' + b.item + '):');
  g.filter((x) => String(x.load) === String(b.load)).forEach((x) => {
    const t = resultados(b.load, x);
    linhas.push('  lote ' + x.lote + ' · ' + x.amostra + ' · ' + exp(x.diluicao) + ' · ' + (dataDe.get(b.load + '|' + x.lote + '|' + x.amostra) || '') + nota(x, !!t) + t);
  });
});
if (Number(r.recalculados) > 0) linhas.push('↻ ' + r.recalculados + ' resultado(s) de C.T/B.L já gravado(s) foram recalculados com a nova diluição.');
(item.fabricasLidas || []).forEach((f) => linhas.push('ℹ️ Li a fábrica como "' + f.lido + '" e entendi ' + f.sigla + '. Se estiver errado, avise.'));
return [{ json: { ...item, textoResposta: linhas.join('\n') } }];

// Pergunta antes de gravar C.T / B.L do recebimento NFC. O chat mostra o número como no laudo; o banco grava também o
// valor multiplicado pela diluição do lote (10 elevado a 1 acrescenta um zero), que aparece no Power BI.
// A gravação acontece depois do "sim", em "BD · Gravar contagens NFC".
const ROTULO = { CT: 'C.T 48h', BL72: 'B.L 72h', BL120: 'B.L 120h' };
// Com "todos", o banco acrescenta os lotes que saem na data e ainda não têm resultado (via_todos) e devolve sempre uma linha.
const todasLinhas = $input.all().map((i) => i.json);
const rows = todasLinhas.filter((r) => r.lote !== undefined && r.lote !== null);
const item = $('Interpretar comando').first().json;
const erro = (t) => [{ json: { ...item, salvar: false, payload: '{}', resumo: '', textoResposta: t } }];

const loadsAchados = todasLinhas.length ? Number(todasLinhas[0].loads_encontrados) : 0;
if (loadsAchados === 0) {
  return erro(`❌ Load ${item.load} (NFC, item 129) não encontrado. Registre o recebimento primeiro: recebimento nfc load ${item.load} fab aqa item 129 lote 10 past 10 elevado a 1`);
}
const faltam = rows.filter((r) => r.alvo_id === null || r.alvo_id === undefined);
if (faltam.length) {
  const lista = faltam.map((r) => `${r.lote} (${r.amostra})`).join(', ');
  return erro(`❌ ${faltam.length === 1 ? 'Lote' : 'Lotes'} ${lista} não ${faltam.length === 1 ? 'foi registrado' : 'foram registrados'} no recebimento NFC do load ${item.load}. Nada foi gravado.`);
}
const porLote = new Map(rows.map((r) => [`${r.lote}|${r.amostra}`, r]));
const num = (n) => String(Number(n.toFixed(6)));
const fmt = (sinal, valor) => `${sinal === '=' ? '' : sinal}${num(valor)}`;
const nomeAn = ROTULO[item.analise];
const viaTodos = rows.filter((r) => r.via_todos === true || r.via_todos === 't');
const infos = [];
if (item.todos) {
  const fora = (item.excluidos || []).map((x) => `${x.lote}${x.amostra ? ' ' + x.amostra : ''}`);
  if (!viaTodos.length && !item.grupos.length) {
    return erro(`ℹ️ Nenhum lote do NFC load ${item.load} com ${nomeAn} para ${item.todos.data} sem resultado${fora.length ? ` (fora: ${fora.join(', ')})` : ''}. Nada foi gravado.` +
      `\nPara corrigir um lote que já tem resultado, mande o lote: ${item.analise.toLowerCase()} nfc load ${item.load} lote 10 past deu 14`);
  }
  if (viaTodos.length) infos.push(`Todos de ${item.todos.data} sem resultado: ${viaTodos.length} lote${viaTodos.length > 1 ? 's' : ''} com ${fmt(item.todos.sinal, item.todos.valor)} lido.`);
  else infos.push(`ℹ️ Nenhum outro lote com ${nomeAn} para ${item.todos.data} sem resultado.`);
  if (fora.length) infos.push(`Fora do "todos": lote${fora.length > 1 ? 's' : ''} ${fora.join(', ')}`);
}
const gruposTodos = [];
for (const amostra of ['past', 'fresh']) {
  const lotes = viaTodos.filter((r) => r.amostra === amostra).map((r) => Number(r.lote));
  if (lotes.length) gruposTodos.push({ lotes, amostra, sinal: item.todos.sinal, valor: item.todos.valor });
}
const itens = [];
const linhas = [];
const correcoes = [];
for (const g of [...gruposTodos, ...item.grupos]) {
  for (const lote of g.lotes) {
    const r = porLote.get(`${lote}|${g.amostra}`);
    const dil = Number(r.diluicao);
    const final = Number((g.valor * 10 ** dil).toFixed(6));
    itens.push({ analise: item.analise, id: Number(r.alvo_id), sinal: g.sinal, valor: final, lido: g.valor });
    if (r.atual !== null && r.atual !== undefined && r.atual !== '') correcoes.push(`${lote} ${g.amostra} (era ${r.atual})`);
    linhas.push(`lote ${lote} · ${g.amostra}: ${fmt(g.sinal, g.valor)}`);
  }
}
const avisos = [...infos];
if (correcoes.length) avisos.push(`⚠️ Corrige resultado anterior: ${correcoes.join(', ')}`);

const resumo = `${nomeAn} — NFC load ${item.load}:\n${linhas.join('\n')}` + (avisos.length ? `\n${avisos.join('\n')}` : '');
return [{ json: { ...item, salvar: true,
  payload: JSON.stringify({ acao: 'contagem_nfc', itens }),
  resumo,
  textoResposta: `❓ Gravar ${nomeAn} — NFC load ${item.load}?\n${linhas.join('\n')}` + (avisos.length ? `\n${avisos.join('\n')}` : '') + `\n\nResponda *sim* ou *não*.` } }];

// Corrigir/apagar coleta (banco já executou). Diz o que foi feito, ou por que não pôde.
const r = $input.first().json;
const item = $('Interpretar comando').first().json;
const e = r.estado;
const onde = item.origem === 'terra' ? 'tanque de terra ' + item.tanque : 'tanque ' + item.tanque + ' do navio ' + item.navio;
const verbo = item.modo === 'apagar' ? 'apagar' : 'trocar';
let texto;
if (!e) {
  texto = '❌ Não achei a coleta do ' + onde + (item.dataColeta ? ' em ' + item.dataColeta : ' nos últimos 7 dias') + '. Confira o número e a data (escreva *comandos coleta*). Nada foi alterado.';
} else if (!e.permitido) {
  texto = '❌ A coleta do ' + onde + ' (' + e.data + ') foi registrada por outra pessoa. Só quem registrou, um Analista ou um Admin pode alterar. Nada foi alterado.';
} else if (e.tem_analise || e.tem_drop || e.tem_teste || e.tem_desvio) {
  const o = e.tem_analise ? 'análise' : (e.tem_drop ? 'drop concluído' : (e.tem_teste ? 'TAB' : 'desvio de drop'));
  texto = '❌ O ' + onde + ' (' + e.data + ') já tem ' + o + ' registrado(a), então não dá para ' + verbo + ' a coleta. Peça a um Admin. Nada foi alterado.';
} else if (e.duplicada) {
  texto = '❌ O tanque ' + item.novoTanque + ' já está registrado nessa mesma data (' + e.data + '). Nada foi alterado.';
} else if (item.modo === 'apagar' && Number(r.apagados) > 0) {
  texto = '✅ Coleta apagada: ' + onde + ' (' + e.data + '). Os drops e o arquivo desse tanque saíram junto; fica tudo guardado e um Admin pode recuperar.';
} else if (item.modo === 'corrigir' && Number(r.atualizados) > 0) {
  texto = '✅ Coleta corrigida: tanque ' + item.tanque + ' → ' + item.novoTanque + ' (' + (item.origem === 'terra' ? 'terra' : 'navio ' + item.navio) + ', ' + e.data + '). Os drops e o arquivo acompanharam a troca.';
} else {
  texto = '❌ Não consegui alterar essa coleta. Nada foi alterado.';
}
return [{ json: { ...item, textoResposta: texto } }];

// "Todos os tanques": <1 nas 3 placas de cada leitura que sai na data e ainda não tem placas; as exceções levam as
// placas ditas (ou ficam de fora). Grava tudo com um "sim" (placas_lote, em "BD · Executar placas da foto"), sem abrir
// desvio: o não ok volta na resposta com o comando pronto, como na foto do laudo.
const item = $('Interpretar comando').first().json;
const todas = $input.all().map((i) => i.json);
const rows = todas.filter((r) => r.analise_id !== null && r.analise_id !== undefined);
const erro = (t) => [{ json: { ...item, salvar: false, tipoPendencia: 'PLACAS', payload: '{}', resumo: '', textoResposta: t } }];
const onde = item.navio ? `do navio ${item.navio}` : 'de terra';
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const ymd = (d) => String(d).split('/').reverse().join('');
const antecipada = ymd(item.data) > ymd(hoje);

if (item.navio && !Number((todas[0] || {}).navios_encontrados)) {
  return erro(`❌ Navio ${item.navio} não encontrado. Confira o nome e a viagem (ex.: O.SKY 123). Nada foi gravado.`);
}
if (!rows.length) {
  return erro(`ℹ️ Nenhuma leitura de ${item.rotulo} dos tanques ${onde} para ${item.data}. Nada foi gravado.`);
}

const SEM = [1, 2, 3].map((placa) => ({ placa, sinal: '<', valor: 1 }));
const txt = (p) => (p.sinal === '=' ? String(p.valor) : p.sinal + p.valor);
const nomeL = (r) => `${r.tanque} ${String(r.frasco).toLowerCase()}${r.repeticao ? ' (repetição)' : ''}`;
const cmd = item.sub === 'CT' ? 'ct' : item.sub === 'BL' ? (item.etapa === 'pre' ? 'bl72' : 'bl120')
  : `wort ${item.metodo === 'Superficie' ? 'superficie' : 'profundidade'} ${item.etapa === 'pre' ? '120h' : '240h'}`;

const comPlacas = [];
const fora = [];
for (const e of item.excecoes || []) {
  const alvo = rows.filter((r) => r.tanque === e.tanque && (!e.frasco || r.frasco === e.frasco));
  if (!alvo.length) {
    return erro(`❌ O tanque ${e.tanque}${e.frasco ? ' (' + e.frasco + ')' : ''} não tem ${item.rotulo} para ${item.data} ${item.navio ? 'no navio ' + item.navio : 'em terra'}. Nada foi gravado.`);
  }
  if (e.placas) {
    if (alvo.length > 1) {
      return erro(`⚠️ O tanque ${e.tanque} (${e.frasco}) tem ${alvo.length} leituras de ${item.rotulo} para ${item.data} (coletas ${alvo.map((r) => r.data_coleta).join(', ')}).` +
        `\nMande esse tanque pelo comando de placas, com *coleta dd/mm/aaaa* no fim. Nada foi gravado.`);
    }
    comPlacas.push({ r: alvo[0], placas: e.placas });
  } else {
    fora.push(...alvo);
  }
}
const separados = new Set([...comPlacas.map((x) => x.r.analise_id), ...fora.map((r) => r.analise_id)]);
const jaLidas = rows.filter((r) => !separados.has(r.analise_id) && Number(r.ja_lidas) > 0);
const doTodos = rows.filter((r) => !separados.has(r.analise_id) && !(Number(r.ja_lidas) > 0));
if (!doTodos.length && !comPlacas.length) {
  return erro(`ℹ️ As leituras de ${item.rotulo} dos tanques ${onde} para ${item.data} já têm placas${fora.length ? ' ou ficaram de fora' : ''}. Nada foi gravado.` +
    `\nPara corrigir um tanque, mande pelo comando de placas: ${cmd} do tanque ${rows[0].tanque}${item.navio ? ' navio ' + item.navio : ''} ${String(rows[0].frasco).toLowerCase()} 0,0,1`);
}
if (doTodos.length + comPlacas.length > 150) return erro('❌ Mais de 150 leituras de uma vez. Separe por navio ou por data. Nada foi gravado.');

const limiteDe = (r) => (r.limite === null || r.limite === undefined ? null : Number(r.limite));
const acima = (r, placas) => { const lim = limiteDe(r); return placas.some((p) => p.sinal === '>' || (lim !== null && p.sinal === '=' && p.valor > lim)); };
const naoOk = comPlacas.filter((x) => acima(x.r, x.placas));
const comandoDe = (x) => `${cmd} do tanque ${x.r.tanque}${item.navio ? ' navio ' + item.navio : ''} ${String(x.r.frasco).toLowerCase()} ${x.placas.map(txt).join(',')} coleta ${x.r.data_coleta}`;

const cab = `${item.rotulo}, tanques ${onde}, leitura de ${item.data}${antecipada ? ' (⏩ antecipada)' : ''}`;
const linhas = [];
if (doTodos.length) linhas.push(`<1 nas 3 placas (${doTodos.length} leitura${doTodos.length > 1 ? 's' : ''}): ${doTodos.map(nomeL).join(', ')}`);
for (const x of comPlacas) {
  const marca = acima(x.r, x.placas) ? '🚨 não ok' : (limiteDe(x.r) === null ? 'ℹ️ sem limite cadastrado' : '✅ ok');
  linhas.push(`${nomeL(x.r)}: ${x.placas.map(txt).join(', ')} → ${marca}`);
}
if (fora.length) linhas.push(`Fora: ${fora.map(nomeL).join(', ')}`);
const infoJa = jaLidas.length ? `\nℹ️ Já tinham placas (ficam como estão): ${jaLidas.map(nomeL).join(', ')}` : '';

const listaNaoOk = naoOk.map((x) => `• ${nomeL(x.r)}: ${x.placas.map(txt).join(', ')}${x.r.tem_desvio ? ' (já tem desvio)' : ''}` +
  (x.r.tem_desvio || x.r.repeticao ? '' : `\n   para abrir o desvio, mande: ${comandoDe(x)}`)).join('\n');
const payload = { acao: 'placas_lote', itens: [
  ...doTodos.map((r) => ({ analise_id: Number(r.analise_id), etapa: item.etapa, placas: SEM })),
  ...comPlacas.map((x) => ({ analise_id: Number(x.r.analise_id), etapa: item.etapa, placas: x.placas })),
] };
return [{ json: { ...item, salvar: true, tipoPendencia: 'PLACAS', payload: JSON.stringify(payload),
  resumo: `✅ Gravado: ${cab}\n${linhas.join('\n')}` + (naoOk.length ? `\n\n🚨 Não ok (nenhum desvio foi aberto):\n${listaNaoOk}` : ''),
  textoResposta: `❓ Gravar ${cab}?\n${linhas.join('\n')}${infoJa}` +
    (naoOk.length ? '\n\nNão abro desvio sozinho: depois do sim, te mando o comando de cada não ok.' : '') +
    '\n\nResponda *sim* para gravar ou *não* para cancelar.' } }];

// Coliformes da foto já gravados no node anterior. Uma mensagem com o que entrou; se alguma composta deu positivo,
// pergunta se abre lote a lote para a confirmação (pendência TAB, ação "abrir", a mesma do "coliformes #5 em confirmação").
const r = $input.first().json;
const item = $('Interpretar comando').first().json;
const linhas = Array.isArray(r.linhas) ? r.linhas : [];
const naoAchadas = Array.isArray(r.nao_achadas) ? r.nao_achadas : [];
const nome = (x) => `#${x.composta} ` + (x.origem === 'embarque' ? `${x.rotulo} (A${(x.lotes || []).join(',A')})` : `load ${x.load} (${(x.lotes || []).join(',')})`);
const gravou = linhas.filter((x) => x.gravou);
const grupo = (acao) => gravou.filter((x) => x.acao === acao);
const partes = [];
const lista = (xs) => xs.map((x) => `• ${x.data}: ${nome(x)}${x.era ? ` (era ${x.era})` : ''}`).join('\n');
if (grupo('feito').length) partes.push(`🧪 No caldo:\n${lista(grupo('feito'))}`);
if (grupo('negativo').length) partes.push(`✅ Lidos, negativos:\n${lista(grupo('negativo'))}`);
const positivos = grupo('positivo');
if (positivos.length) partes.push(`🚨 Positivos:\n${lista(positivos)}`);
const ja = linhas.filter((x) => !x.gravou);
if (ja.length) partes.push(`ℹ️ Sem mudança (já estava assim ou aberta lote a lote): ${ja.map((x) => '#' + x.composta).join(', ')}`);
if (naoAchadas.length) partes.push(`⚠️ Não achei a composta de: ${naoAchadas.map((x) => x.id ? '#' + x.id : `load ${x.load} (${(x.lotes || []).join(',')})`).join(', ')}. Nada foi gravado nessas.`);
let texto = `✅ Coliformes da foto gravados por ${item.nomeContato}.` + (partes.length ? '\n\n' + partes.join('\n\n') : '');
let payload = '{}';
let resumo = '';
if (positivos.length) {
  const ids = [...new Set(positivos.map((x) => Number(x.teste)))];
  const quais = positivos.map((x) => '#' + x.composta).join(', ');
  texto += `\n\n❓ ${positivos.length > 1 ? 'As compostas ' + quais + ' deram' : 'A composta ' + quais + ' deu'} positivo. Abrir ${positivos.length > 1 ? 'as compostas' : 'a composta'} lote a lote para a confirmação? Cada lote vai para o caldo hoje e estria amanhã. Responda *sim* ou *não*.`;
  payload = JSON.stringify({ acao: 'abrir', tipo: 'COLIFORMES', ids });
  resumo = `✅ ${positivos.length > 1 ? 'Compostas ' + quais + ' abertas' : 'Composta ' + quais + ' aberta'} lote a lote para a confirmação de Coliformes (caldo hoje, estria amanhã).`;
}
return [{ json: { ...item, salvar: positivos.length > 0, tipoPendencia: 'TAB', payload, resumo, textoResposta: texto } }];

// A gravação do cargo já foi feita pelas funções do banco. Mostra a confirmação ou o motivo da recusa.
const r = $input.first().json;
const item = $('Interpretar comando').first().json;
const res = String(r.resultado || '');
if (res === 'ok') return [{ json: { ...item } }];
return [{ json: { ...item, textoResposta: '❌ ' + res.replace(/^erro:\s*/, '') + ' Nada foi alterado.' } }];

// Corrigir/apagar recebimento (o banco já executou pela recebimento_pelo_bot, 037). Diz o que mudou, ou por que não pôde.
const item = $('Interpretar comando').first().json;
let r = $input.first().json.r;
if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) { r = null; } }
let texto;
if (!r) {
  texto = '❌ Não consegui alterar o recebimento. Nada foi alterado.';
} else if (!r.ok) {
  texto = '❌ ' + r.erro + ' Nada foi alterado.';
} else if (item.acao === 'load') {
  const a = r.antes || {}, b = r.depois || {};
  const mud = [];
  if (a.numero !== b.numero) mud.push('load ' + a.numero + ' → ' + b.numero);
  if (a.item !== b.item) mud.push('item ' + a.item + ' → ' + b.item);
  if (a.fabrica !== b.fabrica) mud.push('fábrica ' + (a.fabrica || '-') + ' → ' + b.fabrica);
  const n = Number(r.lotes) || 0;
  texto = '✅ Load corrigido: ' + mud.join(', ') + '. Vale para ' + (n === 1 ? 'o lote' : 'os ' + n + ' lotes') + ' dele; fica no histórico.';
} else if (item.acao === 'lote') {
  const a = r.antes || {}, b = r.depois || {};
  const mud = [];
  if (a.lote !== b.lote) mud.push('lote ' + a.lote + ' → ' + b.lote);
  if (a.data_recebimento !== b.data_recebimento) mud.push('data ' + a.data_recebimento + ' → ' + b.data_recebimento);
  texto = '✅ Recebimento corrigido no load ' + r.load + ': ' + mud.join(', ') + '. Fica no histórico.';
} else {
  texto = '✅ Lote ' + r.lote + ' do load ' + r.load + ' apagado. Fica guardado e um Admin pode recuperar.' + (Number(r.restam) === 0 ? ' O load ficou sem lotes.' : '');
}
return [{ json: { ...item, textoResposta: texto } }];

// TAB da foto (o banco já gravou): diz o que ficou positivo (já confirmado), negativo, o que já tinha resultado e o que não achou.
const item = $('Interpretar comando').first().json;
const r = $input.first().json;
const lista = (v) => { if (Array.isArray(v)) return v; if (typeof v === 'string') { try { return JSON.parse(v) || []; } catch (e) { return []; } } return []; };
const linhas = lista(r.linhas);
const naoAchadas = lista(r.nao_achadas);
const compacta = (ns) => { const s = [...new Set((ns || []).map(Number))].sort((a, b) => a - b); const o = []; for (let i = 0; i < s.length; i++) { let j = i; while (j + 1 < s.length && s[j + 1] === s[j] + 1) j++; o.push(i === j ? String(s[i]) : s[i] + '-' + s[j]); i = j; } return o.join(','); };
const porLoad = (ls) => {
  const m = new Map();
  ls.forEach((x) => { const k = `${x.load || '?'}|${x.item || ''}`; if (!m.has(k)) m.set(k, []); m.get(k).push(x); });
  const out = [];
  for (const [k, l] of m) { const [load, it] = k.split('|'); out.push(`• load ${load}${it ? ` (item ${it})` : ''}: ` + l.map((x) => `#${x.composta} (${compacta(x.lotes)})`).join(' · ')); }
  return out.join('\n');
};
const pos = linhas.filter((x) => x.gravou && x.acao === 'positivo');
const neg = linhas.filter((x) => x.gravou && x.acao === 'negativo');
const ja = linhas.filter((x) => !x.gravou);
const partes = [];
if (pos.length) partes.push(`🚨 TAB positivo, confirmado (${pos.length}):\n${porLoad(pos)}`);
if (neg.length) partes.push(`✅ TAB negativo (${neg.length}):\n${porLoad(neg)}`);
if (ja.length) partes.push(`ℹ️ Já tinham resultado, ficaram como estavam: ${ja.map((x) => `#${x.composta}`).join(', ')}`);
if (naoAchadas.length) partes.push(`⚠️ Não achei a composta: ${naoAchadas.map((x) => x.id ? `#${x.id}` : `load ${x.load} (${compacta(x.lotes)})`).join(', ')}`);
const texto = (pos.length || neg.length)
  ? `📷 TAB gravado:\n\n${partes.join('\n\n')}`
  : `📷 Nada novo para gravar no TAB.${partes.length ? '\n\n' + partes.join('\n\n') : ''}`;
return [{ json: { ...item, textoResposta: texto } }];

// Corrigir resultado de C.T/B.L (039). Prévia: mostra "era → novo" e pede sim (a pendência já foi guardada pelo banco).
// Gravar (depois do sim): confirma o que mudou. Erro da regra: diz por quê, sem mudar nada.
const item = $('Interpretar comando').first().json;
let r = $input.first().json.r;
if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) { r = null; } }
let texto;
if (!r) {
  texto = '❌ Não consegui corrigir o resultado. Nada foi alterado.';
} else if (!r.ok) {
  texto = '❌ ' + r.erro + ' Nada foi alterado.';
} else if (r.fase === 'previa') {
  texto = '✏️ Corrigir ' + r.resumo + '.' + (r.motivo ? '\nMotivo: ' + r.motivo : '') + '\n\nResponda *sim* para gravar ou *não* para cancelar.';
} else {
  texto = '✅ Resultado corrigido: ' + r.resumo + '. Fica no histórico.\n\nPor: ' + (item.nomeContato || 'Desconhecido');
}
return [{ json: { ...item, textoResposta: texto } }];
